# ------------------------------------------------------------------ 3. local neighbourhoods and per-gene distance profiles
def knn_overlap(Sa, Sb, k):
    out = []
    for S in (Sa, Sb):
        S = S.copy()
        np.fill_diagonal(S, -np.inf)
        nb = np.argpartition(-S, k, axis=1)[:, :k]
        M = np.zeros(S.shape, dtype=bool)
        M[np.arange(len(S))[:, None], nb] = True
        out.append(M)
    return (out[0] & out[1]).sum(1) / k


def row_ranks(S):
    """Per-gene centred ranks of the similarity profile to all other genes of the set."""
    n = len(S)
    r = S[~np.eye(n, dtype=bool)].reshape(n, n - 1).argsort(1).argsort(1).astype(float)
    return r - r.mean(1, keepdims=True)


def row_corr(ra, rb):
    """Per-gene Spearman correlation of two models' distance profiles."""
    return (ra * rb).sum(1) / np.sqrt((ra ** 2).sum(1) * (rb ** 2).sum(1))


for sname, idx in SETS.items():
