def nonint_frac(X, init_sq, w):
    W = w.sum()
    mu = (w[:, None] * X).sum(0) / W
    csq = (w * (X ** 2).sum(1)).sum() / W - mu @ mu
    return 1 - init_sq * (1 - 1 / len(X)) / csq


