def add(name, value, ci=(None, None), method=""):
    est.append({"name": name, "value": None if value is None else round(float(value), 4),
                "ci_low": None if ci[0] is None else round(float(ci[0]), 4),
                "ci_high": None if ci[1] is None else round(float(ci[1]), 4),
                "method_of_uncertainty": method})


BOOT = ("gene bootstrap: genes resampled with replacement (the same draw for all model pairs), pairs of "
        "copies of one gene dropped; percentile 95%% CI, B=%d")
PERM = "one-sided gene-label permutation p-value (%d permutations of the MaxToki gene-row correspondence); no CI"
NULLM = "mean of the gene-label permutation null; interval = its 2.5-97.5 percentiles (%d permutations)"

for set_name in ("union", "lung", "immune", "external_lung"):
    genes = union if set_name == "union" else sorted(panels[set_name])
    geo = Geometry(tables(genes))
    B = B_UNION if set_name == "union" else B_PANEL
    pt = geo.point()
    bs = geo.boot(B, rng)
    log(f"{set_name}: bootstrap done")
    for met in ("rsa", "dcka"):
        for pr in ("MG", "MS", "GS"):
            add(f"{met}_{pr}_{set_name}", pt[met][pr], pctl([r[met][pr] for r in bs]), BOOT % B)
        add(f"{met}_diff_MG_minus_MS_{set_name}", pt[met]["MG"] - pt[met]["MS"],
            pctl([r[met]["MG"] - r[met]["MS"] for r in bs]), BOOT % B)
        add(f"{met}_ratio_MS_over_MG_{set_name}", pt[met]["MS"] / pt[met]["MG"],
            pctl([r[met]["MS"] / r[met]["MG"] for r in bs]), BOOT % B)
    if set_name == "union":
        rr = pt["rsa"]
        add("rsa_partial_MG_given_S_union", partial(rr["MG"], rr["MS"], rr["GS"]),
            pctl([partial(r["rsa"]["MG"], r["rsa"]["MS"], r["rsa"]["GS"]) for r in bs]), BOOT % B)
        add("rsa_partial_MS_given_G_union", partial(rr["MS"], rr["MG"], rr["GS"]),
            pctl([partial(r["rsa"]["MS"], r["rsa"]["MG"], r["rsa"]["GS"]) for r in bs]), BOOT % B)
    nperm = N_PERM if set_name == "union" else N_PERM_PANEL
    pm = geo.perm(nperm, rng)
    log(f"{set_name}: permutations done")
    for met in ("rsa", "dcka"):
        for pr in ("MG", "MS"):
            add(f"{met}_{pr}_{set_name}_perm_p", perm_p(pm[met][pr], pt[met][pr]), (None, None), PERM % nperm)
            if set_name == "union":
                add(f"{met}_{pr}_union_perm_null_mean", np.mean(pm[met][pr]), pctl(pm[met][pr]), NULLM % nperm)
    del geo

# ---- union set: cross-validated CCA (paper-style CCA on 20 whitened PCs, scored on held-out genes)
X = tables(union); n = len(union)
Z = {k: pc_scores(v, K_PCA) for k, v in X.items()}
cv = {}
for pr in ("MG", "MS"):
    Q = np.zeros(n); H = np.zeros(n); C = np.zeros(n)
    for s in range(N_SPLIT):
        fold = np.random.default_rng(SEED + s).permutation(n) % N_FOLD
        q, h, c = cv_cca(Z[pr[0]], Z[pr[1]], fold)
        Q += q / N_SPLIT; H += h / N_SPLIT; C += c / N_SPLIT
    cv[pr] = (Q, H, C)
cvb = {"MG": [], "MS": []}
for _ in range(B_CCA):
    b = rng.integers(0, n, n)
    for pr in ("MG", "MS"):
        cvb[pr].append((cv[pr][0][b].mean(), cv[pr][1][b].mean()))
cvb = {k: np.array(v) for k, v in cvb.items()}
cvn = {"MG": [], "MS": []}
for _ in range(N_PERM_CCA):
    p = rng.permutation(n); fold = rng.permutation(n) % N_FOLD
    for pr in ("MG", "MS"):
        q, h, _ = cv_cca(Z[pr[0]][p], Z[pr[1]], fold)
        cvn[pr].append((q.mean(), h.mean()))
cvn = {k: np.array(v) for k, v in cvn.items()}
log("CV-CCA done")
BC = ("gene bootstrap of per-gene held-out scores (averaged over %d random 5-fold splits; CCA maps held "
      "fixed), percentile 95%% CI, B=%d" % (N_SPLIT, B_CCA))
for j, lab in ((0, "cvcca_meancorr10"), (1, "cvcca_top1")):
    for pr in ("MG", "MS"):
        add(f"{lab}_{pr}_union", cv[pr][j].mean(), pctl(cvb[pr][:, j]), BC)
        add(f"{lab}_{pr}_union_perm_p", perm_p(cvn[pr][:, j], cv[pr][j].mean()), (None, None), PERM % N_PERM_CCA)
        add(f"{lab}_{pr}_union_perm_null_mean", cvn[pr][:, j].mean(), pctl(cvn[pr][:, j]), NULLM % N_PERM_CCA)
    add(f"{lab}_diff_MG_minus_MS_union", cv["MG"][j].mean() - cv["MS"][j].mean(),
        pctl(cvb["MG"][:, j] - cvb["MS"][:, j]), BC)
    add(f"{lab}_ratio_MS_over_MG_union", cv["MS"][j].mean() / cv["MG"][j].mean(),
        pctl(cvb["MS"][:, j] / cvb["MG"][:, j]), BC)
add("cvcca_top1_chance_union", cv["MG"][2].mean(), (None, None), "deterministic: 1 / held-out fold size")

# ---- union set: estimators that are biased without a null (in-sample CCA as in the paper; raw linear CKA)
ins = {pr: cca_fit(Z[pr[0]], Z[pr[1]])[4][:N_CC].mean() for pr in ("MG", "MS")}
ins_null = {pr: [cca_fit(Z[pr[0]][rng.permutation(n)], Z[pr[1]])[4][:N_CC].mean() for _ in range(N_PERM_CCA)]
            for pr in ("MG", "MS")}
Hc = np.eye(n) - 1.0 / n
KC = {k: Hc @ (v @ v.T) @ Hc for k, v in X.items()}


def lcka(Ka, Kb):
    return float((Ka * Kb).sum() / np.sqrt((Ka * Ka).sum() * (Kb * Kb).sum()))


lck = {pr: lcka(KC[pr[0]], KC[pr[1]]) for pr in ("MG", "MS")}
lck_null = {pr: [] for pr in ("MG", "MS")}
for _ in range(N_PERM_CCA):
    p = rng.permutation(n); km = KC["M"][np.ix_(p, p)]
    for pr in ("MG", "MS"):
        lck_null[pr].append(lcka(km, KC[pr[1]]))
for pr in ("MG", "MS"):
    add(f"insample_cca_meancorr10_{pr}_union", ins[pr], (None, None),
        "point estimate only (in-sample, as in the source paper); see its permutation-null entry")
    add(f"insample_cca_meancorr10_{pr}_union_perm_null_mean", np.mean(ins_null[pr]), pctl(ins_null[pr]),
        NULLM % N_PERM_CCA)
    add(f"raw_linear_cka_{pr}_union", lck[pr], (None, None),
        "point estimate only (biased estimator); see its permutation-null entry")
    add(f"raw_linear_cka_{pr}_union_perm_null_mean", np.mean(lck_null[pr]), pctl(lck_null[pr]), NULLM % N_PERM_CCA)
log("in-sample CCA / raw CKA done")


# ---- sensitivity analyses (point estimates, union set)
def rsa_pt(A, B):
    iu = np.triu_indices(len(A), 1)
    return float(spearmanr(centered_cos(A)[iu], centered_cos(B)[iu])[0])


def drop_pcs(A, k):
    c = A - A.mean(0)
    U, s, Vt = np.linalg.svd(c, full_matrices=False)
    return c - (U[:, :k] * s[:k]) @ Vt[:k]


Xr = tables(union, scgpt_ln=False)
sens = {"rsa_MS_scgpt_without_layernorm": rsa_pt(Xr["M"], Xr["S"]),
        "rsa_GS_scgpt_without_layernorm": rsa_pt(Xr["G"], Xr["S"]),
        "rsa_euclidean_MG": float(spearmanr(pdist(X["M"]), pdist(X["G"]))[0]),
        "rsa_euclidean_MS": float(spearmanr(pdist(X["M"]), pdist(X["S"]))[0])}
for k in (10, 20, 50):
    P = {kk: pc_scores(v, k, whiten=False) for kk, v in X.items()}
    sens[f"rsa_MG_pca{k}"] = rsa_pt(P["M"], P["G"]); sens[f"rsa_MS_pca{k}"] = rsa_pt(P["M"], P["S"])
for k in (1, 5):
    P = {kk: drop_pcs(v, k) for kk, v in X.items()}
    sens[f"rsa_MG_drop_top{k}pc"] = rsa_pt(P["M"], P["G"]); sens[f"rsa_MS_drop_top{k}pc"] = rsa_pt(P["M"], P["S"])
diag["sensitivity_point_estimates_union"] = {k: round(v, 4) for k, v in sens.items()}
diag["n_genes"] = {"union": len(union), **{p: len(g) for p, g in panels.items()}}
diag["panel_overlaps"] = {"lung&immune": len(set(panels["lung"]) & set(panels["immune"])),
                          "lung&external_lung": len(set(panels["lung"]) & set(panels["external_lung"])),
                          "immune&external_lung": len(set(panels["immune"]) & set(panels["external_lung"]))}
log("sensitivity done")

# ---- pre-specified decision rule
E = {e["name"]: e for e in est}
beyond = all(E[f"{m}_MS_{s}_perm_p"]["value"] < 0.05 for m in ("rsa", "dcka")
             for s in ("union", "lung", "immune", "external_lung"))
diff_pos = all(E[f"{m}_diff_MG_minus_MS_union"]["ci_low"] > 0 for m in ("rsa", "dcka"))
panels_same_sign = all(E[f"{m}_diff_MG_minus_MS_{s}"]["value"] > 0 for m in ("rsa", "dcka")
                       for s in ("lung", "immune", "external_lung"))
ratio_hi = max(E[f"{m}_ratio_MS_over_MG_union"]["ci_high"] for m in ("rsa", "dcka"))
ratio_lo = min(E[f"{m}_ratio_MS_over_MG_union"]["ci_low"] for m in ("rsa", "dcka"))
if not beyond:
    verdict = "not aligned with scGPT beyond chance"
elif diff_pos and panels_same_sign and ratio_hi < 0.8:
    verdict = "aligned with scGPT but clearly less than with Geneformer"
elif ratio_lo >= 0.8 and ratio_hi <= 1.25:
    verdict = "aligned with scGPT about as well as with Geneformer"
else:
    verdict = "inconclusive"
diag["decision"] = {"MS_beyond_chance_all_sets_both_metrics": beyond, "diff_CI_above_0_union_both_metrics": diff_pos,
                    "diff_positive_all_panels_both_metrics": panels_same_sign,
                    "ratio_MS_over_MG_union_CI_range": [ratio_lo, ratio_hi]}
print(json.dumps({"verdict": verdict, "estimates": est, "diagnostics": diag}, indent=1))

"""Cross-model gene-embedding alignment: MaxToki-217M vs scGPT whole-human, compared with
MaxToki-217M vs Geneformer V2-316M (shared gene vocabulary and token ids).

Run from the package root:
    "<CODE_ROOT>/analysis-tasks/bin/python" this_script.py
Prints one JSON object {verdict, estimates, diagnostics} to stdout (progress log on stderr).
Reads only data/. Single-threaded BLAS; about 4 minutes on a laptop CPU.

Unit of resampling for every bootstrap CI: the gene (genes resampled with replacement; pairs made of
two copies of the same gene are dropped). Chance level: gene-label permutation (the gene-to-row
correspondence of MaxToki is shuffled)."""
import os
for _v in ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS", "VECLIB_MAXIMUM_THREADS"):
    os.environ.setdefault(_v, "1")
import sys
import time
import json
import numpy as np
import pandas as pd
from scipy.linalg import eigh
from scipy.stats import rankdata, spearmanr
from scipy.spatial.distance import pdist

D = "data"
B_UNION = 1000          # gene-bootstrap replicates, union gene set (primary)
B_PANEL = 500           # gene-bootstrap replicates, each panel
N_PERM = 999            # gene-label permutations, union set
N_PERM_PANEL = 499      # gene-label permutations, each panel
N_SPLIT = 20            # repeated random 5-fold splits for the cross-validated CCA point estimates
B_CCA_FIXED = 2000      # bootstrap of per-gene held-out CCA scores with CCA maps held fixed (diagnostic)
B_CCA_REFIT = 1000      # bootstrap with PCA and CCA refitted in every replicate (reported CIs)
N_SPLIT_BOOT = 4        # random 5-fold splits per refit-bootstrap replicate
N_PERM_CCA = 199        # permutations for CCA / raw-CKA nulls
N_HALF = 200            # random half-samples for the delete-half subsampling SE check
K_PCA, N_CC, N_FOLD = 20, 10, 5
MARGIN = 0.8            # ratio margin of the decision rule
SEED = 20261001
PAIRS = (("M", "G"), ("M", "S"), ("G", "S"))
T0 = time.time()


def log(msg):
    print(f"[{time.time() - T0:7.1f}s] {msg}", file=sys.stderr, flush=True)


# ------------------------------------------------------------------ load and map
Mt = np.load(f"{D}/maxtoki_217m/embed_tokens.npy").astype(np.float64)
Gt = np.load(f"{D}/geneformer_v2_316m/word_embeddings.npy").astype(np.float64)
St = np.load(f"{D}/scgpt_whole_human/encoder_embedding_weight.npy").astype(np.float64)
lnp = np.load(f"{D}/scgpt_whole_human/encoder_enc_norm.npz")
assert Mt.shape == (20275, 1232) and Gt.shape == (20275, 1152) and St.shape == (60697, 512)
tok_m = json.load(open(f"{D}/maxtoki_217m/token_dictionary.json"))
tok_g = json.load(open(f"{D}/geneformer_v2_316m/token_dictionary.json"))
voc_s = json.load(open(f"{D}/scgpt_whole_human/vocab.json"))
assert sorted(voc_s.values()) == list(range(St.shape[0]))
genes_m = {k: v for k, v in tok_m.items() if k.startswith("ENSG")}
genes_g = {k: v for k, v in tok_g.items() if k.startswith("ENSG")}
assert genes_m == genes_g, "MaxToki and Geneformer gene->token-id maps differ"
es = pd.read_csv(f"{D}/gene_ids/ensembl_symbol.csv")
assert es.ensembl_id.is_unique and es.symbol.is_unique
e2s = dict(zip(es.ensembl_id, es.symbol))
panels = {p: pd.read_csv(f"{D}/panels/{p}.csv").ensembl_id.astype(str).tolist()
          for p in ("lung", "immune", "external_lung")}
for p, g in panels.items():
    assert len(g) == len(set(g))
union = sorted(set().union(*panels.values()))


def scgpt_gene_encoder(X):
    """scGPT gene encoder: token-embedding row followed by LayerNorm encoder.enc_norm."""
    mu = X.mean(1, keepdims=True)
    var = X.var(1, keepdims=True)
    return (X - mu) / np.sqrt(var + float(lnp["eps"])) * lnp["weight"] + lnp["bias"]


def tables(genes, scgpt_ln=True):
    for g in genes:
        assert g in genes_m and g in e2s and e2s[g] in voc_s, g
    ti = np.array([genes_m[g] for g in genes])
    si = np.array([voc_s[e2s[g]] for g in genes])
    s = St[si]
    return {"M": Mt[ti], "G": Gt[ti], "S": scgpt_gene_encoder(s) if scgpt_ln else s}


# ------------------------------------------------------------------ helpers
def centered_cos(X):
    Xc = X - X.mean(0)
    Xc = Xc / np.linalg.norm(Xc, axis=1, keepdims=True)
    return Xc @ Xc.T


def pearson(x, y):
    x = x - x.mean(); y = y - y.mean()
    return float(x @ y / np.sqrt((x @ x) * (y @ y)))


def wpearson(x, y, w):
    W = w.sum(); dx = x - (w @ x) / W; dy = y - (w @ y) / W
    return float((w @ (dx * dy)) / np.sqrt((w @ (dx * dx)) * (w @ (dy * dy))))


def partial(rxy, rxz, ryz):
    return (rxy - rxz * ryz) / np.sqrt((1 - rxz ** 2) * (1 - ryz ** 2))


def one_factor(t):
    """Loadings of the exactly identified one-factor model for a triad of pairwise alignments."""
    return {"M": np.sqrt(t["MG"] * t["MS"] / t["GS"]), "G": np.sqrt(t["MG"] * t["GS"] / t["MS"]),
            "S": np.sqrt(t["MS"] * t["GS"] / t["MG"])}


def ucenter_w(K, w):
    """U-centring (unbiased HSIC, Song et al. 2012) of a Gram matrix for a sample in which gene u
    appears w[u] times; pairs of copies of the same gene are excluded (diagonal zeroed)."""
    N = w.sum()
    Kz = K.copy(); np.fill_diagonal(Kz, 0.0)
    r = Kz @ w; t = w @ r
    Kc = Kz - r[:, None] / (N - 2) - r[None, :] / (N - 2) + t / ((N - 1) * (N - 2))
    np.fill_diagonal(Kc, 0.0)
    return Kc


def wdcka(Ka, Kb, WW):
    return float((WW * Ka * Kb).sum() / np.sqrt((WW * Ka * Ka).sum() * (WW * Kb * Kb).sum()))


def dcka_pt(A, B):
    one = np.ones(len(A))
    return wdcka(ucenter_w(A @ A.T, one), ucenter_w(B @ B.T, one), np.ones((len(A), len(A))))


def pctl(a):
    a = np.asarray(a, float)
    return float(np.percentile(a, 2.5)), float(np.percentile(a, 97.5))


def perm_p(null, obs):
    null = np.asarray(null)
    return float((1 + np.sum(null >= obs)) / (len(null) + 1))


class Geometry:
    """RSA = Spearman correlation between two models' pairwise centred-cosine similarities (all gene
    pairs); dCKA = debiased linear CKA. With extra=True also: prsa = Pearson (instead of Spearman) RSA,
    ncka = dCKA of centred, row-normalised vectors (both norm-free). Gene bootstrap uses multiplicity
    weights (exactly equal to recomputing on the resampled gene list with same-gene pairs dropped;
    centring of the cosine similarities is held at the full-set mean)."""

    def __init__(self, X, extra=False):
        n = self.n = len(X["M"])
        self.extra = extra
        self.iu = np.triu_indices(n, 1)
        cg = {k: centered_cos(v) for k, v in X.items()}
        sim = {k: v[self.iu] for k, v in cg.items()}
        self.order = {k: np.argsort(v, kind="mergesort") for k, v in sim.items()}
        self.rank = {k: rankdata(v) for k, v in sim.items()}
        self.gram = {k: v @ v.T for k, v in X.items()}
        ones = np.ones(n)
        self.kc = {k: ucenter_w(v, ones) for k, v in self.gram.items()}
        self.WW1 = np.ones((n, n))
        if extra:
            self.sim, self.cgram = sim, cg
            self.kcn = {k: ucenter_w(v, ones) for k, v in cg.items()}

    def point(self):
        out = {"rsa": {a + b: pearson(self.rank[a], self.rank[b]) for a, b in PAIRS},
               "dcka": {a + b: wdcka(self.kc[a], self.kc[b], self.WW1) for a, b in PAIRS}}
        if self.extra:
            out["prsa"] = {a + b: pearson(self.sim[a], self.sim[b]) for a, b in PAIRS}
            out["ncka"] = {a + b: wdcka(self.kcn[a], self.kcn[b], self.WW1) for a, b in PAIRS}
        return out

    def boot(self, B, rng):
        n = self.n; res = []
        for _ in range(B):
            w = np.bincount(rng.integers(0, n, n), minlength=n).astype(float)
            wp = w[self.iu[0]] * w[self.iu[1]]          # multiplicity of each distinct-gene pair
            r = {}
            for k, o in self.order.items():
                c = wp[o]; cum = np.cumsum(c)
                rk = np.empty_like(c); rk[o] = cum - c + (c + 1) / 2.0   # mid-ranks in resample
                r[k] = rk
            rep = {"rsa": {a + b: wpearson(r[a], r[b], wp) for a, b in PAIRS}}
            idx = np.nonzero(w)[0]; ws = w[idx]; WW = np.outer(ws, ws)
            kc = {k: ucenter_w(g[np.ix_(idx, idx)], ws) for k, g in self.gram.items()}
            rep["dcka"] = {a + b: wdcka(kc[a], kc[b], WW) for a, b in PAIRS}
            if self.extra:
                rep["prsa"] = {a + b: wpearson(self.sim[a], self.sim[b], wp) for a, b in PAIRS}
                kn = {k: ucenter_w(g[np.ix_(idx, idx)], ws) for k, g in self.cgram.items()}
                rep["ncka"] = {a + b: wdcka(kn[a], kn[b], WW) for a, b in PAIRS}
            res.append(rep)
        return res

    def perm(self, N, rng):
        n = self.n
        RM = np.zeros((n, n)); RM[self.iu] = self.rank["M"]; RM = RM + RM.T
        out = {"rsa": {"MG": [], "MS": []}, "dcka": {"MG": [], "MS": []}}
        for _ in range(N):
            p = rng.permutation(n)
            rm = RM[np.ix_(p, p)][self.iu]
            out["rsa"]["MG"].append(pearson(rm, self.rank["G"]))
            out["rsa"]["MS"].append(pearson(rm, self.rank["S"]))
            km = self.kc["M"][np.ix_(p, p)]
            out["dcka"]["MG"].append(wdcka(km, self.kc["G"], self.WW1))
            out["dcka"]["MS"].append(wdcka(km, self.kc["S"], self.WW1))
        return out


# ---- CCA (the source paper's H24 analysis), evaluated on held-out genes
def pc_scores(X, k, whiten=True):
    Xc = X - X.mean(0)
    U, s, Vt = np.linalg.svd(Xc, full_matrices=False)
    return U[:, :k] * (np.sqrt(len(X) - 1) if whiten else s[:k])


def inv_sqrt(C):
    w, V = np.linalg.eigh(C)
    return (V / np.sqrt(np.maximum(w, 1e-10))) @ V.T


def cca_fit(A, B):
    ma, mb = A.mean(0), B.mean(0); A0, B0 = A - ma, B - mb; n = len(A)
    Wa = inv_sqrt(A0.T @ A0 / (n - 1)); Wb = inv_sqrt(B0.T @ B0 / (n - 1))
    U, s, Vt = np.linalg.svd(Wa @ (A0.T @ B0 / (n - 1)) @ Wb)
    return ma, mb, Wa @ U, Wb @ Vt.T, s


def cv_cca(A, B, fold):
    """5-fold CV. Per held-out gene: q = mean over the first N_CC canonical variates of the product of
    within-fold z-scores (its mean over a fold equals the mean held-out canonical correlation), and
    hit = 1 if its nearest held-out partner (cosine, canonical space) is itself."""
    n = len(A); q = np.zeros(n); hit = np.zeros(n); ch = np.zeros(n)
    for k in range(N_FOLD):
        te = fold == k; tr = ~te
        ma, mb, Wa, Wb, _ = cca_fit(A[tr], B[tr])
        Pa = (A[te] - ma) @ Wa[:, :N_CC]; Pb = (B[te] - mb) @ Wb[:, :N_CC]
        za = (Pa - Pa.mean(0)) / Pa.std(0); zb = (Pb - Pb.mean(0)) / Pb.std(0)
        q[te] = (za * zb).mean(1)
        Pa /= np.linalg.norm(Pa, axis=1, keepdims=True); Pb /= np.linalg.norm(Pb, axis=1, keepdims=True)
        hit[te] = np.argmax(Pa @ Pb.T, axis=1) == np.arange(te.sum())
        ch[te] = 1.0 / te.sum()
    return q, hit, ch


def wpca_whiten(K, idx, w, k):
    """Whitened top-k PC scores (weighted covariance = identity) of a bootstrap sample given as unique
    genes idx with multiplicities w; K is the full-set Gram matrix of the uncentred rows."""
    Ku = K[np.ix_(idx, idx)]; N = w.sum()
    r = Ku @ w / N; t = w @ r / N
    Kc = Ku - r[:, None] - r[None, :] + t
    sw = np.sqrt(w); m = len(idx)
    lam, V = eigh(sw[:, None] * Kc * sw[None, :], subset_by_index=[m - k, m - 1])
    return V[:, ::-1] / sw[:, None] * np.sqrt(N - 1)


def wcca_fit(A, B, w):
    W = w.sum(); ma = w @ A / W; mb = w @ B / W; A0 = A - ma; B0 = B - mb; Aw = A0 * w[:, None]
    Wa = inv_sqrt(Aw.T @ A0 / (W - 1)); Wb = inv_sqrt((B0 * w[:, None]).T @ B0 / (W - 1))
    U, s, Vt = np.linalg.svd(Wa @ (Aw.T @ B0 / (W - 1)) @ Wb)
    return ma, mb, Wa @ U, Wb @ Vt.T, s


def cv_cca_w(A, B, w, fold):
    """cv_cca for a bootstrap sample (unique genes with multiplicities w). Folds are assigned to unique
    genes, so copies of one gene never sit on both sides of a split. Retrieval candidates are the unique
    held-out genes. With w = 1 this equals the fold-weighted mean of cv_cca."""
    qs = hs = cs = 0.0
    for k in range(N_FOLD):
        te = fold == k; tr = ~te
        ma, mb, Wa, Wb, _ = wcca_fit(A[tr], B[tr], w[tr])
        Pa = (A[te] - ma) @ Wa[:, :N_CC]; Pb = (B[te] - mb) @ Wb[:, :N_CC]
        wt = w[te]; Wt = wt.sum()
        da = Pa - wt @ Pa / Wt; db = Pb - wt @ Pb / Wt
        za = da / np.sqrt(wt @ da ** 2 / Wt); zb = db / np.sqrt(wt @ db ** 2 / Wt)
        qs += wt @ (za * zb).mean(1)
        Pa /= np.linalg.norm(Pa, axis=1, keepdims=True); Pb /= np.linalg.norm(Pb, axis=1, keepdims=True)
        hs += wt @ (np.argmax(Pa @ Pb.T, axis=1) == np.arange(te.sum()))
        cs += Wt / te.sum()
    N = w.sum()
    return qs / N, hs / N, cs / N


# ------------------------------------------------------------------ run
rng = np.random.default_rng(SEED)
est = []
diag = {}


