# ---- union set: cross-validated CCA (paper-style CCA on 20 whitened PCs, scored on held-out genes)
X = tables(union); n = len(union)
Z = {k: pc_scores(v, K_PCA) for k, v in X.items()}
cv = {}
for pr in ("MG", "MS"):
    Q = np.zeros(n); H = np.zeros(n); C = np.zeros(n)
