rng_cca = np.random.default_rng(SEED + 1)
KF = {k: v @ v.T for k, v in X.items()}
cvr = {"MG": [], "MS": []}
for _ in range(B_CCA_REFIT):
    wf = np.bincount(rng_cca.integers(0, n, n), minlength=n)
