# ---- sensitivity analyses and exploratory checks (point estimates)
def rsa_pt(A, B):
    iu = np.triu_indices(len(A), 1)
    return float(spearmanr(centered_cos(A)[iu], centered_cos(B)[iu])[0])


def drop_pcs(A, k):
    c = A - A.mean(0)
    U, s, Vt = np.linalg.svd(c, full_matrices=False)
    return c - (U[:, :k] * s[:k]) @ Vt[:k]


def eucl_rsa(A, B):
    return float(spearmanr(pdist(A), pdist(B))[0])


def cnorm(A):
    return np.linalg.norm(A - A.mean(0), axis=1)


Xr = tables(union, scgpt_ln=False)
sens = {"rsa_MS_scgpt_without_layernorm": rsa_pt(Xr["M"], Xr["S"]),
        "rsa_GS_scgpt_without_layernorm": rsa_pt(Xr["G"], Xr["S"])}
for k in (10, 20, 50):                       # norm-free: centred cosine on PC scores
    P = {kk: pc_scores(v, k, whiten=False) for kk, v in X.items()}
    sens[f"rsa_MG_pca{k}"] = rsa_pt(P["M"], P["G"]); sens[f"rsa_MS_pca{k}"] = rsa_pt(P["M"], P["S"])
for k in (1, 5):                             # norm-free: centred cosine after removing top PCs
    P = {kk: drop_pcs(v, k) for kk, v in X.items()}
