tert = np.argsort(np.argsort(cnorm(X["M"]))) * 3 // n      # MaxToki centred-norm terciles
for t in range(3):                           # norm-stratified: RSA within each tercile
    P = {kk: v[tert == t] for kk, v in X.items()}
    sens[f"rsa_MG_Mnorm_tercile{t + 1}"] = rsa_pt(P["M"], P["G"])
    sens[f"rsa_MS_Mnorm_tercile{t + 1}"] = rsa_pt(P["M"], P["S"])
# norm-sensitive: Euclidean distances (full dimension, and on unwhitened PC scores as in the paper)
