# row-norm structure (centred norms), with the primary (LayerNorm) and the raw scGPT representation
sens["cnorm_spearman_MG"] = float(spearmanr(cnorm(X["M"]), cnorm(X["G"]))[0])
sens["cnorm_spearman_MS"] = float(spearmanr(cnorm(X["M"]), cnorm(X["S"]))[0])
