# ---- delete-half subsampling check of the bootstrap SE (re-centres the cosines on each half-sample)
rng_half = np.random.default_rng(SEED + 2)
half = {"rsa_MG": [], "rsa_MS": [], "rsa_ratio": [], "dcka_MG": [], "dcka_MS": [], "dcka_ratio": []}
