             for s in ("union", "lung", "immune", "external_lung"))
diff_pos = all(E[f"{m}_diff_MG_minus_MS_union"]["ci_low"] > 0 for m in ("rsa", "dcka"))
panels_same_sign = all(E[f"{m}_diff_MG_minus_MS_{s}"]["value"] > 0 for m in ("rsa", "dcka")
                       for s in ("lung", "immune", "external_lung"))
ratio_hi = max(E[f"{m}_ratio_MS_over_MG_union"]["ci_high"] for m in ("rsa", "dcka"))
ratio_lo = min(E[f"{m}_ratio_MS_over_MG_union"]["ci_low"] for m in ("rsa", "dcka"))


def rule(lo, hi):
    if not beyond:
        return "not aligned with scGPT beyond chance"
    if diff_pos and panels_same_sign and hi < MARGIN:
        return "aligned with scGPT but clearly less than with Geneformer"
    if lo >= MARGIN and hi <= 1 / MARGIN:
        return "aligned with scGPT about as well as with Geneformer"
    return "inconclusive"


verdict = rule(ratio_lo, ratio_hi)          # margin applied to the RSA/dCKA ratio itself (stated rule)
verdict_corr_scale = rule(float(np.sqrt(ratio_lo)), float(np.sqrt(ratio_hi)))   # margin on sqrt-ratio
ratio_ci = {f"{m}_{s}": [E[f"{m}_ratio_MS_over_MG_{s}"]["ci_low"], E[f"{m}_ratio_MS_over_MG_{s}"]["ci_high"]]
            for m in ("rsa", "dcka") for s in ("union", "lung", "immune", "external_lung")}
ratio_ci.update({f"{m}_union": [E[f"{m}_ratio_MS_over_MG_union"]["ci_low"], E[f"{m}_ratio_MS_over_MG_union"]["ci_high"]]
                 for m in ("prsa", "ncka", "cvcca_meancorr10", "cvcca_top1")})
diag["decision"] = {"MS_beyond_chance_all_sets_both_metrics": beyond, "diff_CI_above_0_union_both_metrics": diff_pos,
                    "diff_positive_all_panels_both_metrics": panels_same_sign,
                    "ratio_MS_over_MG_union_CI_range": [ratio_lo, ratio_hi],
                    "verdict_margin_on_metric_scale": verdict,
                    "verdict_if_margin_on_correlation_scale": verdict_corr_scale,
                    "clearly_less_holds_for_metric_scale_margins_above": ratio_hi,
                    "ratio_CIs_crossing_margin": [k for k, v in ratio_ci.items() if v[0] < MARGIN < v[1]],
                    "ratio_CIs_all": ratio_ci}
diag["n_genes"] = {"union": len(union), **{p: len(g) for p, g in panels.items()}}
diag["panel_overlaps"] = {"lung&immune": len(set(panels["lung"]) & set(panels["immune"])),
                          "lung&external_lung": len(set(panels["lung"]) & set(panels["external_lung"])),
                          "immune&external_lung": len(set(panels["immune"]) & set(panels["external_lung"]))}
print(json.dumps({"verdict": verdict, "estimates": est, "diagnostics": diag}, indent=1))

"""Cross-model gene-embedding alignment: MaxToki-217M vs scGPT whole-human, compared with
MaxToki-217M vs Geneformer V2-316M (shared gene vocabulary and token ids).

Run from the package root:
    "<CODE_ROOT>/analysis-tasks/bin/python" this_script.py
Prints one JSON object {verdict, estimates, diagnostics}. Reads only data/. Uses single-threaded BLAS;
the measured wall-clock time is printed in diagnostics["runtime_seconds"].

Unit of resampling for every bootstrap CI: the gene (genes resampled with replacement; pairs made of
two copies of the same gene are dropped). Chance level: gene-label permutation (MaxToki's
gene-to-row correspondence is shuffled)."""
