def cv_run(FPa, FPb):
    """Per-gene held-out scores (q, hit, chance) averaged over the N_SPLIT splits."""
    Q = np.zeros(n); H = np.zeros(n); C = np.zeros(n)
    for si, sp in enumerate(SPL):
