            a = FPa[si][fi]; b = FPb[si][fi]
            q, h = fold_score(a[0], a[1], b[0], b[1])
            Q[te] += q / N_SPLIT; H[te] += h / N_SPLIT; C[te] += 1.0 / len(te) / N_SPLIT
    return Q, H, C


