def zrank(x):
    x = rankdata(x)
    return (x - x.mean()) / x.std()


def rownorm(A):
    return np.linalg.norm(A, axis=1)


def cnorm(A):
    return np.linalg.norm(A - A.mean(0), axis=1)


# frequency / tokenisation proxies: ranks of raw and centred row norms of MaxToki, Geneformer and raw scGPT
