def cos_from_gram(K):
    d = np.sqrt(np.diag(K))
    return K / np.outer(d, d)


def sens_rep(w):
    idx = np.nonzero(w)[0]; ws = w[idx]; W = ws.sum(); m = len(idx); sq = np.sqrt(ws)
    iu = np.triu_indices(m, 1); wp = ws[iu[0]] * ws[iu[1]]; WW = np.outer(ws, ws)
    GR = {}
    for k, K in KS.items():
        Ks = K[np.ix_(idx, idx)]; r = Ks @ ws / W; t = ws @ r / W
        GR[k] = Ks - r[:, None] - r[None, :] + t          # Gram of rows centred at the resample mean
    rep = {}
    for k in "MGS":
        rep[("full_recentred", k)] = GR[k]
        rep[("scgpt_no_layernorm", k)] = GR["Sraw"] if k == "S" else GR[k]
        rep[("norm_residualised", k)] = GR[k + "res"]
        P = PF[k][idx]; P = P - (ws @ P) / W               # fixed basis; scores re-centred
        for kk in (10, 20, 50):
            rep[(f"pca{kk}", k)] = P[:, :kk] @ P[:, :kk].T
        for kk in (1, 5):
            rep[(f"drop_top{kk}pc", k)] = GR[k] - P[:, :kk] @ P[:, :kk].T
        lam, U = eigh(GR[k] * np.outer(sq, sq), subset_by_index=[m - 20, m - 1]); lam = lam[::-1]; U = U[:, ::-1]
        P = (GR[k] * sq[None, :]) @ U / np.sqrt(lam)       # basis refitted on the resample (weighted PCA)
        for kk in (10, 20):
            rep[(f"pca{kk}_refit", k)] = P[:, :kk] @ P[:, :kk].T
    cos, rk = {}, {}
    for K in rep.values():
        if id(K) not in cos:
            C = cos_from_gram(K); cos[id(K)] = C; rk[id(K)] = wranks(C[iu], wp)
    out = {}
    for var in SVARS:
        r = {k: rk[id(rep[(var, k)])] for k in "MGS"}
        kc = {k: ucenter_w(rep[(var, k)], ws) for k in "MGS"}
        for a, b in PAIRS:
            out[(var, "rsa", a + b)] = wpearson(r[a], r[b], wp)
            out[(var, "dcka", a + b)] = wdcka(kc[a], kc[b], WW)
    kc = {k: ucenter_w(cos[id(rep[("full_recentred", k)])], ws) for k in "MGS"}
    for a, b in PAIRS:
        out[("dcka_on_centred_cosine", "dcka", a + b)] = wdcka(kc[a], kc[b], WW)
    wpf = w[iu_full[0]] * w[iu_full[1]]
    re = {}
    for k, o in EORD.items():
        c = wpf[o]; cum = np.cumsum(c); rke = np.empty_like(c); rke[o] = cum - c + (c + 1) / 2.0; re[k] = rke
    for a, b in PAIRS:
        out[("euclidean", "rsa", a + b)] = wpearson(re[a], re[b], wpf)
    return out


sp_pt = sens_rep(np.ones(n))
rng_s = np.random.default_rng(SEED + 303)
sp_bs = [sens_rep(np.bincount(rng_s.integers(0, n, n), minlength=n).astype(float)) for _ in range(B_SENS)]
BS = ("gene bootstrap (same draw for all model pairs, pairs of copies of one gene dropped, gene vectors re-centred "
      "at the resample mean, PCA basis fitted once on all genes); percentile 95%% CI, B=%d" % B_SENS)
BSR = ("gene bootstrap with the PCA basis refitted on every resample (same draw for all model pairs, pairs of "
       "copies of one gene dropped); normal-approximation 95%% CI = point +/- 1.96 x bootstrap SD, B=%d (refitting "
       "on resamples with duplicated genes shifts the bootstrap distribution, so percentiles are off-centre)" % B_SENS)
sens_ctx, refit_shift = {}, {}
for var in SVARS + ("dcka_on_centred_cosine", "euclidean"):
    for met in ("rsa", "dcka"):
        if (var, met, "MG") not in sp_pt:
            continue
        stats = {pr: (sp_pt[(var, met, pr)], [r[(var, met, pr)] for r in sp_bs]) for pr in ("MG", "MS")}
        stats["diff_MG_minus_MS"] = (sp_pt[(var, met, "MG")] - sp_pt[(var, met, "MS")],
                                     [r[(var, met, "MG")] - r[(var, met, "MS")] for r in sp_bs])
        stats["ratio_MS_over_MG"] = (sp_pt[(var, met, "MS")] / sp_pt[(var, met, "MG")],
                                     [r[(var, met, "MS")] / r[(var, met, "MG")] for r in sp_bs])
        for lab, (v, b) in stats.items():
            if var in REFIT:
                add(f"sens_{var}_{met}_{lab}_union", v, normal_ci(v, b), BSR)
                refit_shift[f"{var}_{met}_{lab}"] = {"bootstrap_mean_minus_point": round(float(np.mean(b) - v), 4),
                                                     "percentile_interval": [round(x, 4) for x in pctl(b)]}
            else:
                add(f"sens_{var}_{met}_{lab}_union", v, pctl(b), BS)
        sens_ctx[f"{var}_{met}_GS"] = round(sp_pt[(var, met, "GS")], 4)
diag["sensitivity_GS_point_estimates_union"] = sens_ctx
diag["sensitivity_refit_bootstrap_shift"] = refit_shift
log("sensitivity bootstrap done")

# ---- unselected comparator: random gene sets of the union's size from all genes mappable in all three models
rng_r = np.random.default_rng(SEED + 404)
mapp = np.array(mappable)
rnd = []
for _ in range(N_RAND):
    g = sorted(rng_r.choice(mapp, n, replace=False))
    Y = tables(g); iu = np.triu_indices(n, 1)
    rk = {k: rankdata(centered_cos(v)[iu]) for k, v in Y.items()}
    kc = {k: ucenter_w(v @ v.T, np.ones(n)) for k, v in Y.items()}
    d = {}
    for a, b in PAIRS:
        d[("rsa", a + b)] = pearson(rk[a], rk[b]); d[("dcka", a + b)] = wdcka(kc[a], kc[b], np.ones((n, n)))
    rnd.append(d)
RM_ = ("distribution over %d random %d-gene sets drawn without replacement from the %d genes mappable in all "
       "three models: value = mean, interval = 2.5-97.5 percentiles across sets" % (N_RAND, n, len(mappable)))
for met in ("rsa", "dcka"):
    for pr in ("MG", "MS", "GS"):
        v = [d[(met, pr)] for d in rnd]
        add(f"random{n}_{met}_{pr}", np.mean(v), pctl(v), RM_)
    v = [d[(met, "MG")] - d[(met, "MS")] for d in rnd]
    add(f"random{n}_{met}_diff_MG_minus_MS", np.mean(v), pctl(v), RM_)
    v = [d[(met, "MS")] / d[(met, "MG")] for d in rnd]
    add(f"random{n}_{met}_ratio_MS_over_MG", np.mean(v), pctl(v), RM_)
    diag[f"random{n}_{met}_fraction_of_sets_with_GS_below_MG"] = float(np.mean([d[(met, "GS")] < d[(met, "MG")]
                                                                                   for d in rnd]))
diag["n_mappable_genes_all_three_models"] = len(mappable)
log("random gene sets done")

# ---- exploratory checks reported in the text
rng_h = np.random.default_rng(SEED + 505)
hh = []
for _ in range(N_HALF):
    idx = np.sort(rng_h.choice(n, n // 2, replace=False)); iu = np.triu_indices(len(idx), 1)
    rk = {k: rankdata(centered_cos(X[k][idx])[iu]) for k in "MGS"}
    hh.append((pearson(rk["M"], rk["G"]), pearson(rk["M"], rk["S"])))
hh = np.array(hh)
diag["delete_half_subsampling_rsa_sd_union"] = {
    "MG": round(float(hh[:, 0].std(ddof=1)), 4), "MS": round(float(hh[:, 1].std(ddof=1)), 4),
    "bootstrap_se_MG": round(float(np.std([r["rsa"]["MG"] for r in bs_union], ddof=1)), 4),
    "bootstrap_se_MS": round(float(np.std([r["rsa"]["MS"] for r in bs_union], ddof=1)), 4)}
diag["spearman_of_centred_row_norms_union"] = {
    "MG": round(float(spearmanr(cnorm(X["M"]), cnorm(X["G"]))[0]), 4),
    "MS_layernormed_scgpt": round(float(spearmanr(cnorm(X["M"]), cnorm(X["S"]))[0]), 4),
    "MS_raw_scgpt": round(float(spearmanr(cnorm(X["M"]), cnorm(XR["S"]))[0]), 4),
    "GS_layernormed_scgpt": round(float(spearmanr(cnorm(X["G"]), cnorm(X["S"]))[0]), 4)}
pcv = {}
for k, v in X.items():
    s = np.linalg.svd(v - v.mean(0), compute_uv=False); ev = s ** 2 / np.sum(s ** 2)
    pcv[k] = {"top1": round(float(ev[0]), 4), "top5": round(float(ev[:5].sum()), 4),
              "top10": round(float(ev[:10].sum()), 4), "top20": round(float(ev[:20].sum()), 4)}
diag["pca_variance_explained_union"] = pcv
diag["n_genes"] = {"union": len(union), **{p: len(g) for p, g in panels.items()}}
diag["panel_overlaps"] = {"lung&immune": len(set(panels["lung"]) & set(panels["immune"])),
                          "lung&external_lung": len(set(panels["lung"]) & set(panels["external_lung"])),
                          "immune&external_lung": len(set(panels["immune"]) & set(panels["external_lung"]))}

# ---- pre-specified decision rule (applied to the primary analysis)
E = {e["name"]: e for e in est}
beyond = all(E[f"{m}_MS_{s}_perm_p"]["value"] < 0.05 for m in ("rsa", "dcka")
             for s in ("union", "lung", "immune", "external_lung"))
diff_pos = all(E[f"{m}_diff_MG_minus_MS_union"]["ci_low"] > 0 for m in ("rsa", "dcka"))
panels_same_sign = all(E[f"{m}_diff_MG_minus_MS_{s}"]["value"] > 0 for m in ("rsa", "dcka")
                       for s in ("lung", "immune", "external_lung"))
ratio_hi = max(E[f"{m}_ratio_MS_over_MG_union"]["ci_high"] for m in ("rsa", "dcka"))
ratio_lo = min(E[f"{m}_ratio_MS_over_MG_union"]["ci_low"] for m in ("rsa", "dcka"))
if not beyond:
    verdict = "not aligned with scGPT beyond chance"
elif diff_pos and panels_same_sign and ratio_hi < 0.8:
    verdict = "aligned with scGPT but clearly less than with Geneformer"
elif ratio_lo >= 0.8 and ratio_hi <= 1.25:
    verdict = "aligned with scGPT about as well as with Geneformer"
else:
    verdict = "inconclusive"
diag["decision"] = {"MS_beyond_chance_all_sets_both_metrics": beyond, "diff_CI_above_0_union_both_metrics": diff_pos,
                    "diff_positive_all_panels_both_metrics": panels_same_sign,
                    "ratio_MS_over_MG_union_CI_range": [ratio_lo, ratio_hi]}


# the same difference / ratio criteria applied to each secondary analysis, one metric at a time
def crit(name_diff, name_ratio):
    d, r = E[name_diff], E[name_ratio]
    return {"diff_CI_above_0": d["ci_low"] > 0, "ratio_CI_upper_below_0.8": r["ci_high"] < 0.8,
            "ratio_CI_within_0.8_1.25": r["ci_low"] >= 0.8 and r["ci_high"] <= 1.25,
            "ratio": r["value"], "ratio_CI": [r["ci_low"], r["ci_high"]]}


chk = {}
for s in ("lung", "immune", "external_lung"):
    for m in ("rsa", "dcka"):
        chk[f"panel_{s}_{m}"] = crit(f"{m}_diff_MG_minus_MS_{s}", f"{m}_ratio_MS_over_MG_{s}")
for lab in ("cvcca_meancorr10", "cvcca_top1"):
    chk[lab] = crit(f"{lab}_diff_MG_minus_MS_union", f"{lab}_ratio_MS_over_MG_union")
for var in SVARS + ("dcka_on_centred_cosine", "euclidean"):
    for m in ("rsa", "dcka"):
        if f"sens_{var}_{m}_ratio_MS_over_MG_union" in E:
            chk[f"sens_{var}_{m}"] = crit(f"sens_{var}_{m}_diff_MG_minus_MS_union",
                                          f"sens_{var}_{m}_ratio_MS_over_MG_union")
for m in ("rsa", "dcka"):
    r = E[f"random{n}_{m}_ratio_MS_over_MG"]
    chk[f"random_sets_{m}"] = {"ratio": r["value"], "ratio_range_across_sets": [r["ci_low"], r["ci_high"]]}
diag["criteria_applied_to_secondary_analyses"] = chk
diag["runtime_seconds"] = round(time.time() - T0, 1)
print(json.dumps({"verdict": verdict, "estimates": est, "diagnostics": diag}, indent=1))

#!/usr/bin/env python
"""
Cross-model alignment of gene-embedding geometry:
MaxToki-217M (M) vs scGPT whole-human (S) vs Geneformer V2-316M (G),
on three gene panels (lung, immune, external_lung).

Run from the package root with
    <CODE_ROOT>/analysis-tasks/bin/python <this script>
Prints one JSON object (verdict, estimates, null/chance levels, per-panel values)
to stdout; progress goes to stderr.

Primary metric : RSA = Spearman correlation between two models' pairwise
                 cosine-distance matrices over the panel genes (embeddings
                 centred within panel; scGPT rows passed through the checkpoint's
                 encoder LayerNorm), averaged over the three panels.
Secondary      : (a) cross-validated whitened CCA (20 PCs per model, 10 canonical
                 components, 5-fold CV over genes, 5 fold re-draws): held-out mean
                 canonical correlation and held-out top-1 gene retrieval;
                 (b) k=10 nearest-neighbour overlap.
Uncertainty    : bootstrap over genes (unit of resampling = gene; genes drawn with
                 replacement from the union of the three panels so that genes shared
                 between panels are resampled consistently). Chance levels from
                 gene-correspondence permutation nulls (Mantel for RSA).
"""
import json, sys, time
import numpy as np
import pandas as pd

T0 = time.time()
SEED = 20261001
PANELS = ["lung", "immune", "external_lung"]
PAIRS = [("M", "G"), ("M", "S"), ("G", "S")]
B_RSA = 1000        # gene-bootstrap replicates for primary RSA and kNN
B_SENS = 300        # gene-bootstrap replicates for RSA sensitivity variants (first B_SENS replicates)
N_PERM = 999        # Mantel permutations per panel
B_CCA = 1000        # gene-bootstrap replicates for CV-CCA held-out metrics
N_PERM_CCA = 100    # gene-correspondence permutations for CV-CCA
N_PERM_KNN = 200
CV_REPEATS = 5
K_PC, N_CC, FOLDS, K_NN = 20, 10, 5, 10


def log(*a):
    print(f"[{time.time() - T0:7.1f}s]", *a, file=sys.stderr, flush=True)


# ------------------------------------------------------------------ data
M_tab = np.load("data/maxtoki_217m/embed_tokens.npy").astype(np.float64)
G_tab = np.load("data/geneformer_v2_316m/word_embeddings.npy").astype(np.float64)
S_tab = np.load("data/scgpt_whole_human/encoder_embedding_weight.npy").astype(np.float64)
ln = np.load("data/scgpt_whole_human/encoder_enc_norm.npz")
mt_dict = json.load(open("data/maxtoki_217m/token_dictionary.json"))
gf_dict = json.load(open("data/geneformer_v2_316m/token_dictionary.json"))
sg_vocab = json.load(open("data/scgpt_whole_human/vocab.json"))
e2s = dict(pd.read_csv("data/gene_ids/ensembl_symbol.csv")[["ensembl_id", "symbol"]].values)
panels = {p: pd.read_csv(f"data/panels/{p}.csv")["ensembl_id"].tolist() for p in PANELS}

union = sorted(set().union(*panels.values()))
for g in union:  # every panel gene must map in all three models; M and G share token ids
    assert g in mt_dict and g in gf_dict and mt_dict[g] == gf_dict[g], g
    assert g in e2s and e2s[g] in sg_vocab, g
tok = np.array([mt_dict[g] for g in union])          # MaxToki == Geneformer token id
stok = np.array([sg_vocab[e2s[g]] for g in union])   # scGPT token id via gene symbol
assert tok.min() >= 4 and tok.max() < M_tab.shape[0] and tok.max() < G_tab.shape[0]


def scgpt_layernorm(X):
    """scGPT GeneEncoder = embedding row followed by LayerNorm enc_norm."""
    mu = X.mean(1, keepdims=True)
    var = X.var(1, keepdims=True)
    return (X - mu) / np.sqrt(var + float(ln["eps"])) * ln["weight"] + ln["bias"]


XU = {"M": M_tab[tok], "G": G_tab[tok], "S": scgpt_layernorm(S_tab[stok]), "Sraw": S_tab[stok]}
pos = {g: i for i, g in enumerate(union)}
pidx = {p: np.array([pos[g] for g in panels[p]]) for p in PANELS}
NU = len(union)
log("panels", {p: len(v) for p, v in pidx.items()}, "union", NU)


def centred(X):
    return X - X.mean(0)


def cos_dist(X):
    Xc = centred(X)
    Xn = Xc / np.linalg.norm(Xc, axis=1, keepdims=True)
    return 1.0 - Xn @ Xn.T


def euc_dist(X):
    Xc = centred(X)
    sq = (Xc ** 2).sum(1)
    return np.sqrt(np.maximum(sq[:, None] + sq[None, :] - 2 * Xc @ Xc.T, 0))


def remove_top_pcs(X, r):
    Xc = centred(X)
    w, U = np.linalg.eigh(Xc @ Xc.T)
    Ur = U[:, np.argsort(w)[::-1][:r]]
    return Xc - Ur @ (Ur.T @ Xc)


def ranks(v):
    o = np.argsort(v, kind="mergesort")
    r = np.empty(len(v)); r[o] = np.arange(1, len(v) + 1)
    return r


def pearson(x, y):
    x = x - x.mean(); y = y - y.mean()
    return float(x @ y / np.sqrt((x @ x) * (y @ y)))


def wpearson(x, y, w):
    sw = w.sum(); dx = x - (w @ x) / sw; dy = y - (w @ y) / sw
    return float((w * dx) @ dy / np.sqrt(((w * dx) @ dx) * ((w * dy) @ dy)))


def wranks(order, w):
    """Mid-ranks of every pair in the bootstrap-expanded sample, where pair p occurs w_p times.
    Spearman on the expanded sample == weighted Pearson of these mid-ranks with weights w."""
    ws = w[order]
    r = np.empty(len(w)); r[order] = np.cumsum(ws) - ws / 2.0 + 0.5
    return r


# ------------------------------------------------------------------ per-panel distance views
# key = (view, model); primary view is "cos" on M, G, S (scGPT after LayerNorm)
VIEW_FUN = {"cos": cos_dist, "euc": euc_dist, "rmPC1": lambda X: cos_dist(remove_top_pcs(X, 1))}
VIEW_KEYS = [("cos", "M"), ("cos", "G"), ("cos", "S"), ("cos", "Sraw"),
             ("euc", "M"), ("euc", "G"), ("euc", "S"),
             ("rmPC1", "M"), ("rmPC1", "G"), ("rmPC1", "S")]
PRIMARY = [("cos", a, b) for a, b in PAIRS]
# sensitivity specs: (name, keyA, keyB)
SENS = {
    "rawS": {"MG": (("cos", "M"), ("cos", "G")), "MS": (("cos", "M"), ("cos", "Sraw"))},
    "euc": {"MG": (("euc", "M"), ("euc", "G")), "MS": (("euc", "M"), ("euc", "S"))},
    "rmPC1": {"MG": (("rmPC1", "M"), ("rmPC1", "G")), "MS": (("rmPC1", "M"), ("rmPC1", "S"))},
}
PD, IU = {}, {}
for p in PANELS:
    n = len(pidx[p]); iu = np.triu_indices(n, 1); IU[p] = iu; PD[p] = {}
    for (v, m) in VIEW_KEYS:
        D = VIEW_FUN[v](XU[m][pidx[p]]); d = D[iu]
        PD[p][(v, m)] = {"D": D, "r": ranks(d), "o": np.argsort(d, kind="mergesort")}
log("distances done")

rsa_obs = {(v, a, b): {p: pearson(PD[p][(v, a)]["r"], PD[p][(v, b)]["r"]) for p in PANELS}
           for (v, a, b) in PRIMARY}
sens_obs = {s: {k: {p: pearson(PD[p][ka]["r"], PD[p][kb]["r"]) for p in PANELS}
                for k, (ka, kb) in d.items()} for s, d in SENS.items()}

rng = np.random.default_rng(SEED)

# ------------------------------------------------------------------ Mantel permutation null (primary view)
mantel_null = {pr: np.zeros((N_PERM, len(PANELS))) for pr in PAIRS}
for j, p in enumerate(PANELS):
    n = len(pidx[p]); i0, j0 = IU[p]
    Rfull, rc = {}, {}
    for m in ["M", "G", "S"]:
        R = np.zeros((n, n)); R[i0, j0] = PD[p][("cos", m)]["r"]; Rfull[m] = R + R.T
        rc[m] = PD[p][("cos", m)]["r"] - PD[p][("cos", m)]["r"].mean()
    ss = rc["M"] @ rc["M"]   # all rank vectors are permutations of 1..P -> same sum of squares
    for k in range(N_PERM):
        perm = rng.permutation(n); pi, pj = perm[i0], perm[j0]
        for a, b in PAIRS:
            mantel_null[(a, b)][k, j] = (rc[a] @ Rfull[b][pi, pj]) / ss
log("mantel done")

# ------------------------------------------------------------------ kNN overlap (per-gene scores)
def knn_sets(D, k):
    D = D.copy(); np.fill_diagonal(D, np.inf)
    return np.argsort(D, axis=1)[:, :k]


knn_gene = {pr: {} for pr in PAIRS}
knn_null = {pr: np.zeros((N_PERM_KNN, len(PANELS))) for pr in PAIRS}
for j, p in enumerate(PANELS):
    n = len(pidx[p]); rows = np.repeat(np.arange(n), K_NN)
    NN = {m: knn_sets(PD[p][("cos", m)]["D"], K_NN) for m in ["M", "G", "S"]}
    Amask = {}
    for m in NN:
        A = np.zeros((n, n), bool); A[rows, NN[m].ravel()] = True; Amask[m] = A
    for a, b in PAIRS:
        knn_gene[(a, b)][p] = (Amask[a] & Amask[b]).sum(1) / K_NN
    for k in range(N_PERM_KNN):
        perm = rng.permutation(n); pinv = np.argsort(perm)
        for a, b in PAIRS:
            Bp = np.zeros((n, n), bool); Bp[rows, pinv[NN[b][perm]].ravel()] = True
            knn_null[(a, b)][k, j] = ((Amask[a] & Bp).sum(1) / K_NN).mean()
log("knn done")

# ------------------------------------------------------------------ gene bootstrap: RSA (+ sensitivity) and kNN
boot_rsa = {s: np.zeros((B_RSA, len(PANELS))) for s in PRIMARY}
boot_sens = {s: {k: np.zeros((B_SENS, len(PANELS))) for k in d} for s, d in SENS.items()}
boot_knn = {pr: np.zeros((B_RSA, len(PANELS))) for pr in PAIRS}
sens_keys = sorted({kk for d in SENS.values() for pair in d.values() for kk in pair} - {("cos", "M"), ("cos", "G"), ("cos", "S")})
for bi in range(B_RSA):
    cu = np.bincount(rng.integers(0, NU, NU), minlength=NU).astype(float)
    for j, p in enumerate(PANELS):
        c = cu[pidx[p]]; i0, j0 = IU[p]; w = c[i0] * c[j0]
        R = {key: wranks(PD[p][key]["o"], w) for key in [("cos", "M"), ("cos", "G"), ("cos", "S")]}
        for (v, a, b) in PRIMARY:
            boot_rsa[(v, a, b)][bi, j] = wpearson(R[(v, a)], R[(v, b)], w)
        if bi < B_SENS:
            for key in sens_keys:
                R[key] = wranks(PD[p][key]["o"], w)
            for s, d in SENS.items():
                for k, (ka, kb) in d.items():
                    boot_sens[s][k][bi, j] = wpearson(R[ka], R[kb], w)
        for pr in PAIRS:
            boot_knn[pr][bi, j] = (c @ knn_gene[pr][p]) / c.sum()
    if bi % 250 == 0:
        log("rsa boot", bi)
log("rsa boot done")

# ------------------------------------------------------------------ cross-validated CCA
def pc_scores(X, k):
    """Unit-variance scores on the top-k principal components (unsupervised, per model)."""
    Xc = centred(X)
    w, U = np.linalg.eigh(Xc @ Xc.T)
    return U[:, np.argsort(w)[::-1][:k]] * np.sqrt(len(X) - 1)


def inv_sqrt(C):
    w, V = np.linalg.eigh(C)
    return (V / np.sqrt(w)) @ V.T


def cca_fit(a, b, reg=1e-3):
    m = len(a); ma, mb = a.mean(0), b.mean(0); a = a - ma; b = b - mb
    Wa = inv_sqrt(a.T @ a / (m - 1) + reg * np.eye(a.shape[1]))
    Wb = inv_sqrt(b.T @ b / (m - 1) + reg * np.eye(b.shape[1]))
    U, s, Vt = np.linalg.svd(Wa @ (a.T @ b / (m - 1)) @ Wb)
    return Wa @ U[:, :N_CC], Wb @ Vt.T[:, :N_CC], s[:N_CC], ma, mb


def cca_oof(A, B, seed):
    """5-fold CV over genes. For each fold returns (test idx, Pa, Pb): held-out genes projected
    with the CCA maps fitted on the other folds."""
    f = np.random.default_rng(seed).permutation(len(A)) % FOLDS
    out = []
    for k in range(FOLDS):
        te = np.where(f == k)[0]; tr = np.where(f != k)[0]
        Wa, Wb, _, ma, mb = cca_fit(A[tr], B[tr])
        out.append((te, (A[te] - ma) @ Wa, (B[te] - mb) @ Wb))
    return out


def oof_metrics(folds, c=None):
    """Held-out mean canonical correlation (mean over folds and components) and top-1
    retrieval A->B among all held-out genes of the fold (candidate set fixed).
    c = optional bootstrap gene counts used as query/correlation weights."""
    ccs, hits, tot = [], 0.0, 0.0
    for te, Pa, Pb in folds:
        w = np.ones(len(te)) if c is None else c[te].astype(float)
        if (w > 0).sum() < 3:
            continue
        sw = w.sum()
        da = Pa - (w @ Pa) / sw; db = Pb - (w @ Pb) / sw
        cc = ((w[:, None] * da) * db).sum(0) / np.sqrt(((w[:, None] * da) * da).sum(0) * ((w[:, None] * db) * db).sum(0))
        ccs.append(cc.mean())
        na = Pa / np.linalg.norm(Pa, axis=1, keepdims=True); nb = Pb / np.linalg.norm(Pb, axis=1, keepdims=True)
        hit = (na @ nb.T).argmax(1) == np.arange(len(te))
        hits += w @ hit; tot += sw
    return float(np.mean(ccs)), hits / tot


PCS = {p: {m: pc_scores(XU[m][pidx[p]], K_PC) for m in ["M", "G", "S"]} for p in PANELS}
OOF = {(a, b): {p: [cca_oof(PCS[p][a], PCS[p][b], SEED + r) for r in range(CV_REPEATS)] for p in PANELS}
       for a, b in PAIRS}
cca_obs = {pr: {p: np.mean([oof_metrics(fo) for fo in OOF[pr][p]], axis=0) for p in PANELS} for pr in PAIRS}
cca_insample = {(a, b): {p: float(cca_fit(PCS[p][a], PCS[p][b])[2].mean()) for p in PANELS} for a, b in PAIRS}

cca_null = {pr: np.zeros((N_PERM_CCA, len(PANELS), 2)) for pr in PAIRS}
cca_null_in = {pr: np.zeros((N_PERM_CCA, len(PANELS))) for pr in PAIRS}
for j, p in enumerate(PANELS):
    n = len(pidx[p])
    for k in range(N_PERM_CCA):
        perm = rng.permutation(n)
        for a, b in PAIRS:
            cca_null[(a, b)][k, j] = oof_metrics(cca_oof(PCS[p][a], PCS[p][b][perm], SEED + 1000 + k))
            cca_null_in[(a, b)][k, j] = cca_fit(PCS[p][a], PCS[p][b][perm])[2].mean()
log("cca null done")

# bootstrap of held-out genes (CCA maps from the CV fits held fixed)
boot_cca = {pr: np.zeros((B_CCA, len(PANELS), 2)) for pr in PAIRS}
for bi in range(B_CCA):
    cu = np.bincount(rng.integers(0, NU, NU), minlength=NU)
    for j, p in enumerate(PANELS):
        c = cu[pidx[p]]
        for pr in PAIRS:
            boot_cca[pr][bi, j] = np.mean([oof_metrics(fo, c) for fo in OOF[pr][p]], axis=0)
    if bi % 250 == 0:
        log("cca boot", bi)
log("cca boot done")

# ------------------------------------------------------------------ assemble estimates
def est(name, value, samples, method):
    lo, hi = np.percentile(samples, [2.5, 97.5])
    return {"name": name, "value": float(value), "ci_low": float(lo), "ci_high": float(hi),
            "method_of_uncertainty": method}


def boot_txt(B, extra=""):
    return (f"95% percentile CI from a gene bootstrap: unit of resampling = gene; {B} replicates, genes drawn "
            f"with replacement from the union of the 3 panels ({NU} genes) so shared genes are resampled "
            f"consistently across panels" + extra)


RSA_NOTE = "; Spearman recomputed on each replicate, pairs between copies of the same gene excluded"
lab = {"M": "maxtoki", "G": "geneformer", "S": "scgpt"}
pm = lambda d: float(np.mean([d[p] for p in PANELS]))
E = []

# primary: RSA
for (v, a, b) in PRIMARY:
    E.append(est(f"rsa_{lab[a]}_{lab[b]}_mean3panels", pm(rsa_obs[(v, a, b)]), boot_rsa[(v, a, b)].mean(1),
                 boot_txt(B_RSA, RSA_NOTE)))
bMG, bMS, bGS = [boot_rsa[s] for s in PRIMARY]
oMG, oMS, oGS = [pm(rsa_obs[s]) for s in PRIMARY]
E.append(est("rsa_diff_maxtoki_geneformer_minus_maxtoki_scgpt_mean3panels", oMG - oMS,
             bMG.mean(1) - bMS.mean(1), boot_txt(B_RSA, RSA_NOTE + "; paired (same replicates)")))
E.append(est("rsa_ratio_maxtoki_scgpt_over_maxtoki_geneformer_mean3panels", oMS / oMG,
             bMS.mean(1) / bMG.mean(1), boot_txt(B_RSA, RSA_NOTE + "; paired (same replicates)")))
for j, p in enumerate(PANELS):
    for (v, a, b) in PRIMARY:
        E.append(est(f"rsa_{lab[a]}_{lab[b]}_{p}", rsa_obs[(v, a, b)][p], boot_rsa[(v, a, b)][:, j],
                     boot_txt(B_RSA, RSA_NOTE)))
    E.append(est(f"rsa_diff_maxtoki_geneformer_minus_maxtoki_scgpt_{p}",
                 rsa_obs[PRIMARY[0]][p] - rsa_obs[PRIMARY[1]][p], bMG[:, j] - bMS[:, j],
                 boot_txt(B_RSA, RSA_NOTE + "; paired")))


def partial(rxy, rxz, ryz):
    return (rxy - rxz * ryz) / np.sqrt((1 - rxz ** 2) * (1 - ryz ** 2))


E.append(est("partial_rsa_maxtoki_scgpt_given_geneformer_mean3panels", partial(oMS, oMG, oGS),
             partial(bMS.mean(1), bMG.mean(1), bGS.mean(1)), boot_txt(B_RSA, RSA_NOTE)))
E.append(est("partial_rsa_maxtoki_geneformer_given_scgpt_mean3panels", partial(oMG, oMS, oGS),
             partial(bMG.mean(1), bMS.mean(1), bGS.mean(1)), boot_txt(B_RSA, RSA_NOTE)))
# sensitivity RSA variants
for s in SENS:
    for k in ["MG", "MS"]:
        nm = {"MG": "maxtoki_geneformer", "MS": "maxtoki_scgpt"}[k]
        E.append(est(f"sens_{s}_rsa_{nm}_mean3panels", pm(sens_obs[s][k]), boot_sens[s][k].mean(1),
                     boot_txt(B_SENS, RSA_NOTE)))
    E.append(est(f"sens_{s}_rsa_diff_maxtoki_geneformer_minus_maxtoki_scgpt_mean3panels",
                 pm(sens_obs[s]["MG"]) - pm(sens_obs[s]["MS"]),
                 boot_sens[s]["MG"].mean(1) - boot_sens[s]["MS"].mean(1), boot_txt(B_SENS, RSA_NOTE + "; paired")))
# kNN overlap
KNN_NOTE = "; neighbour sets computed once on the full panel, per-gene overlap scores resampled"
for pr in PAIRS:
    a, b = pr
    E.append(est(f"knn{K_NN}_overlap_{lab[a]}_{lab[b]}_mean3panels",
                 np.mean([knn_gene[pr][p].mean() for p in PANELS]), boot_knn[pr].mean(1), boot_txt(B_RSA, KNN_NOTE)))
E.append(est(f"knn{K_NN}_overlap_diff_maxtoki_geneformer_minus_maxtoki_scgpt_mean3panels",
             np.mean([knn_gene[("M", "G")][p].mean() - knn_gene[("M", "S")][p].mean() for p in PANELS]),
             boot_knn[("M", "G")].mean(1) - boot_knn[("M", "S")].mean(1), boot_txt(B_RSA, KNN_NOTE + "; paired")))
# CV CCA
CCA_NOTE = ("; held-out genes resampled with the CV-fitted CCA maps and retrieval candidate sets held fixed "
            "(training-set variability not included)")
QN = [(0, "cv_cca_mean_canonical_corr"), (1, "cv_cca_top1_retrieval")]
for pr in PAIRS:
    a, b = pr
    for q, qn in QN:
        E.append(est(f"{qn}_{lab[a]}_{lab[b]}_mean3panels", np.mean([cca_obs[pr][p][q] for p in PANELS]),
                     boot_cca[pr][:, :, q].mean(1), boot_txt(B_CCA, CCA_NOTE)))
for q, qn in QN:
    E.append(est(f"{qn}_diff_maxtoki_geneformer_minus_maxtoki_scgpt_mean3panels",
                 np.mean([cca_obs[("M", "G")][p][q] - cca_obs[("M", "S")][p][q] for p in PANELS]),
                 boot_cca[("M", "G")][:, :, q].mean(1) - boot_cca[("M", "S")][:, :, q].mean(1),
                 boot_txt(B_CCA, CCA_NOTE + "; paired")))
for j, p in enumerate(PANELS):
    for pr in [("M", "G"), ("M", "S")]:
        a, b = pr
        for q, qn in QN:
            E.append(est(f"{qn}_{lab[a]}_{lab[b]}_{p}", cca_obs[pr][p][q], boot_cca[pr][:, j, q],
                         boot_txt(B_CCA, CCA_NOTE)))

# ------------------------------------------------------------------ chance levels / permutation p-values
def pval(obs, null):
    return float((1 + np.sum(null >= obs)) / (1 + len(null)))


nulls = {}
for pr in PAIRS:
    a, b = pr; key = f"{lab[a]}_{lab[b]}"
    s = ("cos", a, b); nm = mantel_null[pr].mean(1)
    nulls[f"rsa_{key}"] = {"obs_mean3": pm(rsa_obs[s]), "null_mean": float(nm.mean()),
                           "null_q95": float(np.percentile(nm, 95)), "p_mean3": pval(pm(rsa_obs[s]), nm),
                           "p_per_panel": {p: pval(rsa_obs[s][p], mantel_null[pr][:, j]) for j, p in enumerate(PANELS)},
                           "n_perm": N_PERM}
    kn = knn_null[pr].mean(1); obs = float(np.mean([knn_gene[pr][p].mean() for p in PANELS]))
    nulls[f"knn_{key}"] = {"obs_mean3": obs, "null_mean": float(kn.mean()), "null_q95": float(np.percentile(kn, 95)),
                           "p_mean3": pval(obs, kn), "n_perm": N_PERM_KNN,
                           "analytic_chance": float(np.mean([K_NN / (len(pidx[p]) - 1) for p in PANELS]))}
    for q, qn in [(0, "cv_cca_cc"), (1, "cv_cca_top1")]:
        cn = cca_null[pr][:, :, q].mean(1); obs = float(np.mean([cca_obs[pr][p][q] for p in PANELS]))
        nulls[f"{qn}_{key}"] = {"obs_mean3": obs, "null_mean": float(cn.mean()),
                                "null_q95": float(np.percentile(cn, 95)), "p_mean3": pval(obs, cn), "n_perm": N_PERM_CCA}
    ci_in = cca_null_in[pr].mean(1)
    nulls[f"insample_cca_cc_{key}"] = {"obs_mean3": pm(cca_insample[pr]), "null_mean": float(ci_in.mean()),
                                       "null_q95": float(np.percentile(ci_in, 95)), "n_perm": N_PERM_CCA,
                                       "per_panel": cca_insample[pr]}

# ------------------------------------------------------------------ verdict rule (pre-specified)
by = {e["name"]: e for e in E}
ms = by["rsa_maxtoki_scgpt_mean3panels"]
ratio = by["rsa_ratio_maxtoki_scgpt_over_maxtoki_geneformer_mean3panels"]
diff = by["rsa_diff_maxtoki_geneformer_minus_maxtoki_scgpt_mean3panels"]
cdiff = by["cv_cca_mean_canonical_corr_diff_maxtoki_geneformer_minus_maxtoki_scgpt_mean3panels"]
beyond_chance = (nulls["rsa_maxtoki_scgpt"]["p_mean3"] < 0.05 and ms["ci_low"] > 0 and
                 all(v < 0.05 for v in nulls["rsa_maxtoki_scgpt"]["p_per_panel"].values()))
panel_consistent = all(by[f"rsa_diff_maxtoki_geneformer_minus_maxtoki_scgpt_{p}"]["ci_low"] > 0 for p in PANELS)
if not beyond_chance:
    verdict = "not aligned with scGPT beyond chance"
elif diff["ci_low"] > 0 and ratio["ci_high"] < 0.8 and cdiff["ci_low"] > 0 and panel_consistent:
    verdict = "aligned with scGPT but clearly less than with Geneformer"
elif ratio["ci_low"] >= 0.8 and ratio["ci_high"] <= 1.25:
    verdict = "aligned with scGPT about as well as with Geneformer"
else:
    verdict = "inconclusive"

out = {"verdict": verdict, "estimates": E, "null_and_chance": nulls,
       "per_panel_rsa_sensitivity": {s: d for s, d in sens_obs.items()},
       "per_panel_knn": {f"{lab[a]}_{lab[b]}": {p: float(knn_gene[(a, b)][p].mean()) for p in PANELS} for a, b in PAIRS},
       "per_panel_cv_cca_GS": {p: [float(x) for x in cca_obs[("G", "S")][p]] for p in PANELS},
       "settings": {"seed": SEED, "B_rsa": B_RSA, "B_sens": B_SENS, "n_perm_mantel": N_PERM, "B_cca": B_CCA,
                    "n_perm_cca": N_PERM_CCA, "n_perm_knn": N_PERM_KNN, "cv_repeats": CV_REPEATS, "k_pc": K_PC,
                    "n_cc": N_CC, "folds": FOLDS, "k_nn": K_NN,
                    "n_genes": {p: int(len(pidx[p])) for p in PANELS}, "n_union": NU}}
print(json.dumps(out, indent=1))
log("done")

#!/usr/bin/env python
"""
Cross-model alignment of gene-embedding geometry:
MaxToki-217M (M) vs scGPT whole-human (S) vs Geneformer V2-316M (G),
on three gene panels (lung, immune, external_lung).

Run from the package root with
    <CODE_ROOT>/analysis-tasks/bin/python <this script>
Prints one JSON object (verdict, estimates, null/chance levels, per-panel values,
descriptive statistics) to stdout; progress goes to stderr.

Primary metric : RSA = Spearman correlation between two models' pairwise cosine-distance
                 vectors over the panel genes (embeddings centred within panel; scGPT rows
                 passed through the checkpoint's encoder LayerNorm), averaged over the panels.
Secondary      : (a) cross-validated whitened CCA (20 PCs per model, 10 canonical components,
                 5-fold CV over genes, 5 fold re-draws): held-out mean canonical correlation,
                 held-out mean squared canonical correlation, held-out top-1 gene retrieval;
                 (b) k=10 nearest-neighbour overlap.
Ratios         : M-S / M-G ratio with a paired bootstrap CI for every metric.
Confound checks: RSA after regressing each model's distance ranks on row-norm pair features
                 (a proxy for per-gene training intensity); whole-vocabulary RSA by quintile
                 of Geneformer row norm.
Uncertainty    : bootstrap over genes (unit of resampling = gene; genes drawn with replacement
                 from the union of the three panels so that genes shared between panels are
                 resampled consistently). Chance levels from gene-correspondence permutation
                 nulls (Mantel for RSA).
"""
import json, sys, time
import numpy as np
import pandas as pd

T0 = time.time()
SEED = 20261001
PANELS = ["lung", "immune", "external_lung"]
PAIRS = [("M", "G"), ("M", "S"), ("G", "S")]
B_RSA = 1000        # gene-bootstrap replicates for primary RSA and kNN
B_SENS = 300        # replicates for RSA sensitivity variants and norm-controlled RSA (first B_SENS)
N_PERM = 999        # Mantel permutations per panel
B_CCA = 1000        # gene-bootstrap replicates for CV-CCA and in-sample CCA (fixed maps)
N_PERM_CCA = 100    # gene-correspondence permutations for CCA
N_PERM_KNN = 200
CV_REPEATS = 5
K_PC, N_CC, FOLDS, K_NN = 20, 10, 5, 10
N_DRAWS, DRAW_N = 20, 380   # whole-vocabulary check: random gene sets per Geneformer-norm quintile
INIT_STD = 0.02             # initializer_range in the MaxToki and Geneformer configs
MARGIN = 0.8                # equivalence margin for the M-S/M-G ratio of the primary metric (RSA)


def log(*a):
    print(f"[{time.time() - T0:7.1f}s]", *a, file=sys.stderr, flush=True)


# ------------------------------------------------------------------ data
M_tab = np.load("data/maxtoki_217m/embed_tokens.npy").astype(np.float64)
G_tab = np.load("data/geneformer_v2_316m/word_embeddings.npy").astype(np.float64)
S_tab = np.load("data/scgpt_whole_human/encoder_embedding_weight.npy").astype(np.float64)
ln = np.load("data/scgpt_whole_human/encoder_enc_norm.npz")
mt_dict = json.load(open("data/maxtoki_217m/token_dictionary.json"))
gf_dict = json.load(open("data/geneformer_v2_316m/token_dictionary.json"))
sg_vocab = json.load(open("data/scgpt_whole_human/vocab.json"))
e2s = dict(pd.read_csv("data/gene_ids/ensembl_symbol.csv")[["ensembl_id", "symbol"]].values)
panels = {p: pd.read_csv(f"data/panels/{p}.csv")["ensembl_id"].tolist() for p in PANELS}

union = sorted(set().union(*panels.values()))
for g in union:  # every panel gene must map in all three models; M and G share token ids
    assert g in mt_dict and g in gf_dict and mt_dict[g] == gf_dict[g], g
    assert g in e2s and e2s[g] in sg_vocab, g
tok = np.array([mt_dict[g] for g in union])          # MaxToki == Geneformer token id
stok = np.array([sg_vocab[e2s[g]] for g in union])   # scGPT token id via gene symbol
assert tok.min() >= 4 and tok.max() < M_tab.shape[0] and tok.max() < G_tab.shape[0]


def scgpt_layernorm(X):
    """scGPT GeneEncoder = embedding row followed by LayerNorm enc_norm."""
    mu = X.mean(1, keepdims=True)
    var = X.var(1, keepdims=True)
    return (X - mu) / np.sqrt(var + float(ln["eps"])) * ln["weight"] + ln["bias"]


XU = {"M": M_tab[tok], "G": G_tab[tok], "S": scgpt_layernorm(S_tab[stok]), "Sraw": S_tab[stok]}
# log row norm of the raw table rows: proxy for how strongly each gene's row was trained
LOGN = {"M": np.log(np.linalg.norm(M_tab[tok], axis=1)), "G": np.log(np.linalg.norm(G_tab[tok], axis=1)),
        "S": np.log(np.linalg.norm(S_tab[stok], axis=1))}
pos = {g: i for i, g in enumerate(union)}
pidx = {p: np.array([pos[g] for g in panels[p]]) for p in PANELS}
NU = len(union)
log("panels", {p: len(v) for p, v in pidx.items()}, "union", NU)


def centred(X):
    return X - X.mean(0)


def cos_dist(X):
    Xc = centred(X)
    Xn = Xc / np.linalg.norm(Xc, axis=1, keepdims=True)
    return 1.0 - Xn @ Xn.T


def euc_dist(X):
    Xc = centred(X)
    sq = (Xc ** 2).sum(1)
    return np.sqrt(np.maximum(sq[:, None] + sq[None, :] - 2 * Xc @ Xc.T, 0))


def remove_top_pcs(X, r):
    Xc = centred(X)
    w, U = np.linalg.eigh(Xc @ Xc.T)
    Ur = U[:, np.argsort(w)[::-1][:r]]
    return Xc - Ur @ (Ur.T @ Xc)


def ranks(v):
    o = np.argsort(v, kind="mergesort")
    r = np.empty(len(v)); r[o] = np.arange(1, len(v) + 1)
    return r


def pearson(x, y):
    x = x - x.mean(); y = y - y.mean()
    return float(x @ y / np.sqrt((x @ x) * (y @ y)))


def wpearson(x, y, w):
    sw = w.sum(); dx = x - (w @ x) / sw; dy = y - (w @ y) / sw
    return float((w * dx) @ dy / np.sqrt(((w * dx) @ dx) * ((w * dy) @ dy)))


def wranks(order, w):
    """Mid-ranks of every pair in the bootstrap-expanded sample, where pair p occurs w_p times.
    Spearman on the expanded sample == weighted Pearson of these mid-ranks with weights w."""
    ws = w[order]
    r = np.empty(len(w)); r[order] = np.cumsum(ws) - ws / 2.0 + 0.5
    return r


def wresid(r, F, w):
    """Residual of r after weighted least-squares regression on the columns of F."""
    FtW = F.T * w
    return r - F @ np.linalg.solve(FtW @ F, FtW @ r)


# ------------------------------------------------------------------ per-panel distance views
# key = (view, model); primary view is "cos" on M, G, S (scGPT after LayerNorm)
VIEW_FUN = {"cos": cos_dist, "euc": euc_dist, "rmPC1": lambda X: cos_dist(remove_top_pcs(X, 1))}
VIEW_KEYS = [("cos", "M"), ("cos", "G"), ("cos", "S"), ("cos", "Sraw"),
             ("euc", "M"), ("euc", "G"), ("euc", "S"),
             ("rmPC1", "M"), ("rmPC1", "G"), ("rmPC1", "S")]
PRIMARY = [("cos", a, b) for a, b in PAIRS]
SENS = {
    "rawS": {"MG": (("cos", "M"), ("cos", "G")), "MS": (("cos", "M"), ("cos", "Sraw"))},
    "euc": {"MG": (("euc", "M"), ("euc", "G")), "MS": (("euc", "M"), ("euc", "S"))},
    "rmPC1": {"MG": (("rmPC1", "M"), ("rmPC1", "G")), "MS": (("rmPC1", "M"), ("rmPC1", "S"))},
}
PD, IU, NF = {}, {}, {}
for p in PANELS:
    n = len(pidx[p]); iu = np.triu_indices(n, 1); IU[p] = iu; PD[p] = {}
    for (v, m) in VIEW_KEYS:
        D = VIEW_FUN[v](XU[m][pidx[p]]); d = D[iu]
        PD[p][(v, m)] = {"D": D, "r": ranks(d), "o": np.argsort(d, kind="mergesort")}
    # row-norm pair features of all three models (same nuisance space removed from every model)
    cols = [np.ones(len(iu[0]))]
    for m in ["M", "G", "S"]:
        lg = LOGN[m][pidx[p]]; cols += [np.abs(lg[iu[0]] - lg[iu[1]]), lg[iu[0]] + lg[iu[1]]]
    NF[p] = np.column_stack(cols)
log("distances done")

rsa_obs = {(v, a, b): {p: pearson(PD[p][(v, a)]["r"], PD[p][(v, b)]["r"]) for p in PANELS}
           for (v, a, b) in PRIMARY}
sens_obs = {s: {k: {p: pearson(PD[p][ka]["r"], PD[p][kb]["r"]) for p in PANELS}
                for k, (ka, kb) in d.items()} for s, d in SENS.items()}
nc_res = {p: {m: wresid(PD[p][("cos", m)]["r"], NF[p], np.ones(len(IU[p][0]))) for m in "MGS"} for p in PANELS}
nc_obs = {(a, b): {p: pearson(nc_res[p][a], nc_res[p][b]) for p in PANELS} for a, b in PAIRS}

rng = np.random.default_rng(SEED)

# ------------------------------------------------------------------ Mantel permutation null (primary view)
mantel_null = {pr: np.zeros((N_PERM, len(PANELS))) for pr in PAIRS}
for j, p in enumerate(PANELS):
    n = len(pidx[p]); i0, j0 = IU[p]
    Rfull, rc = {}, {}
    for m in ["M", "G", "S"]:
        R = np.zeros((n, n)); R[i0, j0] = PD[p][("cos", m)]["r"]; Rfull[m] = R + R.T
        rc[m] = PD[p][("cos", m)]["r"] - PD[p][("cos", m)]["r"].mean()
    ss = rc["M"] @ rc["M"]   # all rank vectors are permutations of 1..P -> same sum of squares
    for k in range(N_PERM):
        perm = rng.permutation(n); pi, pj = perm[i0], perm[j0]
        for a, b in PAIRS:
            mantel_null[(a, b)][k, j] = (rc[a] @ Rfull[b][pi, pj]) / ss
log("mantel done")


# ------------------------------------------------------------------ kNN overlap (per-gene scores)
def knn_sets(D, k):
    D = D.copy(); np.fill_diagonal(D, np.inf)
    return np.argsort(D, axis=1)[:, :k]


knn_gene = {pr: {} for pr in PAIRS}
knn_null = {pr: np.zeros((N_PERM_KNN, len(PANELS))) for pr in PAIRS}
for j, p in enumerate(PANELS):
    n = len(pidx[p]); rows = np.repeat(np.arange(n), K_NN)
