# ------------------------------------------------------------------ CCA (cross-validated and in-sample)
def pc_scores(X, k):
    """Unit-variance scores on the top-k principal components (unsupervised, per model)."""
    Xc = centred(X)
    w, U = np.linalg.eigh(Xc @ Xc.T)
    return U[:, np.argsort(w)[::-1][:k]] * np.sqrt(len(X) - 1)


def inv_sqrt(C):
    w, V = np.linalg.eigh(C)
    return (V / np.sqrt(w)) @ V.T


def cca_fit(a, b, reg=1e-3):
    m = len(a); ma, mb = a.mean(0), b.mean(0); a = a - ma; b = b - mb
    Wa = inv_sqrt(a.T @ a / (m - 1) + reg * np.eye(a.shape[1]))
    Wb = inv_sqrt(b.T @ b / (m - 1) + reg * np.eye(b.shape[1]))
    U, s, Vt = np.linalg.svd(Wa @ (a.T @ b / (m - 1)) @ Wb)
    return Wa @ U[:, :N_CC], Wb @ Vt.T[:, :N_CC], s[:N_CC], ma, mb


def wcc(Pa, Pb, w=None):
    """Per-component (weighted) Pearson correlation between paired canonical projections."""
    w = np.ones(len(Pa)) if w is None else w
    sw = w.sum(); da = Pa - (w @ Pa) / sw; db = Pb - (w @ Pb) / sw
    return ((w[:, None] * da) * db).sum(0) / np.sqrt(((w[:, None] * da) * da).sum(0) * ((w[:, None] * db) * db).sum(0))


def cca_oof(A, B, seed):
    """5-fold CV over genes. For each fold returns (test idx, Pa, Pb, hit): held-out genes projected
    with the CCA maps fitted on the other folds, and whether each held-out gene's A-projection
    retrieves its own B-projection (top-1 cosine among all held-out genes of the fold)."""
    f = np.random.default_rng(seed).permutation(len(A)) % FOLDS
    out = []
    for k in range(FOLDS):
        te = np.where(f == k)[0]; tr = np.where(f != k)[0]
        Wa, Wb, _, ma, mb = cca_fit(A[tr], B[tr])
        Pa = (A[te] - ma) @ Wa; Pb = (B[te] - mb) @ Wb
        na = Pa / np.linalg.norm(Pa, axis=1, keepdims=True); nb = Pb / np.linalg.norm(Pb, axis=1, keepdims=True)
        out.append((te, Pa, Pb, ((na @ nb.T).argmax(1) == np.arange(len(te))).astype(float)))
    return out


def oof_metrics(folds, c=None):
    """Held-out (mean canonical correlation, top-1 retrieval, mean squared canonical correlation),
    averaged over folds. c = optional bootstrap gene counts used as weights (candidate sets fixed)."""
    ccs, ccs2, hits, tot = [], [], 0.0, 0.0
    for te, Pa, Pb, hit in folds:
        w = np.ones(len(te)) if c is None else c[te].astype(float)
        if (w > 0).sum() < 3:
            continue
        cc = wcc(Pa, Pb, w)
        ccs.append(cc.mean()); ccs2.append((cc ** 2).mean())
        hits += w @ hit; tot += w.sum()
    return float(np.mean(ccs)), hits / tot, float(np.mean(ccs2))


def ins_cc(fit, A, B, w=None):
    """In-sample mean canonical correlation: maps fitted on all panel genes, evaluated on the same genes."""
    Wa, Wb, _, ma, mb = fit
    return float(wcc((A - ma) @ Wa, (B - mb) @ Wb, w).mean())


