                           "p_per_panel": {p: pval(rsa_obs[s][p], mantel_null[pr][:, j]) for j, p in enumerate(PANELS)},
                           "n_perm": N_PERM}
    kn = knn_null[pr].mean(1); obs = float(np.mean([knn_gene[pr][p].mean() for p in PANELS]))
    nulls[f"knn_{key}"] = {"obs_mean3": obs, "null_mean": float(kn.mean()), "null_q95": float(np.percentile(kn, 95)),
                           "p_mean3": pval(obs, kn), "n_perm": N_PERM_KNN, "analytic_chance": float(KNN_CHANCE.mean())}
    for q, qn in [(0, "cv_cca_cc"), (1, "cv_cca_top1"), (2, "cv_cca_cc2")]:
        cn = cca_null[pr][:, :, q].mean(1); obs = float(np.mean([cca_obs[pr][p][q] for p in PANELS]))
        nulls[f"{qn}_{key}"] = {"obs_mean3": obs, "null_mean": float(cn.mean()),
                                "null_q95": float(np.percentile(cn, 95)), "p_mean3": pval(obs, cn), "n_perm": N_PERM_CCA}
    ci_in = cca_null_in[pr].mean(1)
    nulls[f"insample_cca_cc_{key}"] = {"obs_mean3": pm(cca_insample[pr]), "null_mean": float(ci_in.mean()),
                                       "null_q95": float(np.percentile(ci_in, 95)), "n_perm": N_PERM_CCA,
                                       "per_panel": cca_insample[pr]}

# ------------------------------------------------------------------ verdict rule
# Rule set after exploratory analyses (not pre-registered). The 0.8 margin is a convention and is applied
# to the primary metric (RSA, which behaves like a squared correlation). ratio_scale_check reports how every
# metric's M-S/M-G ratio sits against the same margin, so the dependence of the label on scale is visible.
by = {e["name"]: e for e in E}


def band(e):
    lo, hi = e["ci_low"], e["ci_high"]
    if hi < MARGIN:
        return "below margin"
    if lo >= MARGIN and hi <= 1 / MARGIN:
        return "within [0.8, 1.25]"
    return "straddles margin"


RATIOS = {  # name -> scale of the underlying metric
    "rsa_ratio_maxtoki_scgpt_over_maxtoki_geneformer_mean3panels": "shared-variance (RSA of distances ~ squared correlation)",
    "cv_cca_mean_sq_canonical_corr_ratio_maxtoki_scgpt_over_maxtoki_geneformer_mean3panels": "shared-variance (squared canonical correlation)",
    "rsa_ratio_sqrt_maxtoki_scgpt_over_maxtoki_geneformer_mean3panels": "correlation (square root of RSA ratio)",
    "cv_cca_mean_canonical_corr_ratio_maxtoki_scgpt_over_maxtoki_geneformer_mean3panels": "correlation (canonical correlation)",
    "cv_cca_top1_retrieval_ratio_maxtoki_scgpt_over_maxtoki_geneformer_mean3panels": "proportion (gene-level retrieval)",
    "knn10_overlap_ratio_maxtoki_scgpt_over_maxtoki_geneformer_mean3panels": "proportion (neighbour overlap)",
    "knn10_overlap_above_chance_ratio_maxtoki_scgpt_over_maxtoki_geneformer_mean3panels": "proportion above chance",
    "normctrl_rsa_ratio_maxtoki_scgpt_over_maxtoki_geneformer_mean3panels": "shared-variance, norm-controlled",
    "insample_cca_mean_canonical_corr_ratio_maxtoki_scgpt_over_maxtoki_geneformer_mean3panels": "correlation, in-sample (overfit)",
}
ratio_scale_check = {k: {"scale": sc, "value": by[k]["value"], "ci": [by[k]["ci_low"], by[k]["ci_high"]],
                         "vs_margin": band(by[k])} for k, sc in RATIOS.items()}
ms = by["rsa_maxtoki_scgpt_mean3panels"]
r_rsa = by["rsa_ratio_maxtoki_scgpt_over_maxtoki_geneformer_mean3panels"]
diff = by["rsa_diff_maxtoki_geneformer_minus_maxtoki_scgpt_mean3panels"]
cdiff = by["cv_cca_mean_canonical_corr_diff_maxtoki_geneformer_minus_maxtoki_scgpt_mean3panels"]
beyond_chance = (nulls["rsa_maxtoki_scgpt"]["p_mean3"] < 0.05 and ms["ci_low"] > 0 and
                 all(v < 0.05 for v in nulls["rsa_maxtoki_scgpt"]["p_per_panel"].values()))
panel_consistent = all(by[f"rsa_diff_maxtoki_geneformer_minus_maxtoki_scgpt_{p}"]["ci_low"] > 0 for p in PANELS)
all_ratio_ci_below_1 = all(v["ci"][1] < 1 for v in ratio_scale_check.values())
if not beyond_chance:
    verdict = "not aligned with scGPT beyond chance"
elif (diff["ci_low"] > 0 and cdiff["ci_low"] > 0 and panel_consistent and all_ratio_ci_below_1
      and band(r_rsa) == "below margin"):
    verdict = "aligned with scGPT but clearly less than with Geneformer"
elif band(r_rsa).startswith("within"):
    verdict = "aligned with scGPT about as well as with Geneformer"
else:
    verdict = "inconclusive"

out = {"verdict": verdict, "estimates": E, "null_and_chance": nulls, "ratio_scale_check": ratio_scale_check,
       "rule_inputs": {"beyond_chance": beyond_chance, "panel_consistent": panel_consistent,
                       "all_ratio_ci_upper_below_1": all_ratio_ci_below_1, "margin_primary_metric": MARGIN},
       "descriptive": descriptive,
       "per_panel_rsa_sensitivity": {s: d for s, d in sens_obs.items()},
       "per_panel_norm_controlled_rsa": {f"{lab[a]}_{lab[b]}": nc_obs[(a, b)] for a, b in PAIRS},
       "per_panel_knn": {f"{lab[a]}_{lab[b]}": {p: float(knn_gene[(a, b)][p].mean()) for p in PANELS} for a, b in PAIRS},
       "per_panel_cv_cca_GS": {p: [float(x) for x in cca_obs[("G", "S")][p]] for p in PANELS},
       "settings": {"seed": SEED, "B_rsa": B_RSA, "B_sens": B_SENS, "n_perm_mantel": N_PERM, "B_cca": B_CCA,
                    "n_perm_cca": N_PERM_CCA, "n_perm_knn": N_PERM_KNN, "cv_repeats": CV_REPEATS, "k_pc": K_PC,
                    "n_cc": N_CC, "folds": FOLDS, "k_nn": K_NN, "n_draws": N_DRAWS, "draw_n": DRAW_N,
                    "n_genes": {p: int(len(pidx[p])) for p in PANELS}, "n_union": NU}}
print(json.dumps(out, indent=1))
log("done")

#!/usr/bin/env python
"""
Cross-model alignment of gene-embedding geometry:
MaxToki-217M (M) vs scGPT whole-human (S) vs Geneformer V2-316M (G),
on three gene panels (lung, immune, external_lung), plus random gene sets as a held-out condition.

Run from the package root with
    <CODE_ROOT>/analysis-tasks/bin/python <this script>
Prints one JSON object (verdict, estimates, null/chance levels, descriptive checks, per-metric
ratio classification) to stdout; progress goes to stderr. Runtime about 2-7 minutes depending on load.

Primary metric : RSA = Spearman correlation between two models' pairwise cosine-distance matrices
                 over the panel genes (full-dimensional embeddings centred within panel; scGPT rows
                 passed through the checkpoint's encoder LayerNorm), averaged over the three panels.
Secondary      : (a) cross-validated whitened CCA (20 PCs per model, 10 canonical components,
                 5-fold CV over genes, 5 fold draws): held-out mean canonical correlation and top-1
                 retrieval; (b) k-nearest-neighbour overlap (k = 5, 10, 20, 50).
Sensitivity    : raw scGPT rows; top PC removed; cosine and Euclidean RSA on the top 5/10/20/50/100
                 PCs and on the full dimension; random gene sets from the whole vocabulary.
Uncertainty    : gene bootstrap (genes drawn with replacement from the union of the three panels, so
                 genes shared between panels are resampled consistently); grouped jackknife with every
                 step refitted (CV-CCA, in-sample CCA, kNN); random gene sets resampled as units.
                 Chance levels from gene-correspondence permutation nulls (Mantel for RSA).
"""
import json, sys, time
import numpy as np
import pandas as pd
from scipy.stats import spearmanr, t as t_dist

T0 = time.time()
SEED = 20261001
PANELS = ["lung", "immune", "external_lung"]
PAIRS = [("M", "G"), ("M", "S"), ("G", "S")]
B_RSA = 1000        # gene-bootstrap replicates for primary RSA and kNN
B_SENS = 300        # replicates for RSA sensitivity variants (first B_SENS replicates)
N_PERM = 999        # Mantel permutations per panel
B_CCA = 1000        # fixed-map gene-bootstrap replicates for CV-CCA
N_PERM_CCA = 100    # gene-correspondence permutations for CV-CCA
N_PERM_KNN = 200    # gene-correspondence permutations for kNN (k = 10)
CV_REPEATS = 5
K_PC, N_CC, FOLDS, K_NN = 20, 10, 5, 10
PCA_DIMS = [5, 10, 20, 50, 100]
KNN_KS = [5, 10, 20, 50]
N_JACK, N_JACK_REP = 20, 5                  # grouped jackknife: 20 groups, 5 random groupings
N_RAND, RAND_SIZE, B_SETS = 50, 380, 2000   # random gene sets (held-out condition)
BAND = (0.8, 1.25)  # "about as well" band for the M-S / M-G ratio


def log(*a):
    print(f"[{time.time() - T0:7.1f}s]", *a, file=sys.stderr, flush=True)


def rnd(x, k=4):
    if isinstance(x, dict):
        return {str(a): rnd(b, k) for a, b in x.items()}
    if isinstance(x, (list, tuple)):
        return [rnd(b, k) for b in x]
    if isinstance(x, (float, np.floating)):
        return round(float(x), k)
    return x


# ------------------------------------------------------------------ data
M_tab = np.load("data/maxtoki_217m/embed_tokens.npy").astype(np.float64)
G_tab = np.load("data/geneformer_v2_316m/word_embeddings.npy").astype(np.float64)
S_tab = np.load("data/scgpt_whole_human/encoder_embedding_weight.npy").astype(np.float64)
ln = np.load("data/scgpt_whole_human/encoder_enc_norm.npz")
mt_dict = json.load(open("data/maxtoki_217m/token_dictionary.json"))
gf_dict = json.load(open("data/geneformer_v2_316m/token_dictionary.json"))
sg_vocab = json.load(open("data/scgpt_whole_human/vocab.json"))
e2s = dict(pd.read_csv("data/gene_ids/ensembl_symbol.csv")[["ensembl_id", "symbol"]].values)
panels = {p: pd.read_csv(f"data/panels/{p}.csv")["ensembl_id"].tolist() for p in PANELS}

union = sorted(set().union(*panels.values()))
for g in union:  # every panel gene must map in all three models; M and G share token ids
    assert g in mt_dict and g in gf_dict and mt_dict[g] == gf_dict[g], g
    assert g in e2s and e2s[g] in sg_vocab, g
tok = np.array([mt_dict[g] for g in union])          # MaxToki == Geneformer token id
stok = np.array([sg_vocab[e2s[g]] for g in union])   # scGPT token id via gene symbol
assert tok.min() >= 4 and tok.max() < M_tab.shape[0] and tok.max() < G_tab.shape[0]


def scgpt_layernorm(X):
    """scGPT GeneEncoder = embedding row followed by LayerNorm enc_norm."""
    mu = X.mean(1, keepdims=True)
    var = X.var(1, keepdims=True)
    return (X - mu) / np.sqrt(var + float(ln["eps"])) * ln["weight"] + ln["bias"]


XU = {"M": M_tab[tok], "G": G_tab[tok], "S": scgpt_layernorm(S_tab[stok]), "Sraw": S_tab[stok]}
pos = {g: i for i, g in enumerate(union)}
pidx = {p: np.array([pos[g] for g in panels[p]]) for p in PANELS}
NU = len(union)
log("panels", {p: len(v) for p, v in pidx.items()}, "union", NU)


def centred(X):
    return X - X.mean(0)


def cos_dist(X):
    Xc = centred(X)
    Xn = Xc / np.linalg.norm(Xc, axis=1, keepdims=True)
    return 1.0 - Xn @ Xn.T


def euc_dist(X):
    Xc = centred(X)
    sq = (Xc ** 2).sum(1)
    return np.sqrt(np.maximum(sq[:, None] + sq[None, :] - 2 * Xc @ Xc.T, 0))


def ranks(v):
    o = np.argsort(v, kind="mergesort")
    r = np.empty(len(v)); r[o] = np.arange(1, len(v) + 1)
    return r


def pearson(x, y):
    x = x - x.mean(); y = y - y.mean()
    return float(x @ y / np.sqrt((x @ x) * (y @ y)))


def wpearson(x, y, w):
    sw = w.sum(); dx = x - (w @ x) / sw; dy = y - (w @ y) / sw
    return float((w * dx) @ dy / np.sqrt(((w * dx) @ dx) * ((w * dy) @ dy)))


def wranks(order, w):
    """Mid-ranks of every pair in the bootstrap-expanded sample, where pair p occurs w_p times.
    Spearman on the expanded sample == weighted Pearson of these mid-ranks with weights w."""
    ws = w[order]
    r = np.empty(len(w)); r[order] = np.cumsum(ws) - ws / 2.0 + 0.5
    return r


# ------------------------------------------------------------------ descriptive checks (exact properties of the tables)
def spectrum(X):
    Xc = X - X.mean(0)
    w = np.linalg.eigvalsh(Xc.T @ Xc / (len(X) - 1))
    n, d = X.shape
    edge = w.mean() * (1 + np.sqrt(d / n)) ** 2   # Marchenko-Pastur edge, sigma^2 = mean eigenvalue
    return {"rows": int(n), "dim": int(d), "participation_ratio": float(w.sum() ** 2 / (w ** 2).sum()),
            "n_eig_above_mp_edge": int((w > edge).sum()),
            "median_row_norm": float(np.median(np.linalg.norm(X, axis=1))),
            "init_scale_norm_0.02_sqrt_dim": float(0.02 * np.sqrt(d))}


gene_tok = np.array(sorted(v for k, v in gf_dict.items() if k.startswith("ENSG")))
s_rows = np.array(sorted(v for k, v in sg_vocab.items() if not k.startswith("<")))
desc = {"maxtoki_gene_rows": spectrum(M_tab[gene_tok]), "geneformer_gene_rows": spectrum(G_tab[gene_tok]),
        "scgpt_rows_layernorm": spectrum(scgpt_layernorm(S_tab[s_rows])), "scgpt_rows_raw": spectrum(S_tab[s_rows]),
        "row_norm_spearman_maxtoki_vs_geneformer_all_genes": float(spearmanr(
            np.linalg.norm(M_tab[gene_tok], axis=1), np.linalg.norm(G_tab[gene_tok], axis=1))[0])}
ps = {p: set(panels[p]) for p in PANELS}
desc["panel_overlap"] = {"lung_and_external_lung": len(ps["lung"] & ps["external_lung"]),
                         "lung_and_immune": len(ps["lung"] & ps["immune"]),
                         "immune_and_external_lung": len(ps["immune"] & ps["external_lung"]),
                         "all_three": len(ps["lung"] & ps["immune"] & ps["external_lung"]), "union": NU}
adj, cnorm = {}, {}
for p in PANELS:
    t = tok[pidx[p]]; iu = np.triu_indices(len(t), 1); did = np.abs(t[:, None] - t[None, :])[iu]
    for m in ["M", "G"]:
        adj[f"{p}_{m}"] = float(spearmanr(cos_dist(XU[m][pidx[p]])[iu], did)[0])
    nr = {}
    for m in ["M", "G", "S"]:
        Xc = centred(XU[m][pidx[p]]); U, s, Vt = np.linalg.svd(Xc, full_matrices=False)
        nr[m] = (np.linalg.norm(Xc, axis=1), np.linalg.norm(U[:, :K_PC] * s[:K_PC], axis=1))
    cnorm[p] = {f"{a}{b}_{v}": float(spearmanr(nr[a][i], nr[b][i])[0])
                for a, b in PAIRS for i, v in enumerate(["full", f"top{K_PC}pcs"])}
desc["spearman_cosdist_vs_abs_token_id_difference"] = adj
desc["within_panel_centred_row_norm_spearman"] = cnorm
log("descriptive done")

# ------------------------------------------------------------------ per-panel distance views
# key = (view, model). Primary view: "cos" (full-dimensional cosine) on M, G, S (scGPT after LayerNorm).
PD, IU, DCOS, pcvar = {}, {}, {}, {}
for p in PANELS:
    n = len(pidx[p]); iu = np.triu_indices(n, 1); IU[p] = iu; PD[p] = {}; DCOS[p] = {}; pcvar[p] = {}
    for m in ["M", "G", "S", "Sraw"]:
        X = XU[m][pidx[p]]
        views = {"cos": cos_dist(X)}
        if m != "Sraw":
            Xc = centred(X); U, s, Vt = np.linalg.svd(Xc, full_matrices=False)
            views["euc"] = euc_dist(X)
            views["rmPC1"] = cos_dist(Xc - np.outer(U[:, 0] * s[0], Vt[0]))
            for k in PCA_DIMS:
                Z = U[:, :k] * s[:k]
                views[f"cosPC{k}"] = cos_dist(Z); views[f"eucPC{k}"] = euc_dist(Z)
            pcvar[p][m] = {k: float((s[:k] ** 2).sum() / (s ** 2).sum()) for k in PCA_DIMS}
        for v, D in views.items():
            d = D[iu]; PD[p][(v, m)] = {"r": ranks(d), "o": np.argsort(d, kind="mergesort")}
        DCOS[p][m] = views["cos"]
desc["within_panel_variance_fraction_top_k_pcs"] = pcvar
PRIMARY = [("cos", a, b) for a, b in PAIRS]
SENS = {"rawS": {"MG": (("cos", "M"), ("cos", "G")), "MS": (("cos", "M"), ("cos", "Sraw")),
                 "GS": (("cos", "G"), ("cos", "Sraw"))}}
for v in ["rmPC1", "euc"] + [f"{t}PC{k}" for t in ["cos", "euc"] for k in PCA_DIMS]:
    SENS[v] = {a + b: ((v, a), (v, b)) for a, b in PAIRS}
log("distances done")

rsa_obs = {(v, a, b): {p: pearson(PD[p][(v, a)]["r"], PD[p][(v, b)]["r"]) for p in PANELS}
           for (v, a, b) in PRIMARY}
sens_obs = {s: {k: {p: pearson(PD[p][ka]["r"], PD[p][kb]["r"]) for p in PANELS}
                for k, (ka, kb) in d.items()} for s, d in SENS.items()}

rng = np.random.default_rng(SEED)

# ------------------------------------------------------------------ Mantel permutation null (primary view)
mantel_null = {pr: np.zeros((N_PERM, len(PANELS))) for pr in PAIRS}
for j, p in enumerate(PANELS):
    n = len(pidx[p]); i0, j0 = IU[p]
    Rfull, rc = {}, {}
    for m in ["M", "G", "S"]:
        R = np.zeros((n, n)); R[i0, j0] = PD[p][("cos", m)]["r"]; Rfull[m] = R + R.T
        rc[m] = PD[p][("cos", m)]["r"] - PD[p][("cos", m)]["r"].mean()
    ss = rc["M"] @ rc["M"]   # all rank vectors are permutations of 1..P -> same sum of squares
    for k in range(N_PERM):
        perm = rng.permutation(n); pi, pj = perm[i0], perm[j0]
        for a, b in PAIRS:
            mantel_null[(a, b)][k, j] = (rc[a] @ Rfull[b][pi, pj]) / ss
log("mantel done")


# ------------------------------------------------------------------ kNN overlap (per-gene scores)
def knn_sets(D, k):
    D = D.copy(); np.fill_diagonal(D, np.inf)
    return np.argsort(D, axis=1)[:, :k]


def knn_masks(D, k):
    n = len(D); A = np.zeros((n, n), bool); A[np.repeat(np.arange(n), k), knn_sets(D, k).ravel()] = True
    return A


knn_gene = {kk: {pr: {} for pr in PAIRS} for kk in KNN_KS}
knn_null = {pr: np.zeros((N_PERM_KNN, len(PANELS))) for pr in PAIRS}
for j, p in enumerate(PANELS):
    n = len(pidx[p])
    for kk in KNN_KS:
        Ak = {m: knn_masks(DCOS[p][m], kk) for m in ["M", "G", "S"]}
        for a, b in PAIRS:
            knn_gene[kk][(a, b)][p] = (Ak[a] & Ak[b]).sum(1) / kk
        if kk == K_NN:
            Amask = Ak
    NN = {m: knn_sets(DCOS[p][m], K_NN) for m in ["M", "G", "S"]}
    rows = np.repeat(np.arange(n), K_NN)
    for k in range(N_PERM_KNN):
        perm = rng.permutation(n); pinv = np.argsort(perm)
        for a, b in PAIRS:
            Bp = np.zeros((n, n), bool); Bp[rows, pinv[NN[b][perm]].ravel()] = True
            knn_null[(a, b)][k, j] = ((Amask[a] & Bp).sum(1) / K_NN).mean()
log("knn done")

# ------------------------------------------------------------------ gene bootstrap: RSA (+ sensitivity) and kNN
boot_rsa = {s: np.zeros((B_RSA, len(PANELS))) for s in PRIMARY}
boot_sens = {s: {k: np.zeros((B_SENS, len(PANELS))) for k in d} for s, d in SENS.items()}
boot_knn = {kk: {pr: np.zeros((B_RSA, len(PANELS))) for pr in PAIRS} for kk in KNN_KS}
prim_keys = [("cos", "M"), ("cos", "G"), ("cos", "S")]
sens_keys = sorted({kk for d in SENS.values() for pair in d.values() for kk in pair} - set(prim_keys))
for bi in range(B_RSA):
    cu = np.bincount(rng.integers(0, NU, NU), minlength=NU).astype(float)
    for j, p in enumerate(PANELS):
        c = cu[pidx[p]]; i0, j0 = IU[p]; w = c[i0] * c[j0]
        R = {key: wranks(PD[p][key]["o"], w) for key in prim_keys}
        for (v, a, b) in PRIMARY:
            boot_rsa[(v, a, b)][bi, j] = wpearson(R[(v, a)], R[(v, b)], w)
        if bi < B_SENS:
            for key in sens_keys:
                R[key] = wranks(PD[p][key]["o"], w)
            for s, d in SENS.items():
                for k, (ka, kb) in d.items():
                    boot_sens[s][k][bi, j] = wpearson(R[ka], R[kb], w)
        for kk in KNN_KS:
            for pr in PAIRS:
                boot_knn[kk][pr][bi, j] = (c @ knn_gene[kk][pr][p]) / c.sum()
    if bi % 250 == 0:
        log("rsa boot", bi)
log("rsa boot done")


# ------------------------------------------------------------------ cross-validated CCA
def pc_scores(X, k):
    """Unit-variance scores on the top-k principal components (unsupervised, per model)."""
    Xc = centred(X)
    w, U = np.linalg.eigh(Xc @ Xc.T)
    return U[:, np.argsort(w)[::-1][:k]] * np.sqrt(len(X) - 1)


def inv_sqrt(C):
    w, V = np.linalg.eigh(C)
    return (V / np.sqrt(w)) @ V.T


def cca_fit(a, b, reg=1e-3):
    m = len(a); ma, mb = a.mean(0), b.mean(0); a = a - ma; b = b - mb
    Wa = inv_sqrt(a.T @ a / (m - 1) + reg * np.eye(a.shape[1]))
    Wb = inv_sqrt(b.T @ b / (m - 1) + reg * np.eye(b.shape[1]))
    U, s, Vt = np.linalg.svd(Wa @ (a.T @ b / (m - 1)) @ Wb)
    return Wa @ U[:, :N_CC], Wb @ Vt.T[:, :N_CC], s[:N_CC], ma, mb


def cca_oof_labels(A, B, f):
    """CV with given fold labels f: held-out genes projected with the CCA maps fitted on the other folds."""
    out = []
    for k in range(FOLDS):
        te = np.where(f == k)[0]; tr = np.where(f != k)[0]
        Wa, Wb, _, ma, mb = cca_fit(A[tr], B[tr])
        out.append((te, (A[te] - ma) @ Wa, (B[te] - mb) @ Wb))
    return out


def cca_oof(A, B, seed):
    return cca_oof_labels(A, B, np.random.default_rng(seed).permutation(len(A)) % FOLDS)


def oof_metrics(folds, c=None):
    """Held-out mean canonical correlation (mean over folds and components) and top-1
    retrieval A->B among all held-out genes of the fold (candidate set fixed).
    c = optional bootstrap gene counts used as query/correlation weights."""
    ccs, hits, tot = [], 0.0, 0.0
    for te, Pa, Pb in folds:
        w = np.ones(len(te)) if c is None else c[te].astype(float)
        if (w > 0).sum() < 3:
            continue
        sw = w.sum()
        da = Pa - (w @ Pa) / sw; db = Pb - (w @ Pb) / sw
        cc = ((w[:, None] * da) * db).sum(0) / np.sqrt(((w[:, None] * da) * da).sum(0) * ((w[:, None] * db) * db).sum(0))
        ccs.append(cc.mean())
        na = Pa / np.linalg.norm(Pa, axis=1, keepdims=True); nb = Pb / np.linalg.norm(Pb, axis=1, keepdims=True)
        hit = (na @ nb.T).argmax(1) == np.arange(len(te))
        hits += w @ hit; tot += sw
    return float(np.mean(ccs)), hits / tot


PCS = {p: {m: pc_scores(XU[m][pidx[p]], K_PC) for m in ["M", "G", "S"]} for p in PANELS}
OOF = {(a, b): {p: [cca_oof(PCS[p][a], PCS[p][b], SEED + r) for r in range(CV_REPEATS)] for p in PANELS}
       for a, b in PAIRS}
cca_obs = {pr: {p: np.mean([oof_metrics(fo) for fo in OOF[pr][p]], axis=0) for p in PANELS} for pr in PAIRS}
cca_insample = {(a, b): {p: float(cca_fit(PCS[p][a], PCS[p][b])[2].mean()) for p in PANELS} for a, b in PAIRS}

cca_null = {pr: np.zeros((N_PERM_CCA, len(PANELS), 2)) for pr in PAIRS}
cca_null_in = {pr: np.zeros((N_PERM_CCA, len(PANELS))) for pr in PAIRS}
for j, p in enumerate(PANELS):
    n = len(pidx[p])
    for k in range(N_PERM_CCA):
        perm = rng.permutation(n)
        for a, b in PAIRS:
            cca_null[(a, b)][k, j] = oof_metrics(cca_oof(PCS[p][a], PCS[p][b][perm], SEED + 1000 + k))
            cca_null_in[(a, b)][k, j] = cca_fit(PCS[p][a], PCS[p][b][perm])[2].mean()
log("cca null done")

# fixed-map bootstrap of held-out genes (CCA maps from the CV fits held fixed)
boot_cca = {pr: np.zeros((B_CCA, len(PANELS), 2)) for pr in PAIRS}
for bi in range(B_CCA):
    cu = np.bincount(rng.integers(0, NU, NU), minlength=NU)
    for j, p in enumerate(PANELS):
        c = cu[pidx[p]]
        for pr in PAIRS:
            boot_cca[pr][bi, j] = np.mean([oof_metrics(fo, c) for fo in OOF[pr][p]], axis=0)
    if bi % 250 == 0:
        log("cca boot", bi)
log("cca fixed-map boot done")

# ------------------------------------------------------------------ grouped jackknife, every step refitted
# Delete one group of genes (about 41 of the 828-gene union) at a time; PCA, CCA, CV and kNN neighbour sets are
# recomputed on the remaining genes (remaining genes keep their fold labels). No duplicated genes are created.
FL = {p: [np.random.default_rng(SEED + r).permutation(len(pidx[p])) % FOLDS for r in range(CV_REPEATS)] for p in PANELS}
JQ = ["cv_cca_cc", "cv_cca_top1", "insample_cca_cc", "knn10"]


def pipeline(keep):
    out = {pr: [] for pr in PAIRS}
    for p in PANELS:
        kp = keep[pidx[p]]
        X = {m: XU[m][pidx[p]][kp] for m in ["M", "G", "S"]}
        Z = {m: pc_scores(X[m], K_PC) for m in X}
        A = {m: knn_masks(cos_dist(X[m]), K_NN) for m in X}
        for a, b in PAIRS:
            cv = np.mean([oof_metrics(cca_oof_labels(Z[a], Z[b], FL[p][r][kp])) for r in range(CV_REPEATS)], axis=0)
            out[(a, b)].append([cv[0], cv[1], cca_fit(Z[a], Z[b])[2].mean(), ((A[a] & A[b]).sum(1) / K_NN).mean()])
    return {pr: np.mean(v, axis=0) for pr, v in out.items()}


full_pipe = pipeline(np.ones(NU, bool))
for pr in PAIRS:   # the jackknife pipeline reproduces the point estimates
    assert np.allclose(full_pipe[pr][:2], np.mean([cca_obs[pr][p] for p in PANELS], axis=0))
    assert np.isclose(full_pipe[pr][2], np.mean([cca_insample[pr][p] for p in PANELS]))
    assert np.isclose(full_pipe[pr][3], np.mean([knn_gene[K_NN][pr][p].mean() for p in PANELS]))
rng4 = np.random.default_rng(SEED + 3)
jack = []
for rep in range(N_JACK_REP):
    grp = rng4.permutation(NU) % N_JACK
    rows_ = [pipeline(grp != g) for g in range(N_JACK)]
    jack.append({pr: np.array([r_[pr] for r_ in rows_]) for pr in PAIRS})
TQ = float(t_dist.ppf(0.975, N_JACK - 1))
log("jackknife done")

# ------------------------------------------------------------------ random gene sets (held-out condition)
rng3 = np.random.default_rng(SEED + 2)
pool = [g for g in sorted(gf_dict) if g.startswith("ENSG") and g not in pos and mt_dict.get(g) == gf_dict[g]
        and g in e2s and e2s[g] in sg_vocab]
RQ = ["rsa", "cv_cca_cc", "cv_cca_top1", "knn10"]
rand = {pr: np.zeros((N_RAND, len(RQ))) for pr in PAIRS}
iu_r = np.triu_indices(RAND_SIZE, 1)
for r in range(N_RAND):
    gs = [pool[i] for i in rng3.choice(len(pool), RAND_SIZE, replace=False)]
    t = np.array([mt_dict[g] for g in gs]); s = np.array([sg_vocab[e2s[g]] for g in gs])
    X = {"M": M_tab[t], "G": G_tab[t], "S": scgpt_layernorm(S_tab[s])}
    D = {m: cos_dist(X[m]) for m in X}; rk = {m: ranks(D[m][iu_r]) for m in X}
    Z = {m: pc_scores(X[m], K_PC) for m in X}; A = {m: knn_masks(D[m], K_NN) for m in X}
    for a, b in PAIRS:
        cc, t1 = oof_metrics(cca_oof(Z[a], Z[b], SEED + 5000 + r))
        rand[(a, b)][r] = (pearson(rk[a], rk[b]), cc, t1, ((A[a] & A[b]).sum(1) / K_NN).mean())
set_idx = rng3.integers(0, N_RAND, (B_SETS, N_RAND))
log("random gene sets done")

# ------------------------------------------------------------------ assemble estimates
lab = {"M": "maxtoki", "G": "geneformer", "S": "scgpt"}
DIFF, RATIO = "diff_mg_minus_ms", "ratio_ms_over_mg"
pm = lambda d: float(np.mean([d[p] for p in PANELS]))
SRC = f"unit = gene, drawn from the {NU}-gene panel union"
M_RSA = f"gene bootstrap, {B_RSA} replicates ({SRC}); weighted Spearman, distances fixed; 95% percentile CI"
M_SENS = f"gene bootstrap, {B_SENS} replicates ({SRC}); weighted Spearman, distances fixed; 95% percentile CI"
M_KNN = f"gene bootstrap, {B_RSA} replicates ({SRC}); neighbour sets fixed; 95% percentile CI"
M_CCA = f"gene bootstrap, {B_CCA} replicates ({SRC}); CV-fitted CCA maps fixed (too narrow); 95% percentile CI"
M_JACK = (f"grouped jackknife (unit = gene; {N_JACK} groups x {N_JACK_REP} splits of the {NU}-gene union, all steps "
          f"refitted); estimate +/- t({N_JACK - 1}) x SE (conservative)")
M_SETS = f"bootstrap over {N_RAND} random {RAND_SIZE}-gene sets (unit = gene set, {B_SETS} resamples); 95% percentile CI"
E = []


def est(name, value, samples, method):
    lo, hi = np.percentile(samples, [2.5, 97.5])
    E.append({"name": name, "value": round(float(value), 4), "ci_low": round(float(lo), 4),
              "ci_high": round(float(hi), 4), "method_of_uncertainty": method})


def add_pairwise(prefix, obs, boots, method, levels=PAIRS, diff=True, ratio=True):
    mg, ms_ = ("M", "G"), ("M", "S")
    for a, b in levels:
        est(f"{prefix}_{lab[a]}_{lab[b]}", obs[(a, b)], boots[(a, b)], method)
    if diff:
        est(f"{prefix}_{DIFF}", obs[mg] - obs[ms_], boots[mg] - boots[ms_], method + "; paired")
    if ratio:
        est(f"{prefix}_{RATIO}", obs[ms_] / obs[mg], boots[ms_] / boots[mg], method + "; paired")


# primary: RSA (panel mean and per panel)
add_pairwise("rsa_mean3", {(a, b): pm(rsa_obs[("cos", a, b)]) for a, b in PAIRS},
             {(a, b): boot_rsa[("cos", a, b)].mean(1) for a, b in PAIRS}, M_RSA)
for j, p in enumerate(PANELS):
    add_pairwise(f"rsa_{p}", {(a, b): rsa_obs[("cos", a, b)][p] for a, b in PAIRS},
                 {(a, b): boot_rsa[("cos", a, b)][:, j] for a, b in PAIRS}, M_RSA)


def partial(rxy, rxz, ryz):
    return (rxy - rxz * ryz) / np.sqrt((1 - rxz ** 2) * (1 - ryz ** 2))


bMG, bMS, bGS = [boot_rsa[s] for s in PRIMARY]
oP = {k: np.array([rsa_obs[s][p] for p in PANELS]) for k, s in zip(["MG", "MS", "GS"], PRIMARY)}
M_PART = M_RSA + "; per panel, then averaged; descriptive"
est("partial_rsa_mean3_maxtoki_scgpt_given_geneformer", partial(oP["MS"], oP["MG"], oP["GS"]).mean(),
    partial(bMS, bMG, bGS).mean(1), M_PART)
est("partial_rsa_mean3_maxtoki_geneformer_given_scgpt", partial(oP["MG"], oP["MS"], oP["GS"]).mean(),
    partial(bMG, bMS, bGS).mean(1), M_PART)

# sensitivity RSA variants (panel mean); no ratios for Euclidean variants (M-G can be near zero)
SENS_LEVELS = {"rawS": [("M", "S")], "rmPC1": [("M", "G"), ("M", "S")], "euc": PAIRS}
for s in SENS:
    lv = SENS_LEVELS.get(s, [("M", "G"), ("M", "S")])
    add_pairwise(f"sens_{s}_rsa_mean3", {(k[0], k[1]): pm(sens_obs[s][k]) for k in SENS[s]},
                 {(k[0], k[1]): boot_sens[s][k].mean(1) for k in SENS[s]}, M_SENS, levels=lv,
                 ratio=not s.startswith("euc"))

# kNN overlap (panel mean)
for kk in KNN_KS:
    ch = float(np.mean([kk / (len(pidx[p]) - 1) for p in PANELS]))
    o = {pr: float(np.mean([knn_gene[kk][pr][p].mean() for p in PANELS])) for pr in PAIRS}
    bk = {pr: boot_knn[kk][pr].mean(1) for pr in PAIRS}
    add_pairwise(f"knn{kk}_mean3", o, bk, M_KNN, levels=PAIRS if kk == K_NN else [])
    est(f"knn{kk}_mean3_above_chance_{RATIO}", (o[("M", "S")] - ch) / (o[("M", "G")] - ch),
        (bk[("M", "S")] - ch) / (bk[("M", "G")] - ch), M_KNN + f"; chance {ch:.4f} subtracted; paired")

# CV-CCA, fixed-map bootstrap (panel mean; per-panel M-G minus M-S)
QN = [(0, "cv_cca_cc"), (1, "cv_cca_top1")]
for q, qn in QN:
    add_pairwise(f"{qn}_mean3", {pr: float(np.mean([cca_obs[pr][p][q] for p in PANELS])) for pr in PAIRS},
                 {pr: boot_cca[pr][:, :, q].mean(1) for pr in PAIRS}, M_CCA)
    for j, p in enumerate(PANELS):
        add_pairwise(f"{qn}_{p}", {pr: cca_obs[pr][p][q] for pr in PAIRS}, {pr: boot_cca[pr][:, j, q] for pr in PAIRS},
                     M_CCA, levels=[], ratio=False)


# grouped jackknife (refit-aware) intervals: CV-CCA, in-sample CCA, kNN-10
def jack_est(name, fun):
    val = fun(full_pipe)
    var = np.mean([(N_JACK - 1) / N_JACK * ((fun(J) - fun(J).mean()) ** 2).sum() for J in jack])
    se = float(np.sqrt(var))
    E.append({"name": name, "value": round(float(val), 4), "ci_low": round(float(val - TQ * se), 4),
              "ci_high": round(float(val + TQ * se), 4), "method_of_uncertainty": M_JACK})


for q, qn in enumerate(JQ):
    if qn == "insample_cca_cc":
        for a, b in PAIRS:
            jack_est(f"jack_{qn}_mean3_{lab[a]}_{lab[b]}", lambda d, a=a, b=b: d[(a, b)][..., q])
    jack_est(f"jack_{qn}_mean3_{DIFF}", lambda d: d[("M", "G")][..., q] - d[("M", "S")][..., q])
    jack_est(f"jack_{qn}_mean3_{RATIO}", lambda d: d[("M", "S")][..., q] / d[("M", "G")][..., q])

# random gene sets
for i, qn in enumerate(RQ):
    add_pairwise(f"random_sets_{qn}", {pr: float(rand[pr][:, i].mean()) for pr in PAIRS},
                 {pr: rand[pr][set_idx, i].mean(1) for pr in PAIRS}, M_SETS, levels=PAIRS if qn == "rsa" else [])
rand_range = {qn: {"ms_over_mg_single_set_2.5_97.5": np.percentile(rand[("M", "S")][:, i] / rand[("M", "G")][:, i], [2.5, 97.5]).tolist(),
                   "mg_minus_ms_single_set_min": float((rand[("M", "G")][:, i] - rand[("M", "S")][:, i]).min())}
              for i, qn in enumerate(RQ)}


def one_factor(mg, ms_, gs):
    am = np.sqrt(mg * ms_ / gs)
    return {"maxtoki": float(am), "geneformer": float(mg / am), "scgpt": float(ms_ / am)}


desc["one_factor_loadings_rsa_panels_mean3"] = one_factor(*[pm(rsa_obs[s]) for s in PRIMARY])
desc["one_factor_loadings_rsa_random_sets"] = one_factor(*[rand[pr][:, 0].mean() for pr in PAIRS])


# ------------------------------------------------------------------ chance levels / permutation p-values
def pval(obs, null):
    return float((1 + np.sum(null >= obs)) / (1 + len(null)))


fold_chance = {p: float(np.mean(1.0 / np.bincount(np.arange(len(pidx[p])) % FOLDS))) for p in PANELS}
nulls = {"cv_cca_top1_analytic_chance_mean3": float(np.mean(list(fold_chance.values()))),
         "cv_cca_top1_analytic_chance_per_panel": fold_chance}
for pr in PAIRS:
    a, b = pr; key = f"{lab[a]}_{lab[b]}"
    s = ("cos", a, b); nm = mantel_null[pr].mean(1)
    nulls[f"rsa_{key}"] = {"null_mean": float(nm.mean()), "null_q95": float(np.percentile(nm, 95)),
                           "p_mean3": pval(pm(rsa_obs[s]), nm),
                           "p_per_panel": {p: pval(rsa_obs[s][p], mantel_null[pr][:, j]) for j, p in enumerate(PANELS)},
                           "null_q95_per_panel": {p: float(np.percentile(mantel_null[pr][:, j], 95)) for j, p in enumerate(PANELS)}}
    kn = knn_null[pr].mean(1)
    nulls[f"knn10_{key}"] = {
        "null_mean": float(kn.mean()), "null_q95": float(np.percentile(kn, 95)),
        "p_mean3": pval(np.mean([knn_gene[K_NN][pr][p].mean() for p in PANELS]), kn),
        "analytic_chance": float(np.mean([K_NN / (len(pidx[p]) - 1) for p in PANELS])),
        "obs_per_panel": {p: float(knn_gene[K_NN][pr][p].mean()) for p in PANELS},
        "null_q95_per_panel": {p: float(np.percentile(knn_null[pr][:, j], 95)) for j, p in enumerate(PANELS)},
        "p_per_panel": {p: pval(knn_gene[K_NN][pr][p].mean(), knn_null[pr][:, j]) for j, p in enumerate(PANELS)}}
    for q, qn in QN:
        cn = cca_null[pr][:, :, q].mean(1)
        nulls[f"{qn}_{key}"] = {
            "null_mean": float(cn.mean()), "null_q95": float(np.percentile(cn, 95)),
            "p_mean3": pval(np.mean([cca_obs[pr][p][q] for p in PANELS]), cn),
            "obs_per_panel": {p: float(cca_obs[pr][p][q]) for p in PANELS},
            "null_q95_per_panel": {p: float(np.percentile(cca_null[pr][:, j, q], 95)) for j, p in enumerate(PANELS)},
            "p_per_panel": {p: pval(cca_obs[pr][p][q], cca_null[pr][:, j, q]) for j, p in enumerate(PANELS)}}
    ci_in = cca_null_in[pr].mean(1)
    nulls[f"insample_cca_cc_{key}"] = {"null_mean": float(ci_in.mean()), "null_q95": float(np.percentile(ci_in, 95)),
                                       "per_panel_obs": cca_insample[pr]}
nulls["n_perm"] = {"mantel": N_PERM, "knn10": N_PERM_KNN, "cv_cca": N_PERM_CCA}

# ------------------------------------------------------------------ verdict rule
by = {e["name"]: e for e in E}


def band_class(e):
    if e["ci_high"] < BAND[0]:
        return "below 0.8"
    if e["ci_low"] >= BAND[0] and e["ci_high"] <= BAND[1]:
        return "within [0.8, 1.25]"
    return "straddles 0.8"


ratio_rule = {n: band_class(e) for n, e in by.items() if RATIO in n}
ms = by["rsa_mean3_maxtoki_scgpt"]
ratio = by[f"rsa_mean3_{RATIO}"]
beyond_chance = (nulls["rsa_maxtoki_scgpt"]["p_mean3"] < 0.05 and ms["ci_low"] > 0 and
                 all(v < 0.05 for v in nulls["rsa_maxtoki_scgpt"]["p_per_panel"].values()))
# direction checks: M-G minus M-S must have CI > 0 on the primary metric (mean and every panel), on every cosine
# variant (raw scGPT, top PC removed, 5-100 PCs) and on the refit-aware CV-CCA, retrieval and kNN-10 intervals
gates = ([f"rsa_mean3_{DIFF}"] + [f"rsa_{p}_{DIFF}" for p in PANELS] +
         [f"sens_{s}_rsa_mean3_{DIFF}" for s in ["rawS", "rmPC1"] + [f"cosPC{k}" for k in PCA_DIMS]] +
         [f"jack_{q}_mean3_{DIFF}" for q in ["cv_cca_cc", "cv_cca_top1", "knn10"]])
direction = {g: by[g]["ci_low"] > 0 for g in gates}
if not beyond_chance:
    verdict = "not aligned with scGPT beyond chance"
elif all(direction.values()) and ratio["ci_high"] < BAND[0]:
    verdict = "aligned with scGPT but clearly less than with Geneformer"
elif ratio["ci_low"] >= BAND[0] and ratio["ci_high"] <= BAND[1]:
    verdict = "aligned with scGPT about as well as with Geneformer"
else:
    verdict = "inconclusive"

out = {"verdict": verdict, "estimates": E, "direction_checks": direction, "ratio_rule_by_metric": ratio_rule,
       "null_and_chance": rnd(nulls), "descriptive": rnd(desc), "random_sets_single_set_spread": rnd(rand_range),
       "per_panel_rsa_sensitivity": rnd({s: {k: d[k] for k in d} for s, d in sens_obs.items()}),
       "per_panel_knn": rnd({kk: {f"{lab[a]}_{lab[b]}": {p: knn_gene[kk][(a, b)][p].mean() for p in PANELS}
                                  for a, b in PAIRS} for kk in KNN_KS}),
       "per_panel_cv_cca_cc_top1": rnd({f"{lab[a]}_{lab[b]}": {p: list(cca_obs[(a, b)][p]) for p in PANELS}
                                        for a, b in PAIRS}),
       "settings": {"seed": SEED, "B_rsa": B_RSA, "B_sens": B_SENS, "n_perm_mantel": N_PERM, "B_cca": B_CCA,
                    "n_perm_cca": N_PERM_CCA, "n_perm_knn": N_PERM_KNN, "cv_repeats": CV_REPEATS, "k_pc": K_PC,
                    "n_cc": N_CC, "folds": FOLDS, "k_nn": K_NN, "pca_dims": PCA_DIMS, "knn_ks": KNN_KS,
                    "n_jack_groups": N_JACK, "n_jack_splits": N_JACK_REP, "n_random_sets": N_RAND,
                    "random_set_size": RAND_SIZE, "random_pool": len(pool),
                    "n_genes": {p: int(len(pidx[p])) for p in PANELS}, "n_union": NU}}
print(json.dumps(out, indent=1))
log("done")

#!/usr/bin/env python3
"""
MaxToki-217M gene-embedding alignment with scGPT (whole-human) and Geneformer V2-316M.

Follows contract/SPEC.md Phase 4 (H24 cross-model alignment), applied to the input gene-token
embedding tables restricted to the three gene panels in data/panels/:
  * per panel and per model: centre the genes, PCA to K=20 components (whitened scores);
  * whitened CCA between the two models' PCA scores -> mean of all K canonical correlations;
  * top-1 gene retrieval in the shared canonical space (cosine; mean of both directions);
  * pairwise-distance Spearman (RSA) between the models' centred-cosine distance matrices
    computed on the full-dimensional embeddings (norm-free "shape" agreement).
Chance level: gene-permutation null (the gene correspondence between the two tables is shuffled).
Uncertainty: resampling unit = gene. Delete-d jackknife with d = n/2 (random half-samples of
the union of the three panels drawn without replacement; each panel keeps its genes in the half);
95% CI = full-sample estimate + 2.5/97.5% quantiles of the centred half-sample estimates
(for m = n/2 without replacement the half-sample variance matches the full-sample variance).
Half-sampling is used instead of the ordinary bootstrap because duplicated genes in a bootstrap
sample inflate in-sample CCA/retrieval. Differences between pairs are paired within half-samples.
scGPT rows are passed through the checkpoint's enc_norm LayerNorm (what scGPT's gene encoder
outputs); the raw rows are a sensitivity analysis. Run from the package root; prints JSON.
"""
import json, os, time
import numpy as np, pandas as pd
from scipy.linalg import eigh, svd
from scipy.stats import rankdata, chi2

D = 'data'
K = 20
N_PERM = int(os.environ.get('N_PERM', 500))
N_HALF = int(os.environ.get('N_HALF', 300))
N_PERM_SENS = int(os.environ.get('N_PERM_SENS', 100))
SEED = 20261001
PANELS = ['lung', 'immune', 'external_lung']
MODELS = ['MaxToki', 'Geneformer', 'scGPT']
PAIRS = [('MaxToki', 'scGPT'), ('MaxToki', 'Geneformer'), ('Geneformer', 'scGPT')]
MS, MG, GS = PAIRS
PK = {p: f'{p[0]}-{p[1]}' for p in PAIRS}
METRICS = ['cca_mean_r', 'rsa_cos_spearman', 'top1_retrieval']
t_start = time.time()

# ------------------------------------------------------------------ data and gene mapping
mt_tok = json.load(open(f'{D}/maxtoki_217m/token_dictionary.json'))
gf_tok = json.load(open(f'{D}/geneformer_v2_316m/token_dictionary.json'))
sc_voc = json.load(open(f'{D}/scgpt_whole_human/vocab.json'))
es = pd.read_csv(f'{D}/gene_ids/ensembl_symbol.csv')
e2s = dict(zip(es.ensembl_id, es.symbol))
panels = {p: pd.read_csv(f'{D}/panels/{p}.csv').ensembl_id.astype(str).tolist() for p in PANELS}
union = sorted(set().union(*panels.values()))
pos = {g: i for i, g in enumerate(union)}
pidx = {p: np.array([pos[g] for g in panels[p]]) for p in PANELS}
for g in union:  # every panel gene maps in all three vocabularies; MaxToki and Geneformer ids identical
    assert g in mt_tok and g in gf_tok and mt_tok[g] == gf_tok[g], g
    assert e2s.get(g) in sc_voc, g          # scGPT is keyed by gene symbol (Ensembl -> symbol table)

def take(path, ids):
    return np.asarray(np.load(path, mmap_mode='r')[np.asarray(ids)], dtype=np.float64)

E_mt = take(f'{D}/maxtoki_217m/embed_tokens.npy', [mt_tok[g] for g in union])
E_gf = take(f'{D}/geneformer_v2_316m/word_embeddings.npy', [gf_tok[g] for g in union])
E_sc_raw = take(f'{D}/scgpt_whole_human/encoder_embedding_weight.npy', [sc_voc[e2s[g]] for g in union])
ln = np.load(f'{D}/scgpt_whole_human/encoder_enc_norm.npz')

def layernorm(X):  # scGPT GeneEncoder output = enc_norm(embedding(token))
    m = X.mean(1, keepdims=True); v = X.var(1, keepdims=True)
    return (X - m) / np.sqrt(v + float(ln['eps'])) * ln['weight'].astype(np.float64) + ln['bias'].astype(np.float64)

E_main = {'MaxToki': E_mt, 'Geneformer': E_gf, 'scGPT': layernorm(E_sc_raw)}
def grams(E): return {m: X @ X.T for m, X in E.items()}
G_main = grams(E_main)
nU = len(union)

# ------------------------------------------------------------------ metric primitives
def centred_gram(Gu, r):
    Gs = Gu[np.ix_(r, r)]; rm = Gs.mean(1)
    return Gs - rm[:, None] - rm[None, :] + rm.mean()

def top_u(Gc, k):  # whitened PCA scores (left singular vectors of the centred data)
    n = Gc.shape[0]
    return eigh(Gc, subset_by_index=[n - k, n - 1])[1][:, ::-1]

def cos_z(Gc, iu):  # z-scored ranks of centred-cosine distances, upper triangle
    dg = np.sqrt(np.diag(Gc))
    r = rankdata(1.0 - (Gc / dg[:, None] / dg[None, :])[iu])
    return (r - r.mean()) / r.std()

def cca_r(Ua, Ub):
    return svd(Ua.T @ Ub, compute_uv=False)

def retrieval(Ua, Ub):
    A, s, Bt = svd(Ua.T @ Ub)
    Ca = Ua @ A; Cb = Ub @ Bt.T
    Ca /= np.linalg.norm(Ca, axis=1, keepdims=True); Cb /= np.linalg.norm(Cb, axis=1, keepdims=True)
    S = Ca @ Cb.T; ar = np.arange(len(S))
    return 0.5 * (np.mean(S.argmax(1) == ar) + np.mean(S.argmax(0) == ar))

def panel_metrics(Gd, r, k=K, pairs=PAIRS, with_rsa=True):
    n = len(r); iu = np.triu_indices(n, 1)
    models = sorted({m for pr in pairs for m in pr})
    Gc = {m: centred_gram(Gd[m], r) for m in models}
    U = {m: top_u(Gc[m], k) for m in models}
    Z = {m: cos_z(Gc[m], iu) for m in models} if with_rsa else {}
    out = {pr: {'cca_mean_r': float(cca_r(U[pr[0]], U[pr[1]]).mean()),
                'rsa_cos_spearman': float(np.mean(Z[pr[0]] * Z[pr[1]])) if with_rsa else np.nan,
                'top1_retrieval': float(retrieval(U[pr[0]], U[pr[1]]))} for pr in pairs}
    return out, U, Z, iu

def perm_null(U, Z, iu, n, perms, pairs=PAIRS, with_rsa=True):
    res = {pr: {m: np.full(len(perms), np.nan) for m in METRICS} for pr in pairs}
    Zflat = {}
    for m, z in Z.items():
        F = np.zeros((n, n)); F[iu] = z; Zflat[m] = (F + F.T).ravel()
    for i, p in enumerate(perms):
        fidx = p[iu[0]] * n + p[iu[1]] if with_rsa else None
        for a, b in pairs:
            Ubp = U[b][p]   # row i of model b now belongs to gene p[i]: random gene correspondence
            res[(a, b)]['cca_mean_r'][i] = cca_r(U[a], Ubp).mean()
            res[(a, b)]['top1_retrieval'][i] = retrieval(U[a], Ubp)
            if with_rsa:
                res[(a, b)]['rsa_cos_spearman'][i] = np.mean(Z[a] * Zflat[b][fidx])
    return res

def pval(o, nl): return float((1 + np.sum(nl >= o)) / (len(nl) + 1))
def mean_panels(d): return float(np.mean([d[p] for p in PANELS]))

# ------------------------------------------------------------------ observed values + gene-permutation null
rng_perm = np.random.default_rng(SEED)
obs, null = {}, {}
for p in PANELS:
    r = pidx[p]; n = len(r)
    o, U, Z, iu = panel_metrics(G_main, r)
    obs[p] = o
    null[p] = perm_null(U, Z, iu, n, [rng_perm.permutation(n) for _ in range(N_PERM)])
summary = {}
for pr in PAIRS:
    for m in METRICS:
        per = {p: obs[p][pr][m] for p in PANELS}
        nl = np.mean([null[p][pr][m] for p in PANELS], axis=0)   # null of the 3-panel mean
        pp = {p: pval(per[p], null[p][pr][m]) for p in PANELS}
        summary[(pr, m)] = dict(
            per_panel=per, mean3=mean_panels(per),
            null_mean=float(nl.mean()), null_sd=float(nl.std()), null_q025=float(np.quantile(nl, .025)),
            null_q975=float(np.quantile(nl, .975)), z_vs_null=float((mean_panels(per) - nl.mean()) / nl.std()),
            excess_over_chance=float(mean_panels(per) - nl.mean()),
            p_mean3=pval(mean_panels(per), nl), p_panel=pp,
            fisher_p_panels=float(chi2.sf(-2 * np.sum(np.log(list(pp.values()))), 2 * len(PANELS))),
            null_mean_panel={p: float(null[p][pr][m].mean()) for p in PANELS},
            null_q95_panel={p: float(np.quantile(null[p][pr][m], .95)) for p in PANELS})
t_obs = time.time()

# ------------------------------------------------------------------ gene half-sampling (delete-d jackknife, d = n/2)
rng_half = np.random.default_rng(SEED + 1)
half = {(pr, m): {p: np.empty(N_HALF) for p in PANELS} for pr in PAIRS for m in METRICS}
for bi in range(N_HALF):
    sel = np.zeros(nU, bool); sel[rng_half.choice(nU, nU // 2, replace=False)] = True
    for p in PANELS:
        o = panel_metrics(G_main, pidx[p][sel[pidx[p]]])[0]
        for pr in PAIRS:
            for m in METRICS:
                half[(pr, m)][p][bi] = o[pr][m]
t_half = time.time()

def jk_ci(est, th):
    dev = th - th.mean()
    return [float(est + np.quantile(dev, .025)), float(est + np.quantile(dev, .975))]

res_pairs, res_diff = {}, {}
for m in METRICS:
    for pr in PAIRS:
        s = summary[(pr, m)]
        hp = np.mean([half[(pr, m)][p] for p in PANELS], axis=0)
        res_pairs[f'{PK[pr]}|{m}'] = dict(s, ci_mean3=jk_ci(s['mean3'], hp), se_mean3=float(hp.std()),
                                         ci_panel={p: jk_ci(s['per_panel'][p], half[(pr, m)][p]) for p in PANELS})
    for lab, (hi, lo) in {'MaxToki-Geneformer minus MaxToki-scGPT': (MG, MS),
                          'Geneformer-scGPT minus MaxToki-scGPT': (GS, MS)}.items():
        dpan = {p: obs[p][hi][m] - obs[p][lo][m] for p in PANELS}
        hpan = {p: half[(hi, m)][p] - half[(lo, m)][p] for p in PANELS}
        hpool = np.mean([hpan[p] for p in PANELS], axis=0)
        res_diff[f'{lab}|{m}'] = dict(mean3=mean_panels(dpan), ci_mean3=jk_ci(mean_panels(dpan), hpool),
                                      se_mean3=float(hpool.std()), per_panel=dpan,
                                      ci_panel={p: jk_ci(dpan[p], hpan[p]) for p in PANELS})
    # ratio of above-chance alignment, MaxToki-scGPT / MaxToki-Geneformer (chance = permutation null mean)
    c0 = summary[(MS, m)]['null_mean']; c1 = summary[(MG, m)]['null_mean']
    rat = (summary[(MS, m)]['mean3'] - c0) / (summary[(MG, m)]['mean3'] - c1)
    hr = (np.mean([half[(MS, m)][p] for p in PANELS], 0) - c0) / (np.mean([half[(MG, m)][p] for p in PANELS], 0) - c1)
    res_diff[f'ratio of above-chance alignment MaxToki-scGPT / MaxToki-Geneformer|{m}'] = dict(mean3=float(rat), ci_mean3=jk_ci(rat, hr))

# ------------------------------------------------------------------ sensitivity analyses (point estimates + permutation p)
rng_s = np.random.default_rng(SEED + 2)
def sens_block(Gd, k=K, panel_sets=None, with_rsa=True):
    panel_sets = panel_sets if panel_sets is not None else {p: pidx[p] for p in PANELS}
    mets = METRICS if with_rsa else ['cca_mean_r', 'top1_retrieval']
    vals = {(pr, m): {} for pr in [MS, MG] for m in mets}; nls = {(pr, m): [] for pr in [MS, MG] for m in mets}
    for name, r in panel_sets.items():
        o, U, Z, iu = panel_metrics(Gd, r, k=k, pairs=[MS, MG], with_rsa=with_rsa)
        nl = perm_null(U, Z, iu, len(r), [rng_s.permutation(len(r)) for _ in range(N_PERM_SENS)], pairs=[MS, MG], with_rsa=with_rsa)
        for (pr, m) in vals:
            vals[(pr, m)][name] = o[pr][m]; nls[(pr, m)].append(nl[pr][m])
    res = {}
    for (pr, m), d in vals.items():
        v = float(np.mean(list(d.values()))); nl = np.mean(nls[(pr, m)], axis=0)
        res[f'{PK[pr]}|{m}'] = dict(value=v, per_set=d, null_mean=float(nl.mean()), p_perm=pval(v, nl))
    for m in mets:
        res[f'difference MG-MS|{m}'] = res[f'{PK[MG]}|{m}']['value'] - res[f'{PK[MS]}|{m}']['value']
    return res

unit = lambda X: X / np.linalg.norm(X, axis=1, keepdims=True)
sens = {'pca_k10': sens_block(G_main, k=10, with_rsa=False),
        'scgpt_without_layernorm': sens_block(grams({'MaxToki': E_mt, 'Geneformer': E_gf, 'scGPT': E_sc_raw})),
        'rows_unit_normalised_before_centring': sens_block(grams({m: unit(X) for m, X in E_main.items()})),
        'union_of_panels_828_genes': sens_block(G_main, panel_sets={'union': np.arange(nU)})}

def euc_rsa(r, a, b):  # Euclidean-distance RSA on full centred embeddings (norm-sensitive)
    iu = np.triu_indices(len(r), 1)
    def dz(m):
        Gc = centred_gram(G_main[m], r); dg = np.diag(Gc)
        rr = rankdata(np.sqrt(np.maximum(dg[:, None] + dg[None, :] - 2 * Gc, 0))[iu]); return (rr - rr.mean()) / rr.std()
    return float(np.mean(dz(a) * dz(b)))
sens['rsa_euclidean_full_dim'] = {PK[pr]: float(np.mean([euc_rsa(pidx[p], *pr) for p in PANELS])) for pr in PAIRS}

def cv_cca(r, a, b, k=K, folds=5, reps=3, seed=SEED + 3):  # fit PCA+CCA on 80% of genes, evaluate on held-out 20%
    rng = np.random.default_rng(seed); cors, hits, tot, chance = [], 0.0, 0, []
    for _ in range(reps):
        for f in np.array_split(rng.permutation(len(r)), folds):
            te = r[f]; tr = r[np.setdiff1d(np.arange(len(r)), f)]
            def proj(X):
                mu = X[tr].mean(0); Xc = X[tr] - mu
                w, V = eigh(Xc @ Xc.T, subset_by_index=[len(tr) - k, len(tr) - 1]); V = V[:, ::-1]; w = w[::-1]
                return V, ((X[te] - mu) @ Xc.T @ V) / w
            Atr, Ate = proj(E_main[a]); Btr, Bte = proj(E_main[b])
            A, s, Bt = svd(Atr.T @ Btr); Ca = Ate @ A; Cb = Bte @ Bt.T
            cors.append([np.corrcoef(Ca[:, j], Cb[:, j])[0, 1] for j in range(k)])
            Can = Ca / np.linalg.norm(Ca, axis=1, keepdims=True); Cbn = Cb / np.linalg.norm(Cb, axis=1, keepdims=True)
            S = Can @ Cbn.T; ar = np.arange(len(te))
            hits += 0.5 * (np.sum(S.argmax(1) == ar) + np.sum(S.argmax(0) == ar)); tot += len(te); chance.append(1 / len(te))
    return float(np.mean(cors)), float(hits / tot), float(np.mean(chance))
cv = {PK[pr]: {p: cv_cca(pidx[p], *pr) for p in PANELS} for pr in PAIRS}
sens['cross_validated_cca'] = {k: dict(cv_mean_canonical_r=float(np.mean([x[0] for x in v.values()])),
                                       cv_top1=float(np.mean([x[1] for x in v.values()])),
                                       chance_top1=float(np.mean([x[2] for x in v.values()])), per_panel=v) for k, v in cv.items()}
sens['pca_k5'] = sens_block(G_main, k=5, with_rsa=False)

# descriptive diagnostics (deterministic)
diag = {'pca_variance_explained_K': {}, 'canonical_r_by_component_mean3': {}}
for m in MODELS:
    ve = {}
    for p in PANELS:
        ev = np.linalg.eigvalsh(centred_gram(G_main[m], pidx[p]))[::-1]
        ve[p] = float(ev[:K].sum() / ev.sum())
    diag['pca_variance_explained_K'][m] = ve
for pr in PAIRS:
    diag['canonical_r_by_component_mean3'][PK[pr]] = np.mean(
        [cca_r(*[top_u(centred_gram(G_main[m], pidx[p]), K) for m in pr]) for p in PANELS], axis=0).round(3).tolist()
t_sens = time.time()

# ------------------------------------------------------------------ estimates
est = []
def add(name, value, lo, hi, how):
    r4 = lambda x: None if x is None else round(float(x), 4)
    est.append(dict(name=name, value=r4(value), ci_low=r4(lo), ci_high=r4(hi), method_of_uncertainty=how))
JK = (f'95% CI by gene resampling: delete-d jackknife with d=n/2 ({N_HALF} random half-samples of the 828-gene union '
      f'without replacement; full-sample estimate + 2.5/97.5% quantiles of centred half-sample estimates); mean over 3 panels')
for m in METRICS:
    for pr in PAIRS:
        rp = res_pairs[f'{PK[pr]}|{m}']
        add(f'{m}, {PK[pr]} (mean over 3 panels)', rp['mean3'], *rp['ci_mean3'], JK)
    rp = res_pairs[f'{PK[MS]}|{m}']
    add(f'{m}, chance level (gene-permutation null mean, MaxToki-scGPT, mean over 3 panels)', rp['null_mean'], rp['null_q025'], rp['null_q975'],
        f'central 95% range of the gene-permutation null ({N_PERM} permutations of the gene correspondence)')
    add(f'{m}, permutation p-value MaxToki-scGPT above chance (mean over 3 panels)', rp['p_mean3'], None, None,
        f'one-sided gene-permutation test, {N_PERM} permutations, p=(1+#null>=obs)/(N+1); z vs null = {rp["z_vs_null"]:.1f}')
    rd = res_diff[f'MaxToki-Geneformer minus MaxToki-scGPT|{m}']
    add(f'{m}, difference MaxToki-Geneformer minus MaxToki-scGPT (mean over 3 panels)', rd['mean3'], *rd['ci_mean3'], JK + '; paired')
    rr = res_diff[f'ratio of above-chance alignment MaxToki-scGPT / MaxToki-Geneformer|{m}']
    add(f'{m}, ratio of above-chance alignment MaxToki-scGPT / MaxToki-Geneformer', rr['mean3'], *rr['ci_mean3'], JK + '; paired; chance = permutation-null mean')
    rd2 = res_diff[f'Geneformer-scGPT minus MaxToki-scGPT|{m}']
    add(f'{m}, difference Geneformer-scGPT minus MaxToki-scGPT (mean over 3 panels)', rd2['mean3'], *rd2['ci_mean3'], JK + '; paired')
for p in PANELS:
    for pr in [MS, MG]:
        rp = res_pairs[f'{PK[pr]}|cca_mean_r']
        add(f'cca_mean_r, {PK[pr]}, panel {p}', rp['per_panel'][p], *rp['ci_panel'][p], 'delete-d (d=n/2) gene jackknife 95% CI')
    rd = res_diff['MaxToki-Geneformer minus MaxToki-scGPT|cca_mean_r']
    add(f'cca_mean_r, difference MaxToki-Geneformer minus MaxToki-scGPT, panel {p}', rd['per_panel'][p], *rd['ci_panel'][p], 'delete-d (d=n/2) gene jackknife 95% CI, paired')
    rd = res_diff['MaxToki-Geneformer minus MaxToki-scGPT|rsa_cos_spearman']
    add(f'rsa_cos_spearman, difference MaxToki-Geneformer minus MaxToki-scGPT, panel {p}', rd['per_panel'][p], *rd['ci_panel'][p], 'delete-d (d=n/2) gene jackknife 95% CI, paired')

# ------------------------------------------------------------------ pre-specified decision rule
ms = res_pairs[f'{PK[MS]}|cca_mean_r']
beyond_chance = ms['p_mean3'] < 0.05 and all(v < 0.05 for v in ms['p_panel'].values())
d1 = res_diff['MaxToki-Geneformer minus MaxToki-scGPT|cca_mean_r']
d2 = [res_diff[f'MaxToki-Geneformer minus MaxToki-scGPT|{m}'] for m in ['rsa_cos_spearman', 'top1_retrieval']]
if not beyond_chance:
    verdict = 'not aligned with scGPT beyond chance'
elif d1['ci_mean3'][0] > 0 and all(v > 0 for v in d1['per_panel'].values()) and any(x['ci_mean3'][0] > 0 for x in d2):
    verdict = 'aligned with scGPT but clearly less than with Geneformer'
elif -0.05 < d1['ci_mean3'][0] <= 0 <= d1['ci_mean3'][1] < 0.05 and not any(x['ci_mean3'][0] > 0 for x in d2):
    verdict = 'aligned with scGPT about as well as with Geneformer'
else:
    verdict = 'inconclusive'

def clean(o):
    if isinstance(o, dict): return {str(k): clean(v) for k, v in o.items()}
    if isinstance(o, (list, tuple)): return [clean(v) for v in o]
    if isinstance(o, (np.floating, float)): return round(float(o), 5)
    if isinstance(o, np.integer): return int(o)
    return o
print(json.dumps(clean(dict(
    verdict=verdict, estimates=est,
    n_genes=dict({p: len(pidx[p]) for p in PANELS}, union=nU),
    pairs=res_pairs, differences=res_diff, sensitivity=sens, diagnostics=diag,
    settings=dict(K=K, N_PERM=N_PERM, N_HALF=N_HALF, N_PERM_SENS=N_PERM_SENS, SEED=SEED, scgpt_layernorm=True),
    runtime_s=dict(observed_and_perm=t_obs - t_start, half_sampling=t_half - t_obs, sensitivity=t_sens - t_half,
                   total=time.time() - t_start))), indent=1))

#!/usr/bin/env python3
"""
MaxToki-217M gene-embedding alignment with scGPT (whole-human) and Geneformer V2-316M.

Input-layer version of contract/SPEC.md Phase 4 (H24 cross-model alignment), run on the three gene
panels in data/panels/. For every panel and model pair (MaxToki-scGPT, MaxToki-Geneformer; and
Geneformer-scGPT as a reference):
  * genes are centred and reduced by PCA (top-K eigenvectors of the centred gene Gram matrix =
    whitened PCA scores); K = 20 (SPEC default), 10 (SPEC sensitivity value) and 5;
  * in-sample whitened CCA between the two models' PCA scores -> mean of the K canonical correlations
    (the SPEC H24 statistic) and top-1 gene retrieval in the canonical space (cosine, both directions);
  * cross-validated CCA: PCA + CCA fitted on 80% of the panel's genes, canonical correlations and top-1
    retrieval evaluated on the held-out 20% (5 folds x 3 repeats). Its chance level is ~0 at any n,
    whereas in-sample CCA's chance level and between-pair gaps depend on n/K;
  * distance agreement (RSA): Spearman correlation between the two models' gene-gene distances, for five
    representation/distance choices: centred cosine and Euclidean on the full-dimensional centred
    embeddings; cosine, Euclidean and whitened Euclidean on the 20 PCA scores (SPEC Phase 0 representation).
Chance: gene-permutation null (gene correspondence between the two tables shuffled), per panel.
Uncertainty, resampling unit = gene: delete-d jackknife (subsampling without replacement) of the 828-gene
union; each panel keeps its genes that fall in the subsample. Primary: subsamples of 3/4 of the genes
(d = n/4); deviations from the subsample mean are rescaled by sqrt((n-d)/d) = sqrt(3) and the 95% CI is
[est - q97.5, est - q2.5] of the rescaled deviations. Calibration check: half-samples (d = n/2, scale 1).
Differences and ratios between pairs are paired within subsamples. Ratios of above-chance alignment use
chance levels evaluated at the matching number of genes.
scGPT rows are passed through the checkpoint's enc_norm LayerNorm (the output of scGPT's gene encoder).
Decision rule (fixed after the point estimates had been seen; the verdict is exploratory): see 'decision'.
Run from the package root; prints JSON (about 4-5 minutes on an idle 10-core laptop). Threads are used
only to run the three panels concurrently.
"""
import hashlib, json, os, time
from concurrent.futures import ThreadPoolExecutor
import numpy as np, pandas as pd
from scipy.linalg import eigh, svd
from scipy.stats import rankdata, spearmanr

D = 'data'
K = 20
KS = (20, 10, 5)
N_PERM = int(os.environ.get('N_PERM', 500))             # in-sample permutation null, per panel
N_PERM_CV = int(os.environ.get('N_PERM_CV', 100))       # cross-validated permutation null, per panel
N_SUB = int(os.environ.get('N_SUB', 200))               # 3/4-subsamples (primary CIs)
N_HALF = int(os.environ.get('N_HALF', 40))              # half-samples (calibration check)
N_CHANCE_SUB = int(os.environ.get('N_CHANCE_SUB', 100)) # permutations giving in-sample chance levels at the subsample size
N_PERM_SENS = int(os.environ.get('N_PERM_SENS', 100))   # permutations for the sensitivity analyses
N_BOOT_DEMO = int(os.environ.get('N_BOOT_DEMO', 50))    # ordinary gene bootstrap, only to show duplicate-gene inflation
CV_FOLDS, CV_REPS = 5, 3
SUB_FRAC = 0.75
MARGIN, MARGINS = 0.8, (0.7, 0.8, 0.9)
SEED = 20261001
PANELS = ['lung', 'immune', 'external_lung']
MODELS = ['MaxToki', 'Geneformer', 'scGPT']
PAIRS = [('MaxToki', 'scGPT'), ('MaxToki', 'Geneformer'), ('Geneformer', 'scGPT')]
MS, MG, GS = PAIRS
PK = {p: f'{p[0]}-{p[1]}' for p in PAIRS}
RSA = ['rsa_cos_full', 'rsa_euc_full', 'rsa_cos_pca20', 'rsa_euc_pca20', 'rsa_euc_pca20_whitened']
INS = [f'cca_mean_r_K{k}' for k in KS] + [f'top1_K{k}' for k in KS]
CVM = [f'cv_cca_mean_r_K{k}' for k in KS] + [f'cv_top1_K{k}' for k in KS]
CVCH = [f'cv_top1_chance_K{k}' for k in KS]
METRICS = INS + CVM + RSA
DIFF = 'MaxToki-Geneformer minus MaxToki-scGPT'
POOL = ThreadPoolExecutor(3)
t0 = time.time()

# ------------------------------------------------------------------ data, checksums, gene mapping
checks = {}
for line in open(f'{D}/MANIFEST.sha256'):
    h, f = line.split(maxsplit=1); f = f.strip(); hh = hashlib.sha256()
    with open(f'{D}/{f}', 'rb') as fh:
        for chunk in iter(lambda: fh.read(1 << 24), b''):
            hh.update(chunk)
    checks[f] = hh.hexdigest() == h
mt_tok = json.load(open(f'{D}/maxtoki_217m/token_dictionary.json'))
