# ------------------------------------------------------------------ metric primitives
def centred_gram(Gu, r):
    Gs = Gu[np.ix_(r, r)]; rm = Gs.mean(1)
    return Gs - rm[:, None] - rm[None, :] + rm.mean()

def top_eig(Gc, k):   # top-k eigenpairs, descending; eigenvectors = whitened PCA scores
    n = Gc.shape[0]; w, V = eigh(Gc, subset_by_index=[n - k, n - 1])
    return w[::-1], V[:, ::-1]

def d_cos(Gm, iu):
    dg = np.sqrt(np.diag(Gm)); return (1.0 - Gm / dg[:, None] / dg[None, :])[iu]

def d_euc(Gm, iu):
    dg = np.diag(Gm); return np.sqrt(np.maximum(dg[:, None] + dg[None, :] - 2.0 * Gm, 0.0))[iu]

def zrank(d):
    r = rankdata(d); return (r - r.mean()) / r.std()

def cca_r(Ua, Ub):
    return svd(Ua.T @ Ub, compute_uv=False)

def top1(Ca, Cb):
    Ca = Ca / np.linalg.norm(Ca, axis=1, keepdims=True); Cb = Cb / np.linalg.norm(Cb, axis=1, keepdims=True)
    S = Ca @ Cb.T; ar = np.arange(len(S))
    return 0.5 * (np.mean(S.argmax(1) == ar) + np.mean(S.argmax(0) == ar))

def retrieval(Ua, Ub):
    A, s, Bt = svd(Ua.T @ Ub)
    return top1(Ua @ A, Ub @ Bt.T)

def panel_fit(Gd, r, models=MODELS, rsa=RSA):
    n = len(r); iu = np.triu_indices(n, 1)
    Gc = {m: centred_gram(Gd[m], r) for m in models}
    EW = {m: top_eig(Gc[m], K) for m in models}
    Z = {}
    for m in models:
        w, V = EW[m]
        for v in rsa:
            if v == 'rsa_cos_full': d = d_cos(Gc[m], iu)
            elif v == 'rsa_euc_full': d = d_euc(Gc[m], iu)
            elif v == 'rsa_cos_pca20': d = d_cos((V * w) @ V.T, iu)
            elif v == 'rsa_euc_pca20': d = d_euc((V * w) @ V.T, iu)
            elif v == 'rsa_euc_pca20_whitened': d = d_euc(V @ V.T, iu)
            Z[(m, v)] = zrank(d)
    return dict(n=n, iu=iu, V={m: EW[m][1] for m in models}, w={m: EW[m][0] for m in models},
                tr={m: float(np.trace(Gc[m])) for m in models}, Z=Z, rsa=list(rsa))

def insample(fit, pairs, ks=KS):
    out = {}
    for a, b in pairs:
        o = {}
        for k in ks:
            Ua, Ub = fit['V'][a][:, :k], fit['V'][b][:, :k]
            o[f'cca_mean_r_K{k}'] = float(cca_r(Ua, Ub).mean())
            o[f'top1_K{k}'] = float(retrieval(Ua, Ub))
        for v in fit['rsa']:
            o[v] = float(np.mean(fit['Z'][(a, v)] * fit['Z'][(b, v)]))
        out[(a, b)] = o
    return out

def perm_null_insample(fit, perms, pairs, ks=KS):
    n, iu = fit['n'], fit['iu']
    names = [f'cca_mean_r_K{k}' for k in ks] + [f'top1_K{k}' for k in ks] + fit['rsa']
    res = {pr: {m: np.empty(len(perms)) for m in names} for pr in pairs}
    Zsq = {}
    for key, z in fit['Z'].items():
        F = np.zeros((n, n)); F[iu] = z; Zsq[key] = (F + F.T).ravel()
    for i, p in enumerate(perms):
        fidx = p[iu[0]] * n + p[iu[1]]
        for a, b in pairs:   # row j of model b now belongs to gene p[j]: random gene correspondence
            for k in ks:
                Ua, Ubp = fit['V'][a][:, :k], fit['V'][b][p, :k]
                res[(a, b)][f'cca_mean_r_K{k}'][i] = cca_r(Ua, Ubp).mean()
                res[(a, b)][f'top1_K{k}'][i] = retrieval(Ua, Ubp)
            for v in fit['rsa']:
                res[(a, b)][v][i] = np.mean(fit['Z'][(a, v)] * Zsq[(b, v)][fidx])
    return res

def cv_folds(n, seed):
    rng = np.random.default_rng(seed); out = []
    for _ in range(CV_REPS):
        for f in np.array_split(rng.permutation(n), CV_FOLDS):
            mask = np.ones(n, bool); mask[f] = False; out.append((np.where(mask)[0], f))
    return out

def cv_proj(Gu, tr, te):   # PCA fitted on the training genes; whitened scores of training and held-out genes
    Gtt = Gu[np.ix_(tr, tr)]; Get = Gu[np.ix_(te, tr)]
    cm = Gtt.mean(0); gm = cm.mean()
    w, V = top_eig(Gtt - cm[:, None] - cm[None, :] + gm, K)
    Gx = Get - Get.mean(1, keepdims=True) - cm[None, :] + gm
    return V, (Gx @ V) / w

def cv_eval(P, pairs, ks=KS, by_component=False):   # CCA fitted on training genes, evaluated on held-out genes
    out = {}
    for a, b in pairs:
        o = {}
        for k in ks:
            cors, hits, tot = [], 0.0, 0
            for Pf in P:
                Atr, Ate = Pf[a][0][:, :k], Pf[a][1][:, :k]; Btr, Bte = Pf[b][0][:, :k], Pf[b][1][:, :k]
                A, s, Bt = svd(Atr.T @ Btr); Ca = Ate @ A; Cb = Bte @ Bt.T
                Ca0 = Ca - Ca.mean(0); Cb0 = Cb - Cb.mean(0)
                cors.append((Ca0 * Cb0).sum(0) / np.sqrt((Ca0 ** 2).sum(0) * (Cb0 ** 2).sum(0)))
                hits += top1(Ca, Cb) * len(Ca); tot += len(Ca)
            o[f'cv_cca_mean_r_K{k}'] = float(np.mean(cors)); o[f'cv_top1_K{k}'] = hits / tot
            o[f'cv_top1_chance_K{k}'] = len(P) / tot    # expected top-1 rate under random correspondence
            if by_component and k == K: o['cv_r_by_component'] = np.mean(cors, axis=0)
        out[(a, b)] = o
    return out

def cv_panel(Gd, r, seed, models=MODELS, pairs=PAIRS, ks=KS, by_component=False):
    F = cv_folds(len(r), seed)
    P = [{m: cv_proj(Gd[m], r[tr], r[te]) for m in models} for tr, te in F]
    return cv_eval(P, pairs, ks, by_component), P, F

def pval(o, nl): return float((1 + np.sum(np.asarray(nl) >= o)) / (len(nl) + 1))
def mean3(d): return float(np.mean([d[p] for p in PANELS]))

