def run_subsamples(frac, nrep, seed):
    rng = np.random.default_rng(seed); m = int(round(frac * nU))
    arr = {(pr, mt): {p: np.empty(nrep) for p in PANELS} for pr in PAIRS for mt in METRICS + CVCH}
    for b in range(nrep):
        sel = np.zeros(nU, bool); sel[rng.choice(nU, m, replace=False)] = True
        s0 = int(rng.integers(1 << 30))
        outs = list(POOL.map(sub_panel, [(pi, pidx[p][sel[pidx[p]]], s0) for pi, p in enumerate(PANELS)]))
        for (pr, mt), d in arr.items():
            for pi, p in enumerate(PANELS): d[p][b] = outs[pi][pr][mt]
    return arr, m

def chance_at_size(frac, nrep, seed):   # in-sample chance levels at the subsample size (they depend on n/K)
    rng = np.random.default_rng(seed); m = int(round(frac * nU))
    acc = {(pr, mt): {p: [] for p in PANELS} for pr in [MS, MG] for mt in INS}
    for b in range(nrep):
        sel = np.zeros(nU, bool); sel[rng.choice(nU, m, replace=False)] = True
