            r = pidx[p][sel[pidx[p]]]
            nl = perm_null_insample(panel_fit(G_main, r, rsa=[]), [rng.permutation(len(r))], [MS, MG])
            for pr in [MS, MG]:
                for mt in INS: acc[(pr, mt)][p].append(nl[pr][mt][0])
    return {k: {p: float(np.mean(v)) for p, v in d.items()} for k, d in acc.items()}

