                 no_secondary_ratio_ci_below_margin=not any(res_ratio[m]['ci'][1] < margin for m in SECONDARY))
    if not beyond: v = 'not aligned with scGPT beyond chance'
    elif all(clearly.values()): v = 'aligned with scGPT but clearly less than with Geneformer'
    elif all(about.values()): v = 'aligned with scGPT about as well as with Geneformer'
