        o = insample(panel_fit(G_main, rb, models=MODELS, rsa=[]), [MS, MG], ks=(K,))
        for pr in [MS, MG]: boot[PK[pr]].append(o[pr]['cca_mean_r_K20'])
        uniq.append(len(np.unique(rb)) / len(rb))
sens['ordinary_bootstrap_inflation'] = dict(
    full_sample_cca_mean_r_K20={PK[pr]: summary[(pr, 'cca_mean_r_K20')]['mean3'] for pr in [MS, MG]},
    mean_bootstrap_cca_mean_r_K20={k: float(np.mean(v)) for k, v in boot.items()},
    mean_fraction_unique_genes=float(np.mean(uniq)))

# ------------------------------------------------------------------ descriptive diagnostics
diag = {'pca_variance_explained_K20': {m: {p: float(fits[p]['w'][m].sum() / fits[p]['tr'][m]) for p in PANELS} for m in MODELS},
        'insample_canonical_r_by_component_mean3': {PK[pr]: np.mean([cca_r(fits[p]['V'][pr[0]], fits[p]['V'][pr[1]]) for p in PANELS], axis=0).tolist() for pr in PAIRS},
        'cv_canonical_r_by_component_mean3': {PK[pr]: np.mean([cv_bycomp[p][PK[pr]] for p in PANELS], axis=0).tolist() for pr in PAIRS}}
eu = {'spearman_pca20_euclidean_distance_vs_own_norm_sum': {}, 'spearman_pca20_row_norms_between_models': {}}
for p in PANELS:
    f = fits[p]; nn = {}
    for m in MODELS:
        S = f['V'][m] * np.sqrt(f['w'][m]); nn[m] = (S ** 2).sum(1)
        de = d_euc(S @ S.T, f['iu']); ns = (nn[m][:, None] + nn[m][None, :])[f['iu']]
        eu['spearman_pca20_euclidean_distance_vs_own_norm_sum'].setdefault(m, {})[p] = float(spearmanr(de, ns)[0])
    for pr in PAIRS:
        eu['spearman_pca20_row_norms_between_models'].setdefault(PK[pr], {})[p] = float(spearmanr(nn[pr[0]], nn[pr[1]])[0])
diag['euclidean_pca20_norm_dependence'] = eu
diag['subsample_settings'] = dict(m_sub=m_sub, scale_sub=SCALE, m_half=m_half, scale_half=SCALE_H, n_union=nU)
t_sens = time.time()

# ------------------------------------------------------------------ estimates
est = []
def add(name, value, lo, hi, how):
    r4 = lambda x: None if x is None else round(float(x), 4)
    est.append(dict(name=name, value=r4(value), ci_low=r4(lo), ci_high=r4(hi), method_of_uncertainty=how))
SUBM = (f'95% CI by gene subsampling (delete-d jackknife, d = n/4): {N_SUB} random 3/4-subsamples of the 828-gene union '
        f'without replacement, deviations from the subsample mean rescaled by sqrt(3); mean over 3 panels')
NULLM = lambda nperm: f'central 95% range of the gene-permutation null ({nperm} permutations per panel; mean over 3 panels)'
LABEL = {'cca_mean_r_K20': 'mean canonical correlation, in-sample, K=20', 'cv_cca_mean_r_K20': 'mean canonical correlation, held-out genes (5-fold CV x3), K=20',
         'cca_mean_r_K10': 'mean canonical correlation, in-sample, K=10', 'cv_cca_mean_r_K10': 'mean canonical correlation, held-out genes, K=10',
         'cca_mean_r_K5': 'mean canonical correlation, in-sample, K=5', 'cv_cca_mean_r_K5': 'mean canonical correlation, held-out genes, K=5',
         'rsa_cos_full': 'distance agreement (Spearman), centred cosine, full dimension',
         'rsa_cos_pca20': 'distance agreement (Spearman), cosine on 20 PCA scores',
         'rsa_euc_pca20': 'distance agreement (Spearman), Euclidean on 20 PCA scores',
         'rsa_euc_pca20_whitened': 'distance agreement (Spearman), Euclidean on 20 whitened PCA scores',
         'rsa_euc_full': 'distance agreement (Spearman), Euclidean, full dimension',
         'top1_K20': 'top-1 gene retrieval, in-sample, K=20', 'cv_top1_K20': 'top-1 gene retrieval, held-out genes, K=20'}
for mt in LABEL:
    for pr in PAIRS:
        rp = res_pairs[f'{PK[pr]}|{mt}']
        add(f'{LABEL[mt]}: {PK[pr]} (mean over 3 panels)', rp['mean3'], *rp['ci_mean3'], SUBM)
    rp = res_pairs[f'{PK[MS]}|{mt}']
    if 'null_mean' in rp:
        nperm = N_PERM_CV if mt in CVM else N_PERM
        add(f'{LABEL[mt]}: chance level for MaxToki-scGPT (permutation-null mean)', rp['null_mean'], rp['null_q025'], rp['null_q975'], NULLM(nperm))
        add(f'{LABEL[mt]}: permutation p-value MaxToki-scGPT above chance (largest of the 3 per-panel p-values)', rp['p_max_over_panels'], None, None,
            f'one-sided gene-permutation test per panel, {nperm} permutations, p=(1+#null>=obs)/(N+1); smallest per-panel z = {min(rp["z_panel"].values()):.1f}')
    if mt.startswith('cv_top1'):
        add(f'{LABEL[mt]}: chance level (expected 1/n_test)', rp['chance_expected'], None, None, 'analytic expectation under random correspondence')
    rd = res_diff[f'{DIFF}|{mt}']
    add(f'{LABEL[mt]}: difference MaxToki-Geneformer minus MaxToki-scGPT (mean over 3 panels)', rd['mean3'], *rd['ci_mean3'], SUBM + '; paired')
    if mt in res_ratio:
        rr = res_ratio[mt]
        add(f'{LABEL[mt]}: ratio of above-chance alignment, MaxToki-scGPT / MaxToki-Geneformer', rr['value'], *rr['ci'],
            SUBM + '; paired; chance levels evaluated at the matching number of genes')
    rd2 = res_diff[f'Geneformer-scGPT minus MaxToki-scGPT|{mt}']
    add(f'{LABEL[mt]}: difference Geneformer-scGPT minus MaxToki-scGPT (mean over 3 panels)', rd2['mean3'], *rd2['ci_mean3'], SUBM + '; paired')
PANM = f'95% CI by gene subsampling (delete-d jackknife, d = n/4, {N_SUB} subsamples, rescaled by sqrt(3)); single panel'
for p in PANELS:
    for mt in ['cca_mean_r_K20', 'cv_cca_mean_r_K20']:
        for pr in [MS, MG]:
            rp = res_pairs[f'{PK[pr]}|{mt}']
            add(f'{LABEL[mt]}: {PK[pr]}, panel {p}', rp['per_panel'][p], *rp['ci_panel'][p], PANM)
    for mt in ['cca_mean_r_K20', 'cv_cca_mean_r_K20', 'cca_mean_r_K10', 'cv_cca_mean_r_K10', 'cca_mean_r_K5', 'cv_cca_mean_r_K5',
               'rsa_cos_full', 'rsa_cos_pca20', 'rsa_euc_pca20']:
        rd = res_diff[f'{DIFF}|{mt}']
        add(f'{LABEL[mt]}: difference MaxToki-Geneformer minus MaxToki-scGPT, panel {p}', rd['per_panel'][p], *rd['ci_panel'][p], PANM + '; paired')

def clean(o):
    if isinstance(o, dict): return {(k if isinstance(k, str) else str(k)): clean(v) for k, v in o.items()}
    if isinstance(o, (list, tuple)): return [clean(v) for v in o]
    if isinstance(o, np.ndarray): return clean(o.tolist())
    if isinstance(o, (np.floating, float)): return round(float(o), 5)
    if isinstance(o, (np.integer,)): return int(o)
    if isinstance(o, np.bool_): return bool(o)
    return o
print(json.dumps(clean(dict(
    verdict=verdict, decision=decision, estimates=est, data_checks=mapping,
    pairs=res_pairs, differences=res_diff, ratios=res_ratio, sensitivity=sens, diagnostics=diag,
    settings=dict(K=K, KS=KS, N_PERM=N_PERM, N_PERM_CV=N_PERM_CV, N_SUB=N_SUB, N_HALF=N_HALF, N_CHANCE_SUB=N_CHANCE_SUB,
                  N_PERM_SENS=N_PERM_SENS, N_BOOT_DEMO=N_BOOT_DEMO, CV_FOLDS=CV_FOLDS, CV_REPS=CV_REPS, SUB_FRAC=SUB_FRAC,
                  MARGIN=MARGIN, SEED=SEED, scgpt_layernorm=True),
    runtime_s=dict(observed_and_perm=t_obs - t0, subsampling=t_sub - t_obs, half_sampling=t_half - t_sub,
                   chance_and_cis=t_ci - t_half, sensitivity_diagnostics=t_sens - t_ci, total=time.time() - t0))), indent=1))

#!/usr/bin/env python3
"""
MaxToki-217M gene-embedding alignment with scGPT (whole-human) and Geneformer V2-316M.

Follows contract/SPEC.md Phase 4 (H24 cross-model alignment) on the input gene-token embedding
tables, restricted to the three gene panels in data/panels/ (each panel analysed separately;
summaries are means over the 3 panels).
  * per panel and model: centre the genes; PCA to K components (whitened scores); K = 20 (SPEC
    default), 10 (SPEC alternate) and 5;
  * in-sample whitened CCA between the two models' PCA scores -> mean of the K canonical r;
  * cross-validated CCA: PCA + CCA fitted on 80% of the genes, canonical correlations and top-1
    retrieval evaluated on the held-out 20% (5 folds x 3 repeats);
  * top-1 gene retrieval in the shared canonical space (cosine; mean of both directions);
  * distance agreement (RSA): Spearman correlation between the two models' centred-cosine
    distance matrices on the full-dimensional embeddings (norm-free, does not depend on K).
Chance: gene-permutation null (gene correspondence shuffled), plus a covariate-stratified null
that shuffles only within deciles of MaxToki row norm (a proxy for token frequency).
Uncertainty: resampling unit = gene. Delete-d jackknife with d = n/2 (random half-samples of the
828-gene union without replacement; each panel keeps its genes in the half); 95% CI = full-sample
estimate + 2.5/97.5% quantiles of the centred half-sample estimates. Pair differences and ratios
are paired within half-samples. Ratios of above-chance alignment subtract a chance level computed
at the same gene count (full panels for the estimate, half panels for the half-samples).
Decision rule (post hoc; fixed after exploratory point estimates): primary estimand = ratio R of
above-chance distance agreement, MaxToki-scGPT / MaxToki-Geneformer; equivalence range
[0.8, 1.25]. Also reported: the same classification for every other metric and K, and a
significance-only rule on CCA at each K.
Other analyses: random genome-wide gene sets, scGPT without LayerNorm, unit-length rows, the
828-gene union, Euclidean RSA, ordinary-bootstrap inflation check, full-vocabulary token-id check.
scGPT rows are passed through the checkpoint's enc_norm LayerNorm. Run from the package root;
prints JSON to stdout (progress to stderr).
"""
import json, os, sys, time
import numpy as np, pandas as pd
from scipy.linalg import eigh, svd
from scipy.stats import rankdata, chi2, spearmanr

t_start = time.time()
def log(*a): print(f'[{time.time() - t_start:6.1f}s]', *a, file=sys.stderr, flush=True)
ENV = lambda k, d: int(os.environ.get(k, d))
D = 'data'
K = 20
KS = (20, 10, 5)
N_PERM = ENV('N_PERM', 500)              # plain gene-permutation null (in-sample metrics, RSA)
N_PERM_STRAT = ENV('N_PERM_STRAT', 200)  # norm-stratified permutation null
N_PERM_CV = ENV('N_PERM_CV', 100)        # permutation null for cross-validated CCA (K = 20)
N_PERM_SENS = ENV('N_PERM_SENS', 100)    # permutation p for sensitivity variants
N_HALF = ENV('N_HALF', 300)              # half-samples (main metrics, cross-validated CCA)
N_HALF_SENS = ENV('N_HALF_SENS', 100)    # first half-samples also used for the sensitivity variants
N_CHANCE_HS = ENV('N_CHANCE_HS', 60)     # first half-samples used to estimate chance at half size (5 perms each)
N_RAND = ENV('N_RAND', 30)               # random genome-wide gene sets of 370 genes
N_RAND_N = ENV('N_RAND_N', 20)           # random sets at n = 185 and 740
N_BOOT = ENV('N_BOOT', 100)              # ordinary bootstrap (inflation check only)
MARGIN = 0.8                             # equivalence range for above-chance ratios: [0.8, 1.25]
SEED = 20261001
PANELS = ['lung', 'immune', 'external_lung']
MODELS = ['MaxToki', 'Geneformer', 'scGPT']
PAIRS = [('MaxToki', 'scGPT'), ('MaxToki', 'Geneformer'), ('Geneformer', 'scGPT')]
MS, MG, GS = PAIRS
PK = {p: f'{p[0]}-{p[1]}' for p in PAIRS}

# ------------------------------------------------------------------ data, gene mapping, checks
mt_tok = json.load(open(f'{D}/maxtoki_217m/token_dictionary.json'))
gf_tok = json.load(open(f'{D}/geneformer_v2_316m/token_dictionary.json'))
sc_voc = json.load(open(f'{D}/scgpt_whole_human/vocab.json'))
es = pd.read_csv(f'{D}/gene_ids/ensembl_symbol.csv')
e2s = dict(zip(es.ensembl_id, es.symbol))
mt_genes = sorted(k for k in mt_tok if k.startswith('ENSG'))
gf_genes = sorted(k for k in gf_tok if k.startswith('ENSG'))
assert mt_genes == gf_genes and len(mt_genes) == 20271          # same 20,271 gene tokens ...
assert all(mt_tok[g] == gf_tok[g] for g in mt_genes)            # ... with identical token ids
assert max(mt_tok[g] for g in mt_genes) < 20275
T_mt = np.load(f'{D}/maxtoki_217m/embed_tokens.npy')
T_gf = np.load(f'{D}/geneformer_v2_316m/word_embeddings.npy')
T_sc = np.load(f'{D}/scgpt_whole_human/encoder_embedding_weight.npy')
ln = np.load(f'{D}/scgpt_whole_human/encoder_enc_norm.npz')
sc_trained = np.abs(T_sc).max(1) > 0.1      # rows never updated keep their U(-0.1, 0.1) init
mappable = [g for g in mt_genes if e2s.get(g) in sc_voc]
mappable_trained = [g for g in mappable if sc_trained[sc_voc[e2s[g]]]]

panels = {p: pd.read_csv(f'{D}/panels/{p}.csv').ensembl_id.astype(str).tolist() for p in PANELS}
union = sorted(set().union(*panels.values()))
pos = {g: i for i, g in enumerate(union)}
pidx = {p: np.array([pos[g] for g in panels[p]]) for p in PANELS}
for g in union:   # every panel gene maps in all three vocabularies and has a trained scGPT row
    assert g in mt_tok and e2s.get(g) in sc_voc and sc_trained[sc_voc[e2s[g]]], g
nU = len(union)

def layernorm(X):  # scGPT GeneEncoder output = enc_norm(embedding(token))
    m = X.mean(1, keepdims=True); v = X.var(1, keepdims=True)
    return (X - m) / np.sqrt(v + float(ln['eps'])) * ln['weight'].astype(np.float64) + ln['bias'].astype(np.float64)

def emb_rows(genes, scgpt_ln=True):
    X = {'MaxToki': T_mt[[mt_tok[g] for g in genes]].astype(np.float64),
         'Geneformer': T_gf[[gf_tok[g] for g in genes]].astype(np.float64)}
    S = T_sc[[sc_voc[e2s[g]] for g in genes]].astype(np.float64)
    X['scGPT'] = layernorm(S) if scgpt_ln else S
    return X

def grams(E): return {m: X @ X.T for m, X in E.items()}
unit = lambda X: X / np.linalg.norm(X, axis=1, keepdims=True)
E_main = emb_rows(union)
E_noln = emb_rows(union, scgpt_ln=False)
G_main = grams(E_main)
G_noln = grams(E_noln)
G_unit = grams({m: unit(X) for m, X in E_main.items()})
G_all = dict(G_main, scGPT_raw=G_noln['scGPT'], **{f'{m}_u': G_unit[m] for m in MODELS})
row_norm = {m: np.linalg.norm(X, axis=1) for m, X in E_main.items()}
row_norm['scGPT_raw'] = np.linalg.norm(E_noln['scGPT'], axis=1)

# ------------------------------------------------------------------ metric primitives
def centred_gram(Gu, r):
    Gs = Gu[np.ix_(r, r)]; rm = Gs.mean(1)
    return Gs - rm[:, None] - rm[None, :] + rm.mean()

def top_u(Gc, k):  # whitened PCA scores (left singular vectors of the centred data)
    n = Gc.shape[0]
    return eigh(Gc, subset_by_index=[n - k, n - 1])[1][:, ::-1]

def zrank(x):
    r = rankdata(x); return (r - r.mean()) / r.std()

def cos_z(Gc, iu):  # z-scored ranks of centred-cosine distances, upper triangle
    dg = np.sqrt(np.diag(Gc))
    return zrank(1.0 - (Gc / dg[:, None] / dg[None, :])[iu])

def euc_z(Gc, iu):  # z-scored ranks of Euclidean distances (norm-sensitive)
    dg = np.diag(Gc)
    return zrank(np.sqrt(np.maximum(dg[:, None] + dg[None, :] - 2 * Gc, 0))[iu])

def cca_r(Ua, Ub): return svd(Ua.T @ Ub, compute_uv=False)

def retrieval(Ua, Ub):
    A, s, Bt = svd(Ua.T @ Ub)
    Ca = Ua @ A; Cb = Ub @ Bt.T
    Ca = Ca / np.linalg.norm(Ca, axis=1, keepdims=True); Cb = Cb / np.linalg.norm(Cb, axis=1, keepdims=True)
    S = Ca @ Cb.T; ar = np.arange(len(S))
    return 0.5 * (np.mean(S.argmax(1) == ar) + np.mean(S.argmax(0) == ar))

def prep(Gd, r, models, k=K, rsa_models=(), euc_models=()):
    n = len(r); iu = np.triu_indices(n, 1)
    Gc = {m: centred_gram(Gd[m], r) for m in models}
    U = {m: top_u(Gc[m], k) for m in models}
    Z = {m: cos_z(Gc[m], iu) for m in rsa_models}
    Ze = {m: euc_z(Gc[m], iu) for m in euc_models}
    return U, Z, Ze, iu

def pair_metrics(U, Z, Ze, pairs, ks=KS):
    """pairs: {output key: (model a, model b)}"""
    out = {}
    for key, (a, b) in pairs.items():
        d = {}
        for k in ks:
            d[f'cca_K{k}'] = float(cca_r(U[a][:, :k], U[b][:, :k]).mean())
            d[f'ret_K{k}'] = float(retrieval(U[a][:, :k], U[b][:, :k]))
        if a in Z and b in Z: d['rsa_cos'] = float(np.mean(Z[a] * Z[b]))
        if a in Ze and b in Ze: d['rsa_euc'] = float(np.mean(Ze[a] * Ze[b]))
        out[key] = d
    return out

def insample(Gd, r, pairs=PAIRS, ks=KS, rsa=True, euc=False):
    models = sorted({m for pr in pairs for m in pr})
    U, Z, Ze, iu = prep(Gd, r, models, max(ks), models if rsa else (), models if euc else ())
    return pair_metrics(U, Z, Ze, {pr: pr for pr in pairs}, ks), U, Z, iu

def perm_null(U, Z, iu, n, perms, pairs, ks=KS):
    rsa = bool(Z)
    names = [f'cca_K{k}' for k in ks] + [f'ret_K{k}' for k in ks] + (['rsa_cos'] if rsa else [])
    res = {pr: {nm: np.empty(len(perms)) for nm in names} for pr in pairs}
    Zf = {}
    if rsa:
        for m in {b for _, b in pairs}:
            F = np.zeros((n, n)); F[iu] = Z[m]; Zf[m] = (F + F.T).ravel()
    for i, p in enumerate(perms):
        fidx = p[iu[0]] * n + p[iu[1]] if rsa else None
        for a, b in pairs:
            Ubp = U[b][p]   # row i of model b now belongs to gene p[i]: random gene correspondence
            for k in ks:
                res[(a, b)][f'cca_K{k}'][i] = cca_r(U[a][:, :k], Ubp[:, :k]).mean()
                res[(a, b)][f'ret_K{k}'][i] = retrieval(U[a][:, :k], Ubp[:, :k])
            if rsa: res[(a, b)]['rsa_cos'][i] = np.mean(Z[a] * Zf[b][fidx])
    return res

def proj_g(Gu, tr, te, k):  # PCA fitted on training genes: whitened train scores + projected test scores
    Gtt = Gu[np.ix_(tr, tr)]; rm = Gtt.mean(1); mm = rm.mean()
    Gc = Gtt - rm[:, None] - rm[None, :] + mm
    n = len(tr); w, V = eigh(Gc, subset_by_index=[n - k, n - 1]); V = V[:, ::-1]; w = w[::-1]
    Gx = Gu[np.ix_(te, tr)]; cx = Gx.mean(1)
    return V, (Gx - cx[:, None] - rm[None, :] + mm) @ V / w

def fold_stats(Atr, Ate, Btr, Bte):  # CCA fitted on training scores, evaluated on held-out genes
    A, s, Bt = svd(Atr.T @ Btr); Ca = Ate @ A; Cb = Bte @ Bt.T
    Cac = Ca - Ca.mean(0); Cbc = Cb - Cb.mean(0)
    cr = (Cac * Cbc).sum(0) / np.sqrt((Cac ** 2).sum(0) * (Cbc ** 2).sum(0))
    Can = Ca / np.linalg.norm(Ca, axis=1, keepdims=True); Cbn = Cb / np.linalg.norm(Cb, axis=1, keepdims=True)
    S = Can @ Cbn.T; ar = np.arange(len(Ca))
    return cr, 0.5 * (np.sum(S.argmax(1) == ar) + np.sum(S.argmax(0) == ar))

def cv_metrics(Gd, r, pairs=PAIRS, ks=KS, folds=5, reps=3, seed=SEED + 3, rows=None, cache=None):
    rows = rows or {}
    rng = np.random.default_rng(seed); models = sorted({m for pr in pairs for m in pr})
    cors = {(pr, k): [] for pr in pairs for k in ks}; hits = {(pr, k): 0.0 for pr in pairs for k in ks}
    tot, inv, fi = 0, [], 0
    for _ in range(reps):
        for f in np.array_split(rng.permutation(len(r)), folds):
            tr = np.setdiff1d(np.arange(len(r)), f); P = {}
            for m in models:
                if cache is not None and m not in rows and (m, fi) in cache:
                    P[m] = cache[(m, fi)]; continue
                rr = rows.get(m, r); P[m] = proj_g(Gd[m], rr[tr], rr[f], max(ks))
                if cache is not None and m not in rows: cache[(m, fi)] = P[m]
            fi += 1; tot += len(f); inv.append(1.0 / len(f))
            for a, b in pairs:
                for k in ks:
                    cr, h = fold_stats(P[a][0][:, :k], P[a][1][:, :k], P[b][0][:, :k], P[b][1][:, :k])
                    cors[((a, b), k)].append(cr); hits[((a, b), k)] += h
    out = {}
    for pr in pairs:
        d = {}
        for k in ks:
            d[f'cvcca_K{k}'] = float(np.mean(cors[(pr, k)])); d[f'cvret_K{k}'] = float(hits[(pr, k)] / tot)
        d['cv_ret_chance'] = float(np.mean(inv))   # expected top-1 hit rate for a random match
        out[pr] = d
    return out

def pval(o, nl): return float((1 + np.sum(np.asarray(nl) >= o)) / (len(nl) + 1))
def jk_ci(est, th):
    dev = np.asarray(th) - np.mean(th)
    return [float(est + np.quantile(dev, .025)), float(est + np.quantile(dev, .975))]
def m3(d): return float(np.mean([d[p] for p in PANELS]))

IN_METRICS = [f'cca_K{k}' for k in KS] + [f'ret_K{k}' for k in KS] + ['rsa_cos']
CV_METRICS = [f'cvcca_K{k}' for k in KS] + [f'cvret_K{k}' for k in KS]

# ------------------------------------------------------------------ observed values + plain and norm-stratified permutation nulls
rng_perm = np.random.default_rng(SEED)
rng_strat = np.random.default_rng(SEED + 5)
obs, null, snull = {}, {}, {}
for p in PANELS:
    r = pidx[p]; n = len(r)
    o, U, Z, iu = insample(G_main, r, euc=True)
    obs[p] = o
    null[p] = perm_null(U, Z, iu, n, [rng_perm.permutation(n) for _ in range(N_PERM)], PAIRS)
