# ------------------------------------------------------------------ summaries
def obs_pp(variant, metric, pr):
    if variant == 'main': return {p: obs[p][pr][metric] for p in PANELS}
    if variant == 'cv': return {p: cv_obs[p][pr][metric] for p in PANELS}
def null_pp(variant, metric, pr):
    if variant == 'main' and metric in null[PANELS[0]][pr]: return {p: null[p][pr][metric] for p in PANELS}
    if variant == 'cv' and pr in cv_null[PANELS[0]] and metric in cv_null[PANELS[0]][pr]: return {p: cv_null[p][pr][metric] for p in PANELS}
    return None
def hs3(variant, metric, pr): return np.mean([HS[(variant, metric, pr)][p] for p in PANELS], axis=0)

def chance_levels(variant, metric, pr):
    """(full-size chance per panel, chance for the 3-panel mean at half size: scalar or per-half-sample array)"""
    if variant == 'cv' and metric.startswith('cvcca'):
        return {p: 0.0 for p in PANELS}, 0.0            # held-out canonical r of unrelated tables has expectation 0
    if variant == 'cv' and metric.startswith('cvret'):
        return {p: cv_obs[p][pr]['cv_ret_chance'] for p in PANELS}, hs3('cv', 'cv_ret_chance', pr)
    nl = null_pp(variant, metric, pr)
    full = {p: float(nl[p].mean()) for p in PANELS}
    if metric == 'rsa_cos': return full, m3(full)        # chance ~ 0 at any n
    return full, half_chance[(pr, metric)]

DIFF = 'MaxToki-Geneformer minus MaxToki-scGPT'
RATIO = 'ratio MaxToki-scGPT / MaxToki-Geneformer above chance'
S = {}
def summarize(variant, metric):
    out = {}
    for pr in PAIRS:
        o = obs_pp(variant, metric, pr); h = HS[(variant, metric, pr)]
        d = dict(per_panel=o, mean3=m3(o), ci_mean3=jk_ci(m3(o), hs3(variant, metric, pr)),
                 ci_panel={p: jk_ci(o[p], h[p]) for p in PANELS}, half_sample_mean3=float(hs3(variant, metric, pr).mean()))
        nl = null_pp(variant, metric, pr)
        if nl is not None:
            nl3 = np.mean([nl[p] for p in PANELS], axis=0); pp = {p: pval(o[p], nl[p]) for p in PANELS}
            d.update(null_mean=float(nl3.mean()), null_q025=float(np.quantile(nl3, .025)), null_q975=float(np.quantile(nl3, .975)),
                     z_vs_null=float((m3(o) - nl3.mean()) / nl3.std()), p_mean3=pval(m3(o), nl3), p_panel=pp,
                     fisher_p_panels=float(chi2.sf(-2 * np.sum(np.log(list(pp.values()))), 2 * len(PANELS))),
                     null_q95_panel={p: float(np.quantile(nl[p], .95)) for p in PANELS}, n_perm=len(nl3))
        out[PK[pr]] = d
    for lab, (hi, lo) in {DIFF: (MG, MS), 'Geneformer-scGPT minus MaxToki-scGPT': (GS, MS)}.items():
        dp = {p: obs_pp(variant, metric, hi)[p] - obs_pp(variant, metric, lo)[p] for p in PANELS}
        hp = {p: HS[(variant, metric, hi)][p] - HS[(variant, metric, lo)][p] for p in PANELS}
        h3 = np.mean([hp[p] for p in PANELS], axis=0)
        out[lab] = dict(per_panel=dp, mean3=m3(dp), ci_mean3=jk_ci(m3(dp), h3), ci_panel={p: jk_ci(dp[p], hp[p]) for p in PANELS},
                        half_sample_mean3=float(h3.mean()))
    cf_s, ch_s = chance_levels(variant, metric, MS); cf_g, ch_g = chance_levels(variant, metric, MG)
    os_, og = obs_pp(variant, metric, MS), obs_pp(variant, metric, MG)
    R = (m3(os_) - m3(cf_s)) / (m3(og) - m3(cf_g))
    Rh = (hs3(variant, metric, MS) - ch_s) / (hs3(variant, metric, MG) - ch_g)
    ci = jk_ci(R, Rh)
    rp = {p: (os_[p] - cf_s[p]) / (og[p] - cf_g[p]) for p in PANELS}
    cls = ('clearly less' if ci[1] < MARGIN and all(v < MARGIN for v in rp.values()) else
           'about as well' if ci[0] >= MARGIN and ci[1] <= 1 / MARGIN and all(MARGIN <= v <= 1 / MARGIN for v in rp.values())
           else 'undetermined')
    out[RATIO] = dict(mean3=float(R), ci_mean3=ci, per_panel=rp, chance_full_MS=m3(cf_s), chance_full_MG=m3(cf_g),
                      chance_half_MS=float(np.mean(ch_s)), chance_half_MG=float(np.mean(ch_g)), margin_class=cls)
    S[(variant, metric)] = out

