              for v, ms_ in [('main', IN_METRICS), ('cv', CV_METRICS)] for m in ms_}
def sig_rule(variant, cca_metric, secondary):
    d1 = S[(variant, cca_metric)][DIFF]; d2 = [S[s][DIFF] for s in secondary]
    if d1['ci_mean3'][0] > 0 and all(v > 0 for v in d1['per_panel'].values()) and any(x['ci_mean3'][0] > 0 for x in d2):
        return 'clearly less'
    if -0.05 < d1['ci_mean3'][0] <= 0 <= d1['ci_mean3'][1] < 0.05 and not any(x['ci_mean3'][0] > 0 for x in d2):
        return 'about as well'
    return 'inconclusive'
