#!/usr/bin/env python
"""MaxToki-217M gene-embedding alignment with scGPT (whole-human) versus Geneformer V2-316M.

Run from the package root (the folder that contains data/):
    <CODE_ROOT>/analysis-tasks/bin/python analysis.py
Reads only data/, writes nothing, prints one JSON object with every estimate (progress goes to stderr).
Runtime about 2-4 minutes on a laptop CPU.
"""
import os
for _v in ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS", "VECLIB_MAXIMUM_THREADS"):
    os.environ.setdefault(_v, "4")
import json
import sys
import time
import numpy as np
import pandas as pd
from scipy.linalg import solve_triangular

T0 = time.time()
SEED = 20261001
NBOOT = 1000            # joint gene bootstrap replicates (unit: gene, drawn from the union of the 3 panels)
NPERM = 999             # within-panel gene-label permutations (Mantel null) for the primary statistic
NPERM_UNION = 199       # joint permutations of the 828-gene union, applied to every panel (null for the 3-panel mean)
NPERM_FIT = 199         # within-panel permutations for fitted metrics (CCA, Procrustes, held-out CCA, CKA)
K_PCA = 20              # SPEC Phase 0 step 5
K_SWEEP = [5, 10, 20, 50, 100, 200]
HO_REPEATS = 10         # held-out CCA: 10 random 2-fold splits
N_RANDOM_SETS = 50      # random-gene baseline
RANDOM_SET_SIZE = 380
SC_TRAINED_NORM = 1.4   # scGPT rows at init have norm about 1.31 (sd about 0.03); > 1.4 = moved by training
LEN_DOM_RHO = 0.5       # a distance is called length-dominated if Spearman(d_ij, n_i+n_j) > 0.5 in any model/panel
RATIO_REF = 0.80        # magnitude cut shown only in the sensitivity table; NOT used for the verdict
D = "data"
PANELS = ["lung", "immune", "external_lung"]
PAIRS3 = [("MT", "SC"), ("MT", "GF"), ("GF", "SC")]
DIMS = [str(k) for k in K_SWEEP] + ["full"]


def log(msg):
    print(f"[{time.time() - T0:7.1f}s] {msg}", file=sys.stderr, flush=True)


# ----------------------------------------------------------------------------------------- load
def layer_norm(S, lnp):
    w, b, eps = lnp["weight"].astype(np.float64), lnp["bias"].astype(np.float64), float(lnp["eps"])
    return (S - S.mean(1, keepdims=True)) / np.sqrt(S.var(1, keepdims=True) + eps) * w + b


def load():
    mt = np.load(f"{D}/maxtoki_217m/embed_tokens.npy", mmap_mode="r")
    gf = np.load(f"{D}/geneformer_v2_316m/word_embeddings.npy", mmap_mode="r")
    sc = np.load(f"{D}/scgpt_whole_human/encoder_embedding_weight.npy", mmap_mode="r")
    lnp = dict(np.load(f"{D}/scgpt_whole_human/encoder_enc_norm.npz"))
    mt_tok = json.load(open(f"{D}/maxtoki_217m/token_dictionary.json"))
    gf_tok = json.load(open(f"{D}/geneformer_v2_316m/token_dictionary.json"))
    sc_voc = json.load(open(f"{D}/scgpt_whole_human/vocab.json"))
    sym = pd.read_csv(f"{D}/gene_ids/ensembl_symbol.csv").set_index("ensembl_id")["symbol"]
    panels = {p: pd.read_csv(f"{D}/panels/{p}.csv")["ensembl_id"].tolist() for p in PANELS}
    union = sorted(set().union(*panels.values()))
    for g in union:  # every panel gene must map in all three models; MT and GF ids must coincide
        assert g in mt_tok and g in gf_tok and mt_tok[g] == gf_tok[g], g
        assert g in sym.index and sym[g] in sc_voc, g
    mi = np.array([mt_tok[g] for g in union])
    si = np.array([sc_voc[sym[g]] for g in union])
    X = {"MT": np.asarray(mt[mi], dtype=np.float64),
         "GF": np.asarray(gf[mi], dtype=np.float64),
         "SCraw": np.asarray(sc[si], dtype=np.float64)}
    X["SC"] = layer_norm(X["SCraw"], lnp)                       # scGPT gene encoder applies enc_norm
    pos = {g: i for i, g in enumerate(union)}
    members = {p: np.array([pos[g] for g in panels[p]]) for p in PANELS}
    scn_all = np.linalg.norm(np.asarray(sc, dtype=np.float64), axis=1)
    init_norm = np.sqrt(512 * 0.1 ** 2 / 3.0)                   # scGPT init: uniform(-0.1, 0.1)
    # random-gene pool: every MaxToki gene token that maps to a trained scGPT row
    genes_all = [g for g, t in mt_tok.items() if g.startswith("ENSG") and t < mt.shape[0]]
    mapped = [g for g in genes_all if g in sym.index and sym[g] in sc_voc and gf_tok.get(g) == mt_tok[g]]
    pool = [g for g in mapped if scn_all[sc_voc[sym[g]]] > SC_TRAINED_NORM]
    pool_ids = (np.array([mt_tok[g] for g in pool]), np.array([sc_voc[sym[g]] for g in pool]))
    diag = {
        "n_genes": {p: len(panels[p]) for p in PANELS},
        "n_union": len(union),
        "overlap": {"lung&immune": len(set(panels["lung"]) & set(panels["immune"])),
                    "lung&external_lung": len(set(panels["lung"]) & set(panels["external_lung"])),
                    "immune&external_lung": len(set(panels["immune"]) & set(panels["external_lung"])),
                    "all_three": len(set(panels["lung"]) & set(panels["immune"]) & set(panels["external_lung"]))},
        "scgpt_init_row_norm_expected": round(float(init_norm), 3),
        "scgpt_frac_vocab_rows_near_init(norm<1.35)": round(float(np.mean(scn_all[:60694] < 1.35)), 3),
        "scgpt_panel_min_row_norm": round(float(np.linalg.norm(X["SCraw"], axis=1).min()), 3),
        "random_pool_MT_genes_total": len(genes_all),
        "random_pool_mapped_to_scgpt": len(mapped),
        "random_pool_trained_scgpt_rows": len(pool),
    }
    return X, union, members, diag, (mt, gf, sc, lnp), pool_ids


# ------------------------------------------------------------------------------------ helpers
def center(Xs):
    return Xs - Xs.mean(0)


def cos_d(Xc):
    Xn = Xc / np.linalg.norm(Xc, axis=1, keepdims=True)
    return 1.0 - Xn @ Xn.T


def euc_d(Xc):
    sq = (Xc ** 2).sum(1)
    return np.sqrt(np.maximum(sq[:, None] + sq[None, :] - 2.0 * Xc @ Xc.T, 0.0))


def pca_scores(Xc, k):
    w, V = np.linalg.eigh(Xc @ Xc.T)            # Gram-matrix PCA (n << d)
    o = np.argsort(w)[::-1][:k]
    return V[:, o] * np.sqrt(np.maximum(w[o], 0.0))


def rank_vec(v):
    r = np.empty(len(v))
    r[np.argsort(v, kind="mergesort")] = np.arange(1, len(v) + 1)
    return r


def rank_mat(M):
    """Symmetric matrix of the ranks (1..n_pairs) of the upper-triangle entries of M (zero diagonal)."""
    n = len(M)
    iu = np.triu_indices(n, 1)
    R = np.zeros((n, n))
    R[iu] = rank_vec(M[iu])
    return R + R.T


def pearson(x, y):
    x = x - x.mean()
    y = y - y.mean()
    return float(x @ y / np.sqrt((x @ x) * (y @ y)))


def partial_r(a, b, Z):
    Z = np.column_stack([np.ones(len(a))] + list(Z))
    ra = a - Z @ np.linalg.lstsq(Z, a, rcond=None)[0]
    rb = b - Z @ np.linalg.lstsq(Z, b, rcond=None)[0]
    return pearson(ra, rb)


def norm_terms(Z, iu):
    nr = np.linalg.norm(Z, axis=1)
    return [rank_vec(np.add.outer(nr, nr)[iu]), rank_vec(np.abs(np.subtract.outer(nr, nr))[iu])]


def pct(a):
    a = np.asarray(a, dtype=float)
    return float(np.percentile(a, 2.5)), float(np.percentile(a, 97.5))


# fitted alignment metrics on PCA-20 scores
def cca_fit(Pa, Pb):
    Qa, _ = np.linalg.qr(center(Pa))
    Qb, _ = np.linalg.qr(center(Pb))
    return Qa, Qb


def cca_r(Pa, Pb):
    Qa, Qb = cca_fit(Pa, Pb)
    return float(np.linalg.svd(Qa.T @ Qb, compute_uv=False).mean())


def cca_variates(Pa, Pb):
    Qa, Qb = cca_fit(Pa, Pb)
    Uu, s, Vt = np.linalg.svd(Qa.T @ Qb)
    return Qa @ Uu, Qb @ Vt.T, s


def top1_hits(A, B):
    d = (A ** 2).sum(1)[:, None] + (B ** 2).sum(1)[None, :] - 2 * A @ B.T
    return (np.argmin(d, axis=1) == np.arange(len(A))).astype(float)


def procrustes_parts(Pa, Pb):
    A, B = center(Pa), center(Pb)
    A, B = A / np.linalg.norm(A), B / np.linalg.norm(B)
    return A, B


def procrustes_r(Pa, Pb):
    A, B = procrustes_parts(Pa, Pb)
    return float(np.linalg.svd(A.T @ B, compute_uv=False).sum())


def procrustes_hits(Pa, Pb):
    A, B = procrustes_parts(Pa, Pb)
    Uu, _, Vt = np.linalg.svd(A.T @ B)
    return top1_hits(A @ Uu @ Vt, B)


def ho_cca(Pa, Pb, labs):
    """Held-out CCA: fit on one half, mean of the 20 canonical correlations on the other half (2-fold x repeats)."""
    out = []
    for lab in labs:
        for f in (0, 1):
            tr, te = lab == f, lab != f
            ma, mb = Pa[tr].mean(0), Pb[tr].mean(0)
            Qa, Ra = np.linalg.qr(Pa[tr] - ma)
            Qb, Rb = np.linalg.qr(Pb[tr] - mb)
            Uu, _, Vt = np.linalg.svd(Qa.T @ Qb)
            Ca = (Pa[te] - ma) @ solve_triangular(Ra, Uu)
            Cb = (Pb[te] - mb) @ solve_triangular(Rb, Vt.T)
            Ca, Cb = Ca - Ca.mean(0), Cb - Cb.mean(0)
            out.append(np.mean((Ca * Cb).sum(0) / np.sqrt((Ca ** 2).sum(0) * (Cb ** 2).sum(0))))
    return float(np.mean(out))


def hsic_u(K, L):
    n = len(K)
    return (np.sum(K * L) + K.sum() * L.sum() / ((n - 1) * (n - 2))
            - 2.0 / (n - 2) * (K.sum(0) @ L.sum(0))) / (n * (n - 3))


def ucka(K, L):
    """Debiased linear CKA (unbiased HSIC, Song et al. 2012); K, L are Gram matrices with zero diagonal."""
    return float(hsic_u(K, L) / np.sqrt(hsic_u(K, K) * hsic_u(L, L)))


def zgram(Z):
    G = Z @ Z.T
    np.fill_diagonal(G, 0.0)
    return G


# --------------------------------------------------------------------------- representations
X, union, members, diag, tables, pool_ids = load()
U = len(union)
log("loaded")
MODELS = ["MT", "GF", "SC"]
RC, pcs, gram = {}, {}, {}
IU = {}


def add_rep(p, key, M):
    R = rank_mat(M)
    R -= R[IU[p]].mean()
    np.fill_diagonal(R, 0.0)
    RC[p][key] = R


for p in PANELS + ["union"]:
    idx = members[p] if p != "union" else np.arange(U)
    IU[p] = np.triu_indices(len(idx), 1)
    RC[p], pcs[p], gram[p] = {}, {}, {}
    if p == "union":
        for m in MODELS + ["SCraw"]:
            add_rep(p, f"cosfull:{m}", cos_d(center(X[m][idx])))
        continue
    for m in MODELS:
        Xc = center(X[m][idx])
        S = pca_scores(Xc, max(K_SWEEP))
        pcs[p][m] = S[:, :K_PCA]
        gram[p][m] = {"full": zgram(Xc), "p20": zgram(S[:, :K_PCA])}
        for d in DIMS:
            Z = Xc if d == "full" else S[:, :int(d)]
            add_rep(p, f"cos{d}:{m}", cos_d(Z))
            add_rep(p, f"euc{d}:{m}", euc_d(Z))
            nr = np.linalg.norm(Z, axis=1)
            add_rep(p, f"nsum{d}:{m}", np.add.outer(nr, nr))
            add_rep(p, f"ndif{d}:{m}", np.abs(np.subtract.outer(nr, nr)))
    add_rep(p, "cosfull:SCraw", cos_d(center(X["SCraw"][idx])))
    for a, b in PAIRS3:                                     # H24: pairwise distances in the whitened canonical space
        Ca, Cb, _ = cca_variates(pcs[p][a], pcs[p][b])
        for side, C in (("A", Ca), ("B", Cb)):
            add_rep(p, f"ccaE:{a}-{b}:{side}", euc_d(C))
            nr = np.linalg.norm(C, axis=1)
            add_rep(p, f"nsumccaE:{a}-{b}:{side}", np.add.outer(nr, nr))
            add_rep(p, f"ndifccaE:{a}-{b}:{side}", np.abs(np.subtract.outer(nr, nr)))
    log(f"representations {p}")

# diagnostics (each computed from one table at a time): spectrum isotropy, length dominance of each distance,
# cross-model row-norm agreement
rng_d = np.random.default_rng(SEED + 7)
for m in MODELS:
    Xc = center(X[m])
    ev = np.sort(np.linalg.eigvalsh(Xc @ Xc.T))[::-1]
    G = center(rng_d.normal(size=Xc.shape))
    evg = np.sort(np.linalg.eigvalsh(G @ G.T))[::-1]
    for k in (10, 20):
        diag[f"{m}_union_var_frac_top{k}PC"] = round(float(ev[:k].sum() / ev.sum()), 3)
        diag[f"{m}_union_var_frac_top{k}PC_gaussian_same_shape"] = round(float(evg[:k].sum() / evg.sum()), 3)
len_rho = {}
for p in PANELS:
    iu = IU[p]
    for m in MODELS:
        for d in DIMS:
            for met in ("cos", "euc"):
                len_rho[f"{met}{d}|{p}|{m}"] = pearson(RC[p][f"{met}{d}:{m}"][iu], RC[p][f"nsum{d}:{m}"][iu])
    for a, b in PAIRS3:
        for side in ("A", "B"):
            len_rho[f"ccaE|{p}|{a}-{b}:{side}"] = pearson(RC[p][f"ccaE:{a}-{b}:{side}"][iu],
                                                          RC[p][f"nsumccaE:{a}-{b}:{side}"][iu])
    for a, b in PAIRS3:
        na = np.linalg.norm(center(X[a][members[p]]), axis=1)
        nb = np.linalg.norm(center(X[b][members[p]]), axis=1)
        diag[f"{p}_rownorm_spearman_{a}_{b}"] = round(pearson(rank_vec(na), rank_vec(nb)), 3)
fam_len = {}
for key, v in len_rho.items():
    fam = key.split("|")[0]
    fam_len[fam] = max(fam_len.get(fam, -1.0), v)
LENGTH_DOMINATED = {f for f, v in fam_len.items() if v > LEN_DOM_RHO}
diag["length_dominance_max_spearman_dist_vs_normsum"] = {f: round(v, 3) for f, v in fam_len.items()}
diag["length_dominance_by_model_panel"] = {k: round(v, 3) for k, v in len_rho.items()
                                           if k.split("|")[0] in ("cosfull", "eucfull", "cos20", "euc20", "ccaE")}
log("diagnostics")

# ------------------------------------------------------------------------------- RSA statistics
# Every RSA statistic is a weighted Pearson correlation between rank-transformed pairwise distances over gene
# pairs i<j; with unit weights it is exactly Spearman's rho over all pairs. A gene bootstrap with multiplicities
# c_i corresponds to pair weights c_i*c_j (a gene paired with its own copy is excluded), so each weighted moment
# is a quadratic form 0.5 * c' F c with a zero-diagonal matrix F. Distance ranks are those of the full sample.
nsize = {p: len(members[p]) for p in PANELS}
nsize["union"] = U


def specs(p):
    if p == "union":
        return [(f"cosfull|{a}-{b}", "r", [f"cosfull:{a}", f"cosfull:{b}"]) for a, b in PAIRS3 + [("MT", "SCraw")]]
    out = []
    for d in DIMS:
        for a, b in PAIRS3:
            for met in ("cos", "euc"):
                out.append((f"{met}{d}|{a}-{b}", "r", [f"{met}{d}:{a}", f"{met}{d}:{b}"]))
                out.append((f"{met}P{d}|{a}-{b}", "partial",
                            [f"{met}{d}:{a}", f"{met}{d}:{b}", f"nsum{d}:{a}", f"ndif{d}:{a}",
                             f"nsum{d}:{b}", f"ndif{d}:{b}"]))
    out.append(("cosfull|MT-SCraw", "r", ["cosfull:MT", "cosfull:SCraw"]))
    for a, b in PAIRS3:
        k = f"{a}-{b}"
        out.append((f"ccaE|{k}", "r", [f"ccaE:{k}:A", f"ccaE:{k}:B"]))
        out.append((f"ccaEP|{k}", "partial", [f"ccaE:{k}:A", f"ccaE:{k}:B", f"nsumccaE:{k}:A", f"ndifccaE:{k}:A",
                                               f"nsumccaE:{k}:B", f"ndifccaE:{k}:B"]))
    return out


def batch_stats(p, Cm):
    """Cm: (B, n) gene multiplicities -> dict statistic -> array of B values."""
    W = 0.5 * (Cm.sum(1) ** 2 - (Cm ** 2).sum(1))
    S1, S2 = {}, {}

    def s1(k):
        if k not in S1:
            S1[k] = 0.5 * np.einsum("bi,bi->b", Cm @ RC[p][k], Cm) / W
        return S1[k]

    def cov(k, l):
        key = (k, l) if k <= l else (l, k)
        if key not in S2:
            S2[key] = 0.5 * np.einsum("bi,bi->b", Cm @ (RC[p][key[0]] * RC[p][key[1]]), Cm) / W
        return S2[key] - s1(k) * s1(l)

    out = {}
    for name, kind, keys in specs(p):
        if kind == "r":
            k, l = keys
            out[name] = cov(k, l) / np.sqrt(cov(k, k) * cov(l, l))
        else:                                   # partial correlation given the 4 row-norm terms
            Cmat = np.empty((Cm.shape[0], 6, 6))
            for i in range(6):
                for j in range(i, 6):
                    Cmat[:, i, j] = Cmat[:, j, i] = cov(keys[i], keys[j])
            Pm = np.linalg.inv(Cmat)
            out[name] = -Pm[:, 0, 1] / np.sqrt(Pm[:, 0, 0] * Pm[:, 1, 1])
    return out


obs = {p: {k: float(v[0]) for k, v in batch_stats(p, np.ones((1, nsize[p]))).items()} for p in PANELS + ["union"]}
log("observed")

# joint gene bootstrap over the union (keeps the panel overlap; same draw for every model pair and metric)
rng = np.random.default_rng(SEED)
CU = np.stack([np.bincount(rng.integers(0, U, U), minlength=U) for _ in range(NBOOT)]).astype(np.float64)
bootdf = {}
for p in PANELS:
    bootdf[p] = pd.DataFrame(batch_stats(p, CU[:, members[p]]))
    log(f"bootstrap {p}")
bootdf["union"] = pd.DataFrame(batch_stats("union", CU))
obsdf = {p: pd.Series(obs[p]) for p in obs}
log("bootstrap union")

