def jk_ci(theta_full, theta_i):
    theta_i = np.asarray(theta_i, dtype=float)
    nn = len(theta_i)
    se = np.sqrt((nn - 1) / nn * np.sum((theta_i - theta_i.mean()) ** 2))
    return float(theta_full - 1.96 * se), float(theta_full + 1.96 * se)


# retrieval: per-gene hit indicators of the full-sample fit, resampled with the same joint gene bootstrap
def hits_boot(p, k, key):
    c = CU[:, members[p]]
    return (c @ HITS[p][k][key]) / c.sum(1)


