def ridge_r2s(Xa, Ya, Xb, Yb, alphas):
    Uu, s, Vt = np.linalg.svd(Xa, full_matrices=False)
    UY = Uu.T @ Ya
    den = ((Yb - Yb.mean(0)) ** 2).sum()
    return [float(1 - ((Yb - Xb @ (Vt.T @ ((s / (s ** 2 + a_))[:, None] * UY))) ** 2).sum() / den) for a_ in alphas]


