# ----------------------------------------------------------------------------- verdict
# The rule below was fixed AFTER the results were seen (it is not a pre-registered test); the sensitivity
# table printed under "verdict_sensitivity" gives the verdict each alternative metric would have produced.
#  - not beyond chance: MT-SC primary permutation p >= 0.05 in any panel, or its 3-panel-mean CI reaches 0,
#    or the H24 CCA r of MT-SC is not above its permutation null (p >= 0.05) in any panel.
#  - clearly less: (a) primary gap (MT-GF minus MT-SC) CI above 0 for the 3-panel mean and in every panel;
#    (b) 3-panel-mean gap CI above 0 for each SPEC Phase 4 fitted metric (H24 CCA r, held-out CCA, H20 Procrustes r);
#    (c) no metric that is not length-dominated has a 3-panel-mean gap CI entirely below 0.
#  - about as well: primary 3-panel-mean gap CI includes 0.   - inconclusive: otherwise.
# No magnitude threshold enters the verdict; RATIO_REF is reported only as a sensitivity column.
def rule_direction(diff, panel_diffs):
    if diff[1] > 0 and all(pd_[1] > 0 for pd_ in panel_diffs):
        return "clearly less"
    if diff[1] <= 0 <= diff[2]:
        return "about as well"
    return "inconclusive"


def rule_with_ratio(diff, panel_diffs, ratio):
    v = rule_direction(diff, panel_diffs)
    if v == "clearly less" and not ratio <= RATIO_REF:
        return "inconclusive"
    return v


