def sens_row(label, group, diff, panel_diffs, ratio, length_dominated, mt_sc, mt_gf):
    sens.append({"metric": label, "group": group, "MT_SC": round(mt_sc, 4), "MT_GF": round(mt_gf, 4),
                 "diff_mean3": [round(x, 4) for x in diff],
                 "panels_with_gap_CI_above_0": int(sum(pd_[1] > 0 for pd_ in panel_diffs)),
                 "panels_with_gap_CI_below_0": int(sum(pd_[2] < 0 for pd_ in panel_diffs)),
                 "ratio_MTSC_over_MTGF": round(ratio, 4), "length_dominated": bool(length_dominated),
                 "rule_direction_and_CI": rule_direction(diff, panel_diffs),
                 "rule_plus_ratio_le_0.80": rule_with_ratio(diff, panel_diffs, ratio)})


def sens_boot(label, group, fam, ld):
    s_ = SUM[fam]
    sens_row(label, group, s_["diff"], list(s_["panel_diff"].values()), s_["ratio"][0], ld,
             s_["pairs"]["MT-SC"][0], s_["pairs"]["MT-GF"][0])


def sens_fit(label, group, key, ratio_key="ratio"):
    s_ = FIT_SUM[key]
    sens_row(label, group, s_["diff"], list(s_["panel_diff"].values()), s_[ratio_key][0], False,
             s_["pairs"]["MT-SC"][0], s_["pairs"]["MT-GF"][0])


sens_boot("centred-cosine RSA (primary)", "full dimension", "cosfull", "cosfull" in LENGTH_DOMINATED)
sens_boot("cosine RSA, row-norm partialled", "full dimension", "cosPfull", False)
sens_boot("Euclidean RSA, row-norm partialled", "full dimension", "eucPfull", False)
sens_boot("Euclidean RSA (raw)", "full dimension", "eucfull", "eucfull" in LENGTH_DOMINATED)
sens_fit("debiased linear CKA", "full dimension", "ucka_full")
sens_boot("cosine RSA", "PCA-20", "cos20", "cos20" in LENGTH_DOMINATED)
sens_boot("cosine RSA, row-norm partialled", "PCA-20", "cosP20", False)
sens_boot("Euclidean RSA (raw; SPEC 'pairwise-distance Spearman', reading 1)", "PCA-20", "euc20",
          "euc20" in LENGTH_DOMINATED)
sens_boot("Euclidean RSA, row-norm partialled", "PCA-20", "eucP20", False)
sens_fit("H24 CCA mean canonical r (raw ratio)", "PCA-20", "cca_r", "ratio_raw")
sens_fit("H24 CCA mean canonical r (excess over null)", "PCA-20", "cca_r")
sens_fit("H24 CCA in-sample top-1 retrieval", "PCA-20", "cca_top1")
sens_boot("H24 CCA-space distance Spearman (SPEC reading 2)", "PCA-20", "ccaE", "ccaE" in LENGTH_DOMINATED)
sens_boot("H24 CCA-space distance Spearman, norm partialled", "PCA-20", "ccaEP", False)
sens_fit("held-out CCA (2-fold x 10)", "PCA-20", "ho_cca")
sens_fit("H20 Procrustes r (excess over null)", "PCA-20", "procr_r")
sens_fit("H20 Procrustes in-sample top-1 retrieval", "PCA-20", "procr_top1")
sens_fit("debiased linear CKA", "PCA-20", "ucka_p20")
for k in (5, 10):
    sens_boot("cosine RSA", f"PCA-{k}", f"cos{k}", f"cos{k}" in LENGTH_DOMINATED)
    sens_boot("cosine RSA, row-norm partialled", f"PCA-{k}", f"cosP{k}", False)
    sens_boot("Euclidean RSA, row-norm partialled", f"PCA-{k}", f"eucP{k}", False)

beyond = (all(pvals[f"MT-SC_{p}"] < 0.05 for p in PANELS) and SUM["cosfull"]["pairs"]["MT-SC"][1] > 0
          and all(fitted_per_panel[p]["MT-SC"]["cca_r_perm_p"] < 0.05 for p in PANELS))
primary_clear = rule_direction(SUM["cosfull"]["diff"], list(SUM["cosfull"]["panel_diff"].values())) == "clearly less"
spec_same_dir = all(FIT_SUM[k]["diff"][1] > 0 for k in ("cca_r", "ho_cca", "procr_r"))
nonlen = ([f"{m}{d}" for m in ("cosP", "eucP") for d in DIMS] + ["ccaEP"]
          + [f"cos{d}" for d in DIMS if f"cos{d}" not in LENGTH_DOMINATED])
reversals = [f for f in nonlen if SUM[f]["diff"][2] < 0] + [k for k in FIT_SUM if FIT_SUM[k]["diff"][2] < 0]
panel_reversals = ([f"{f}:{p}" for f in nonlen for p in PANELS if SUM[f]["panel_diff"][p][2] < 0]
                   + [f"{k}:{p}" for k in FIT_SUM for p in PANELS if FIT_SUM[k]["panel_diff"][p][2] < 0])
if not beyond:
    verdict = "not aligned with scGPT beyond chance"
elif primary_clear and spec_same_dir and not reversals:
    verdict = "aligned with scGPT but clearly less than with Geneformer"
elif SUM["cosfull"]["diff"][1] <= 0 <= SUM["cosfull"]["diff"][2]:
    verdict = "aligned with scGPT about as well as with Geneformer"
else:
    verdict = "inconclusive"

out = {"verdict": verdict,
       "decision_inputs": {"MT_SC_beyond_chance(primary all panels, mean CI, H24 CCA all panels)": bool(beyond),
                           "primary_gap_CI_above_0_mean_and_every_panel": bool(primary_clear),
                           "SPEC_H24_heldoutCCA_H20_gap_CI_above_0": bool(spec_same_dir),
                           "non_length_dominated_metrics_with_reversed_mean_gap": reversals,
                           "non_length_dominated_metrics_with_a_reversed_panel": panel_reversals,
                           "length_dominated_families": sorted(LENGTH_DOMINATED),
                           "magnitude_cut_used_for_verdict": None,
                           "magnitude_cut_shown_in_sensitivity": RATIO_REF},
       "verdict_sensitivity": sens,
       "estimates": est,
       "permutation_pvalues": pvals,
       "fitted_per_panel": fitted_per_panel,
       "observed_per_panel": {p: {k: round(v, 4) for k, v in obs[p].items()
                                  if k.split("|")[0] in ("cosfull", "cosPfull", "eucfull", "eucPfull", "cos20",
                                                         "euc20", "cosP20", "eucP20", "ccaE", "ccaEP")}
                              for p in obs},
       "diagnostics": diag,
       "runtime_s": round(time.time() - T0, 1)}
print(json.dumps(out, indent=1))

#!/usr/bin/env python3
"""
MaxToki-217M gene-embedding geometry vs scGPT whole-human and vs Geneformer V2-316M.

Cross-model alignment as in SPEC Phase 4 (H24: whitened CCA on per-model PCA-20 gene
embeddings; pairwise-distance Spearman; gene-level top-1 retrieval), applied to the static
input token-embedding tables on the three gene panels, with held-out (cross-validated) CCA,
gene-label permutation nulls and a gene-level bootstrap.

Run from the package root:
    "<CODE_ROOT>/analysis-tasks/bin/python" this_script.py
Prints one JSON object to stdout ("estimates" holds every reported number); progress -> stderr.
"""
import os
for _v in ("OPENBLAS_NUM_THREADS", "OMP_NUM_THREADS", "MKL_NUM_THREADS", "VECLIB_MAXIMUM_THREADS"):
    os.environ.setdefault(_v, "1")
import json
import sys
import time

import numpy as np
import pandas as pd
from scipy.linalg import eigh as sp_eigh
from scipy.stats import rankdata

# ------------------------------------------------------------------ parameters
D = "data/"
PANELS = ["lung", "immune", "external_lung"]
PAIRS = [("M", "S"), ("M", "G"), ("G", "S")]   # M = MaxToki-217M, G = Geneformer V2-316M, S = scGPT
K = 20                 # PCA components per model and panel (SPEC Phase 0 step 5)
K_SENS = (10, 30)      # PCA-dimension sensitivity
NFOLD = 5              # gene-level folds for held-out CCA
N_SPLITS = 5           # fold re-draws averaged for each point estimate
N_PERM = 200           # gene-label permutations, CCA-based statistics
N_PERM_RSA = 500       # gene-label permutations, distance-correlation statistics
N_BOOT = 400           # gene-level bootstrap replicates (main metrics)
N_BOOT_SENS = 200      # gene-level bootstrap replicates (sensitivity variants; first 200 draws)
SEED = 20261001
Z975 = 1.959963984540054
T0 = time.time()


def log(msg):
    print(f"[{time.time() - T0:7.1f}s] {msg}", file=sys.stderr, flush=True)


# ------------------------------------------------------------------ data
tdM = json.load(open(D + "maxtoki_217m/token_dictionary.json"))
tdG = json.load(open(D + "geneformer_v2_316m/token_dictionary.json"))
voc = json.load(open(D + "scgpt_whole_human/vocab.json"))
es = pd.read_csv(D + "gene_ids/ensembl_symbol.csv")
e2s = dict(zip(es.ensembl_id.astype(str), es.symbol.astype(str)))
panels = {p: pd.read_csv(D + f"panels/{p}.csv").ensembl_id.astype(str).tolist() for p in PANELS}
union = sorted(set().union(*panels.values()))
for g in union:
    assert tdM[g] == tdG[g], g            # MaxToki and Geneformer share token ids
    assert g in e2s and e2s[g] in voc, g  # every panel gene has an scGPT token
tok = np.array([tdM[g] for g in union])
stok = np.array([voc[e2s[g]] for g in union])
assert len(set(stok)) == len(stok)
Mt = np.load(D + "maxtoki_217m/embed_tokens.npy", mmap_mode="r")
Gt = np.load(D + "geneformer_v2_316m/word_embeddings.npy", mmap_mode="r")
St = np.load(D + "scgpt_whole_human/encoder_embedding_weight.npy", mmap_mode="r")
lnp = np.load(D + "scgpt_whole_human/encoder_enc_norm.npz")


def enc_norm(X):
    """scGPT gene-encoder LayerNorm (encoder.enc_norm), applied row-wise."""
    mu = X.mean(1, keepdims=True)
    var = X.var(1, keepdims=True)
    return (X - mu) / np.sqrt(var + float(lnp["eps"])) * lnp["weight"].astype(float) + lnp["bias"].astype(float)


S_RAW = np.asarray(St[stok], dtype=float)
EMB = {"M": np.asarray(Mt[tok], dtype=float), "G": np.asarray(Gt[tok], dtype=float), "S": enc_norm(S_RAW)}
for _m, _X in EMB.items():
    assert np.isfinite(_X).all() and (np.linalg.norm(_X, axis=1) > 0).all(), _m
POS = {g: i for i, g in enumerate(union)}
PIDX = {p: np.array([POS[g] for g in panels[p]]) for p in PANELS}
NU = len(union)
log(f"loaded; union of panels = {NU} genes; panel sizes = {[len(PIDX[p]) for p in PANELS]}")


# ------------------------------------------------------------------ helpers
def pca_scores(X, k):
    """Top-k PCA scores (genes are rows) via the gene x gene Gram matrix."""
    Xc = X - X.mean(0)
    n = Xc.shape[0]
    w, V = sp_eigh(Xc @ Xc.T, subset_by_index=[n - k, n - 1])
    w, V = w[::-1], V[:, ::-1]
    return V * np.sqrt(np.clip(w, 0, None))


def pca_var_explained(X, k):
    Xc = X - X.mean(0)
    n = Xc.shape[0]
    Kg = Xc @ Xc.T
    w = sp_eigh(Kg, subset_by_index=[n - k, n - 1], eigvals_only=True)
    return float(w.sum() / np.trace(Kg))


def isqrt(C, reg=1e-6):
    w, V = np.linalg.eigh(C)
    w = np.clip(w, 0, None) + reg * w.max()
    return (V / np.sqrt(w)) @ V.T


def cca_fit(A, B):
    """Whitened CCA. Returns means, canonical weight matrices and canonical correlations (descending)."""
    ma, mb = A.mean(0), B.mean(0)
    Ac, Bc = A - ma, B - mb
    n = len(A)
    Wa, Wb = isqrt(Ac.T @ Ac / n), isqrt(Bc.T @ Bc / n)
    T = Wa @ (Ac.T @ Bc / n) @ Wb
    w, U = np.linalg.eigh(T @ T.T)
    w, U = w[::-1], U[:, ::-1]
    s = np.sqrt(np.clip(w, 1e-24, None))
    V = (T.T @ U) / s
    return ma, mb, Wa @ U, Wb @ V, np.minimum(s, 1.0)


def make_folds(groups, rng):
    """Gene-level folds; copies of one gene (bootstrap duplicates) always share a fold."""
    ug, inv = np.unique(groups, return_inverse=True)
    f = np.empty(len(ug), int)
    f[rng.permutation(len(ug))] = np.arange(len(ug)) % NFOLD
    return f[inv]


def cv_stats(A, B, folds, groups):
    """Held-out mean canonical correlation and held-out top-1 retrieval (both directions averaged)."""
    rs, hits, chance = [], [], []
    for k in range(NFOLD):
        te = folds == k
        tr = ~te
        ma, mb, Wa, Wb, s = cca_fit(A[tr], B[tr])
        ua = (A[te] - ma) @ Wa
        ub = (B[te] - mb) @ Wb
        uac, ubc = ua - ua.mean(0), ub - ub.mean(0)
        rs.append(np.mean((uac * ubc).sum(0) / np.sqrt((uac ** 2).sum(0) * (ubc ** 2).sum(0))))
        za, zb = ua * s, ub * s          # canonical space, axes weighted by training canonical correlation
        za /= np.linalg.norm(za, axis=1, keepdims=True)
        zb /= np.linalg.norm(zb, axis=1, keepdims=True)
        sim = za @ zb.T
        gt = groups[te]
        hits.append(0.5 * (np.mean(gt[sim.argmax(1)] == gt) + np.mean(gt[sim.argmax(0)] == gt)))
        chance.append(1.0 / te.sum())
    return float(np.mean(rs)), float(np.mean(hits)), float(np.mean(chance))


def rank_matrix(Dm):
    """Symmetric matrix of ranks of the off-diagonal pairwise values (diagonal 0)."""
    n = len(Dm)
    iu = np.triu_indices(n, 1)
    R = np.zeros((n, n))
    R[iu] = rankdata(Dm[iu])
    return R + R.T


def std_offdiag(R):
    """Standardise the off-diagonal entries (mean 0, SD 1 over pairs); diagonal set to 0."""
    n = len(R)
    iu = np.triu_indices(n, 1)
    v = R[iu]
    Z = (R - v.mean()) / v.std()
    np.fill_diagonal(Z, 0.0)
    return Z


def euclid(P):
    sq = (P ** 2).sum(1)
    return np.sqrt(np.clip(sq[:, None] + sq[None] - 2 * P @ P.T, 0, None))


def centred_cosine_dist(X):
    Xc = X - X.mean(0)
    Xn = Xc / np.linalg.norm(Xc, axis=1, keepdims=True)
    return 1.0 - Xn @ Xn.T


def weighted_rank_corr(Ra, Rb, C):
    """Pearson correlation of pairwise ranks over gene pairs i != j with pair weight c_i*c_j.
    C: (B, n) gene multiplicities. With C = 1 this is exactly Spearman's rho of the pairwise values."""
    C = np.atleast_2d(C).astype(float)
    sw = C.sum(1) ** 2 - (C ** 2).sum(1)

    def q(Mx):
        return ((C @ Mx) * C).sum(1)

    ea, eb = q(Ra) / sw, q(Rb) / sw
    cov = q(Ra * Rb) / sw - ea * eb
    va = q(Ra * Ra) / sw - ea ** 2
    vb = q(Rb * Rb) / sw - eb ** 2
    return cov / np.sqrt(va * vb)


def weighted_spearman_vec(x, y, C):
    """Pearson correlation of the ranks of per-gene values x, y with gene weights C (B, n)."""
    C = np.atleast_2d(C).astype(float)
    rx, ry = rankdata(x), rankdata(y)
    W = C / C.sum(1, keepdims=True)
    mx, my = W @ rx, W @ ry
    cov = W @ (rx * ry) - mx * my
    return cov / np.sqrt((W @ rx ** 2 - mx ** 2) * (W @ ry ** 2 - my ** 2))


# ------------------------------------------------------------------ per-panel representations
REP = {}
details = {"n_genes": {p: int(len(PIDX[p])) for p in PANELS}, "n_union": int(NU),
           "n_shared": {"lung&immune": len(set(panels["lung"]) & set(panels["immune"])),
                        "lung&external_lung": len(set(panels["lung"]) & set(panels["external_lung"])),
                        "immune&external_lung": len(set(panels["immune"]) & set(panels["external_lung"])),
                        "all_three": len(set(panels["lung"]) & set(panels["immune"]) & set(panels["external_lung"]))},
           "pca20_var_explained": {}, "table_element_sd_all_gene_rows": {}}
gene_rows = np.array(sorted(v for k, v in tdM.items() if k.startswith("ENSG")))
details["table_element_sd_all_gene_rows"] = {"M": round(float(np.asarray(Mt[gene_rows]).std()), 4),
                                             "G": round(float(np.asarray(Gt[gene_rows]).std()), 4),
                                             "M_init_range_config": 0.02}
for p in PANELS:
    idx = PIDX[p]
    r = {}
    P_main = {m: pca_scores(EMB[m][idx], max(K_SENS + (K,))) for m in "MGS"}
    for k in (K,) + K_SENS:
        r[f"k{k}"] = {m: P_main[m][:, :k].copy() for m in "MGS"}
    r["main"] = r[f"k{K}"]
    r["rawS"] = {"M": r["main"]["M"], "G": r["main"]["G"], "S": pca_scores(S_RAW[idx], K)}
    rown = {m: EMB[m][idx] / np.linalg.norm(EMB[m][idx], axis=1, keepdims=True) for m in "MGS"}
    r["rownorm"] = {m: pca_scores(rown[m], K) for m in "MGS"}
    r["R_euc"] = {m: rank_matrix(euclid(r["main"][m])) for m in "MGS"}
    r["R_cos"] = {m: rank_matrix(centred_cosine_dist(EMB[m][idx])) for m in "MGS"}
    r["Z_euc"] = {m: std_offdiag(r["R_euc"][m]) for m in "MGS"}
    r["Z_cos"] = {m: std_offdiag(r["R_cos"][m]) for m in "MGS"}
    # diagnostics for the Euclidean-PCA-20 distance correlation: per-gene radius in PCA-20 space
    r["rad20"] = {m: np.linalg.norm(r["main"][m], axis=1) for m in "MGS"}
    r["R_radsum"] = {m: rank_matrix(r["rad20"][m][:, None] + r["rad20"][m][None]) for m in "MGS"}
    details["pca20_var_explained"][p] = {m: round(pca_var_explained(EMB[m][idx], K), 4) for m in "MGS"}
    REP[p] = r
log("representations ready")

SENS = [("k10", [("M", "S"), ("M", "G")]), ("k30", [("M", "S"), ("M", "G")]),
        ("rawS", [("M", "S")]), ("rownorm", [("M", "S"), ("M", "G")])]

# ------------------------------------------------------------------ observed statistics
obs = {p: {} for p in PANELS}
rng_obs = np.random.default_rng([SEED, 1])
for p in PANELS:
    n = len(PIDX[p])
    groups = np.arange(n)
    ones = np.ones(n)
    splits = [make_folds(groups, rng_obs) for _ in range(N_SPLITS)]
    r = REP[p]
    for a, b in PAIRS:
        vals = np.array([cv_stats(r["main"][a], r["main"][b], f, groups) for f in splits]).mean(0)
        obs[p][a + b] = {"cv_cca": vals[0], "top1": vals[1], "top1_chance": vals[2],
                         "insample_cca": float(cca_fit(r["main"][a], r["main"][b])[4].mean()),
                         "rsa_euc20": float(weighted_rank_corr(r["R_euc"][a], r["R_euc"][b], ones)[0]),
                         "rsa_cos": float(weighted_rank_corr(r["R_cos"][a], r["R_cos"][b], ones)[0]),
                         "radius20_corr": float(weighted_spearman_vec(r["rad20"][a], r["rad20"][b], ones)[0])}
    for m in "MGS":
        obs[p]["diag_" + m] = {"euc20_vs_radius_sum": float(weighted_rank_corr(r["R_euc"][m], r["R_radsum"][m], ones)[0])}
    for var, prs in SENS:
        for a, b in prs:
            vals = np.array([cv_stats(r[var][a], r[var][b], f, groups) for f in splits]).mean(0)
            obs[p][f"{var}:{a}{b}"] = {"cv_cca": vals[0], "top1": vals[1]}
log("observed statistics done")

# ------------------------------------------------------------------ permutation nulls (gene labels of the 2nd model shuffled)
null = {p: {} for p in PANELS}
rng_perm = np.random.default_rng([SEED, 2])
for p in PANELS:
    n = len(PIDX[p])
    groups = np.arange(n)
    npairs2 = n * (n - 1)
    r = REP[p]
    for a, b in PAIRS:
        cv, t1, ins = np.empty(N_PERM), np.empty(N_PERM), np.empty(N_PERM)
        for i in range(N_PERM):
            pi = rng_perm.permutation(n)
            f = make_folds(groups, rng_perm)
            cv[i], t1[i], _ = cv_stats(r["main"][a], r["main"][b][pi], f, groups)
            ins[i] = cca_fit(r["main"][a], r["main"][b][pi])[4].mean()
        re_, rc_ = np.empty(N_PERM_RSA), np.empty(N_PERM_RSA)
        for i in range(N_PERM_RSA):
            pi = rng_perm.permutation(n)
            sub = np.ix_(pi, pi)
            re_[i] = np.sum(r["Z_euc"][a] * r["Z_euc"][b][sub]) / npairs2
            rc_[i] = np.sum(r["Z_cos"][a] * r["Z_cos"][b][sub]) / npairs2
        null[p][a + b] = {"cv_cca": cv, "top1": t1, "insample_cca": ins, "rsa_euc20": re_, "rsa_cos": rc_}
    log(f"permutation null done: {p}")

# ------------------------------------------------------------------ gene-level bootstrap (one draw over the union of panels per replicate)
rng_boot = np.random.default_rng([SEED, 3])
rng_bfold = np.random.default_rng([SEED, 4])
u2loc = {}
for p in PANELS:
    _m = np.full(NU, -1)
    _m[PIDX[p]] = np.arange(len(PIDX[p]))
    u2loc[p] = _m
boot = {p: {} for p in PANELS}
counts = {p: np.zeros((N_BOOT, len(PIDX[p]))) for p in PANELS}
for bi in range(N_BOOT):
    draw = rng_boot.integers(0, NU, NU)
    for p in PANELS:
        loc = u2loc[p][draw]
        loc = loc[loc >= 0]
        counts[p][bi] = np.bincount(loc, minlength=len(PIDX[p]))
        f = make_folds(loc, rng_bfold)
        r = REP[p]
        for a, b in PAIRS:
            A, B = r["main"][a][loc], r["main"][b][loc]
            cv, t1, _ = cv_stats(A, B, f, loc)
            d = boot[p].setdefault(a + b, {"cv_cca": [], "top1": [], "insample_cca": []})
            d["cv_cca"].append(cv)
            d["top1"].append(t1)
            d["insample_cca"].append(cca_fit(A, B)[4].mean())
        if bi < N_BOOT_SENS:
            for var, prs in SENS:
                for a, b in prs:
                    cv, t1, _ = cv_stats(r[var][a][loc], r[var][b][loc], f, loc)
                    d = boot[p].setdefault(f"{var}:{a}{b}", {"cv_cca": [], "top1": []})
                    d["cv_cca"].append(cv)
                    d["top1"].append(t1)
    if (bi + 1) % 50 == 0:
        log(f"bootstrap {bi + 1}/{N_BOOT}")
for p in PANELS:
    r = REP[p]
    for a, b in PAIRS:
        boot[p][a + b]["rsa_euc20"] = weighted_rank_corr(r["R_euc"][a], r["R_euc"][b], counts[p])
        boot[p][a + b]["rsa_cos"] = weighted_rank_corr(r["R_cos"][a], r["R_cos"][b], counts[p])
        boot[p][a + b]["radius20_corr"] = weighted_spearman_vec(r["rad20"][a], r["rad20"][b], counts[p])
    for m in "MGS":
        boot[p]["diag_" + m] = {"euc20_vs_radius_sum": weighted_rank_corr(r["R_euc"][m], r["R_radsum"][m], counts[p])}
    for key in boot[p]:
        for met in boot[p][key]:
            boot[p][key][met] = np.asarray(boot[p][key][met], dtype=float)
log("bootstrap done")

# ------------------------------------------------------------------ estimates
BOOT_TXT = ("gene-level bootstrap, {nb} replicates (unit of resampling = gene: genes drawn with replacement from the "
            "828-gene union of the three panels, each panel keeps its drawn genes; CCA refitted with gene-grouped "
            "5-fold CV; PCA bases fixed); 95% CI = estimate +/- 1.96 x bootstrap SD")
estimates, extra = [], {}


def add(name, value, reps, nb, note=""):
    sd = float(np.std(reps, ddof=1))
    estimates.append({"name": name, "value": round(float(value), 4), "ci_low": round(float(value - Z975 * sd), 4),
                      "ci_high": round(float(value + Z975 * sd), 4),
                      "method_of_uncertainty": BOOT_TXT.format(nb=nb) + note})
    extra[name] = {"boot_sd": round(sd, 4), "boot_mean": round(float(np.mean(reps)), 4)}


def stat_vals(p, key, met):
    if p == "panel_mean":
        return (float(np.mean([obs[q][key][met] for q in PANELS])),
                np.mean([boot[q][key][met] for q in PANELS], axis=0))
    return float(obs[p][key][met]), boot[p][key][met]


DIFF_NOTE = "; paired difference on the same genes and bootstrap draws"
for met in ["cv_cca", "top1", "rsa_cos", "rsa_euc20", "insample_cca"]:
    for p in PANELS + ["panel_mean"]:
        if met == "insample_cca" and p != "panel_mean":
            continue
        for a, b in PAIRS:
            v, reps = stat_vals(p, a + b, met)
            add(f"{met}|{a}{b}|{p}", v, reps, N_BOOT)
        vg, rg = stat_vals(p, "MG", met)
        vs, rs_ = stat_vals(p, "MS", met)
        add(f"{met}|diff_MG_minus_MS|{p}", vg - vs, rg - rs_, N_BOOT, DIFF_NOTE)
for var, prs in SENS:
    vals = {}
    for a, b in prs:
        v, reps = stat_vals("panel_mean", f"{var}:{a}{b}", "cv_cca")
        vals[a + b] = (v, reps)
        add(f"sens_{var}|cv_cca|{a}{b}|panel_mean", v, reps, N_BOOT_SENS)
    if "MG" in vals:
        add(f"sens_{var}|cv_cca|diff_MG_minus_MS|panel_mean", vals["MG"][0] - vals["MS"][0],
            vals["MG"][1] - vals["MS"][1], N_BOOT_SENS, DIFF_NOTE)
for a, b in PAIRS:
    v, reps = stat_vals("panel_mean", a + b, "radius20_corr")
    add(f"diag_radius20_spearman|{a}{b}|panel_mean", v, reps, N_BOOT)
for m in "MGS":
    v, reps = stat_vals("panel_mean", "diag_" + m, "euc20_vs_radius_sum")
    add(f"diag_euc20_distance_vs_radius_sum_spearman|{m}|panel_mean", v, reps, N_BOOT)


# permutation p-values and null summaries
def perm_p(o, nl):
    return float((1 + np.sum(nl >= o)) / (1 + len(nl)))


perm = {}
for met in ["cv_cca", "top1", "insample_cca", "rsa_euc20", "rsa_cos"]:
    for a, b in PAIRS:
        key = a + b
        for p in PANELS:
            nl = null[p][key][met]
            perm[f"{met}|{key}|{p}"] = {"obs": round(float(obs[p][key][met]), 4), "null_mean": round(float(nl.mean()), 4),
                                         "null_q95": round(float(np.quantile(nl, 0.95)), 4),
                                         "p": round(perm_p(obs[p][key][met], nl), 4)}
        nl = np.mean([null[q][key][met] for q in PANELS], axis=0)
        o = float(np.mean([obs[q][key][met] for q in PANELS]))
        perm[f"{met}|{key}|panel_mean"] = {"obs": round(o, 4), "null_mean": round(float(nl.mean()), 4),
                                            "null_q95": round(float(np.quantile(nl, 0.95)), 4), "p": round(perm_p(o, nl), 4)}
chance = {p: round(float(obs[p]["MS"]["top1_chance"]), 4) for p in PANELS}

# ------------------------------------------------------------------ pre-specified decision rule
E = {e["name"]: e for e in estimates}
ms_beyond = perm["cv_cca|MS|panel_mean"]["p"] < 0.05 and all(perm[f"cv_cca|MS|{p}"]["p"] < 0.05 for p in PANELS)
dprim = E["cv_cca|diff_MG_minus_MS|panel_mean"]
d_all_pos = all(E[f"cv_cca|diff_MG_minus_MS|{p}"]["value"] > 0 for p in PANELS)
if not ms_beyond:
    verdict = "not aligned with scGPT beyond chance"
elif dprim["ci_low"] > 0 and d_all_pos:
    verdict = "aligned with scGPT but clearly less than with Geneformer"
elif dprim["ci_low"] >= -0.05 and dprim["ci_high"] <= 0.05:
    verdict = "aligned with scGPT about as well as with Geneformer"
else:
    verdict = "inconclusive"

out = {"verdict_by_rule": verdict, "estimates": estimates, "bootstrap_extra": extra, "permutation": perm,
       "top1_chance": chance, "details": details,
       "settings": {"K": K, "K_SENS": list(K_SENS), "NFOLD": NFOLD, "N_SPLITS": N_SPLITS, "N_PERM": N_PERM,
                    "N_PERM_RSA": N_PERM_RSA, "N_BOOT": N_BOOT, "N_BOOT_SENS": N_BOOT_SENS, "SEED": SEED},
       "runtime_s": round(time.time() - T0, 1)}
print(json.dumps(out, indent=1))

#!/usr/bin/env python3
"""
MaxToki-217M gene-embedding geometry vs scGPT whole-human and vs Geneformer V2-316M.

Cross-model alignment following SPEC Phase 4 on the static input token-embedding tables:
H24 (whitened CCA on per-model PCA-20 gene embeddings: mean canonical correlation, top-1 gene
retrieval, pairwise-distance Spearman) and H20 (orthogonal Procrustes top-1 retrieval), on the
three gene panels. CCA/Procrustes statistics are held-out (gene-level 5-fold CV); the SPEC's
in-sample mean canonical correlation is also reported. Chance levels from gene-label permutations.
Uncertainty from gene-level resampling in which PCA, centring and CCA/Procrustes are refitted on
every resample: (a) a with-replacement bootstrap and (b) half-sampling without replacement (no
duplicate genes); each 95% CI uses the larger of the two SDs.

Run from the package root:
    "<CODE_ROOT>/analysis-tasks/bin/python" this_script.py
Prints one JSON object to stdout ("estimates" holds every reported number); progress -> stderr.
Resamples run in parallel (fork) when available; every resample has its own seed, so the output
does not depend on the number of workers.
"""
import os
for _v in ("OPENBLAS_NUM_THREADS", "OMP_NUM_THREADS", "MKL_NUM_THREADS", "VECLIB_MAXIMUM_THREADS"):
    os.environ.setdefault(_v, "1")
import json
import multiprocessing as mp
import sys
import time

import numpy as np
import pandas as pd
from scipy.linalg import eigh as sp_eigh
from scipy.stats import rankdata

# ------------------------------------------------------------------ parameters
D = "data/"
PANELS = ["lung", "immune", "external_lung"]
PAIRS = [("M", "S"), ("M", "G"), ("G", "S")]   # M = MaxToki-217M, G = Geneformer V2-316M, S = scGPT
K = 20                 # PCA components per model and panel (SPEC Phase 0 step 5)
K_SENS = (10, 30)      # PCA-dimension sensitivity
KMAX = max(K_SENS + (K,))
TOPK = (5, 10)         # held-out mean canonical correlation over the top-k canonical variates
NFOLD = 5              # gene-level folds for held-out CCA / Procrustes
N_SPLITS = 5           # fold re-draws averaged for each point estimate
N_PERM = 200           # gene-label permutations, CCA/Procrustes statistics
N_PERM_RSA = 500       # gene-label permutations, distance-correlation statistics
N_BOOT = 400           # with-replacement gene bootstrap replicates
N_HALF = 400           # half-samples without replacement
MARGIN = 0.05          # practical margin on the correlation / proportion scale (SPEC: +/-0.05 tolerance on r)
SEED = 20261001
Z975 = 1.959963984540054
N_WORKERS = max(1, min(8, (os.cpu_count() or 2) - 1))
T0 = time.time()


def log(msg):
    print(f"[{time.time() - T0:7.1f}s] {msg}", file=sys.stderr, flush=True)


# ------------------------------------------------------------------ data
tdM = json.load(open(D + "maxtoki_217m/token_dictionary.json"))
tdG = json.load(open(D + "geneformer_v2_316m/token_dictionary.json"))
voc = json.load(open(D + "scgpt_whole_human/vocab.json"))
es = pd.read_csv(D + "gene_ids/ensembl_symbol.csv")
e2s = dict(zip(es.ensembl_id.astype(str), es.symbol.astype(str)))
panels = {p: pd.read_csv(D + f"panels/{p}.csv").ensembl_id.astype(str).tolist() for p in PANELS}
union = sorted(set().union(*panels.values()))
for g in union:
    assert tdM[g] == tdG[g], g            # MaxToki and Geneformer share token ids
    assert g in e2s and e2s[g] in voc, g  # every panel gene has an scGPT token
tok = np.array([tdM[g] for g in union])
stok = np.array([voc[e2s[g]] for g in union])
assert len(set(stok)) == len(stok)
Mt = np.load(D + "maxtoki_217m/embed_tokens.npy", mmap_mode="r")
Gt = np.load(D + "geneformer_v2_316m/word_embeddings.npy", mmap_mode="r")
St = np.load(D + "scgpt_whole_human/encoder_embedding_weight.npy", mmap_mode="r")
lnp = np.load(D + "scgpt_whole_human/encoder_enc_norm.npz")


def enc_norm(X):
    """scGPT gene-encoder LayerNorm (encoder.enc_norm), applied row-wise."""
    mu = X.mean(1, keepdims=True)
    var = X.var(1, keepdims=True)
    return (X - mu) / np.sqrt(var + float(lnp["eps"])) * lnp["weight"].astype(float) + lnp["bias"].astype(float)


S_RAW = np.asarray(St[stok], dtype=float)
EMB = {"M": np.asarray(Mt[tok], dtype=float), "G": np.asarray(Gt[tok], dtype=float), "S": enc_norm(S_RAW)}
for _m, _X in EMB.items():
    assert np.isfinite(_X).all() and (np.linalg.norm(_X, axis=1) > 0).all(), _m
POS = {g: i for i, g in enumerate(union)}
PIDX = {p: np.array([POS[g] for g in panels[p]]) for p in PANELS}
NU = len(union)
log(f"loaded; union of panels = {NU} genes; panel sizes = {[len(PIDX[p]) for p in PANELS]}")


# ------------------------------------------------------------------ helpers
def pca_from_gram(G, k):
    """Top-k PCA scores of the rows whose (uncentred) Gram matrix is G; rows centred at their own mean.
    Applied to G[loc][:, loc] this is PCA refitted on a resample (bootstrap duplicates included)."""
    Gc = G - G.mean(0)[None, :] - G.mean(1)[:, None] + G.mean()
    n = len(Gc)
    w, V = sp_eigh(Gc, subset_by_index=[n - k, n - 1])
    w, V = w[::-1], V[:, ::-1]
    return V * np.sqrt(np.clip(w, 0, None))


def pca_var_explained(G, k):
    Gc = G - G.mean(0)[None, :] - G.mean(1)[:, None] + G.mean()
    n = len(Gc)
    w = sp_eigh(Gc, subset_by_index=[n - k, n - 1], eigvals_only=True)
    return float(w.sum() / np.trace(Gc))


def isqrt(C, reg=1e-6):
    w, V = np.linalg.eigh(C)
    w = np.clip(w, 0, None) + reg * w.max()
    return (V / np.sqrt(w)) @ V.T


def cca_fit(A, B):
    """Whitened CCA. Returns means, canonical weight matrices and canonical correlations (descending)."""
    ma, mb = A.mean(0), B.mean(0)
    Ac, Bc = A - ma, B - mb
    n = len(A)
    Wa, Wb = isqrt(Ac.T @ Ac / n), isqrt(Bc.T @ Bc / n)
    T = Wa @ (Ac.T @ Bc / n) @ Wb
    w, U = np.linalg.eigh(T @ T.T)
    w, U = w[::-1], U[:, ::-1]
    s = np.sqrt(np.clip(w, 1e-24, None))
    V = (T.T @ U) / s
    return ma, mb, Wa @ U, Wb @ V, np.minimum(s, 1.0)


def make_folds(groups, rng):
    """Gene-level folds; copies of one gene (bootstrap duplicates) always share a fold."""
    ug, inv = np.unique(groups, return_inverse=True)
    f = np.empty(len(ug), int)
    f[rng.permutation(len(ug))] = np.arange(len(ug)) % NFOLD
    return f[inv]


def top1_hits(za, zb, gt):
    """Top-1 cosine retrieval among held-out genes, both directions averaged."""
    za = za / np.linalg.norm(za, axis=1, keepdims=True)
    zb = zb / np.linalg.norm(zb, axis=1, keepdims=True)
    sim = za @ zb.T
    return 0.5 * (np.mean(gt[sim.argmax(1)] == gt) + np.mean(gt[sim.argmax(0)] == gt))


CV_KEYS = ["cv_cca", "cv_cca_top5", "cv_cca_top10", "top1", "procrustes_top1", "top1_chance"]
NULL_CV = CV_KEYS[:-1]


def cv_stats(A, B, folds, groups):
    """Held-out statistics from gene-level K-fold CV: held-out canonical correlations (mean over all
    components, and over the top-k in training order), top-1 retrieval in CCA space (H24), and top-1
    retrieval after orthogonal Procrustes (H20)."""
    R, hits, hits_pro, chance = [], [], [], []
    for k in range(NFOLD):
        te = folds == k
        tr = ~te
        ma, mb, Wa, Wb, s = cca_fit(A[tr], B[tr])
        ua = (A[te] - ma) @ Wa
        ub = (B[te] - mb) @ Wb
        uac, ubc = ua - ua.mean(0), ub - ub.mean(0)
        R.append((uac * ubc).sum(0) / np.sqrt((uac ** 2).sum(0) * (ubc ** 2).sum(0)))
        gt = groups[te]
        hits.append(top1_hits(ua * s, ub * s, gt))      # axes weighted by training canonical correlation
        U_, _, Vt = np.linalg.svd((A[tr] - ma).T @ (B[tr] - mb))
        hits_pro.append(top1_hits((A[te] - ma) @ (U_ @ Vt), B[te] - mb, gt))
        chance.append(1.0 / len(np.unique(gt)))
    r = np.mean(R, 0)
    return dict(zip(CV_KEYS, [float(r.mean()), float(r[:TOPK[0]].mean()), float(r[:TOPK[1]].mean()),
                              float(np.mean(hits)), float(np.mean(hits_pro)), float(np.mean(chance))]))


def rank_matrix(Dm):
    """Symmetric matrix of ranks of the off-diagonal pairwise values (diagonal 0)."""
    n = len(Dm)
    iu = np.triu_indices(n, 1)
    R = np.zeros((n, n))
    R[iu] = rankdata(Dm[iu])
    return R + R.T


def std_offdiag(R):
    n = len(R)
    iu = np.triu_indices(n, 1)
    v = R[iu]
    Z = (R - v.mean()) / v.std()
    np.fill_diagonal(Z, 0.0)
    return Z


def euclid(P):
    sq = (P ** 2).sum(1)
    return np.sqrt(np.clip(sq[:, None] + sq[None] - 2 * P @ P.T, 0, None))


def centred_cos_dist_gram(G, w):
    """Centred-cosine distance from an uncentred Gram matrix, centring at the w-weighted mean (sum w = 1)."""
    Gw = G @ w
    Gc = G - Gw[:, None] - Gw[None, :] + w @ Gw
    d = np.sqrt(np.diag(Gc))
    return 1.0 - Gc / np.outer(d, d)


def weighted_rank_corr(Ra, Rb, C):
    """Pearson correlation of pairwise ranks over gene pairs i != j with pair weight c_i*c_j.
    C: (B, n) gene multiplicities. With C = 1 this is exactly Spearman's rho of the pairwise values."""
    C = np.atleast_2d(C).astype(float)
    sw = C.sum(1) ** 2 - (C ** 2).sum(1)

    def q(Mx):
        return ((C @ Mx) * C).sum(1)

    ea, eb = q(Ra) / sw, q(Rb) / sw
    cov = q(Ra * Rb) / sw - ea * eb
    va = q(Ra * Ra) / sw - ea ** 2
    vb = q(Rb * Rb) / sw - eb ** 2
    return cov / np.sqrt(va * vb)


def weighted_spearman_vec(x, y, c):
    """Pearson correlation of the ranks of per-gene values x, y with gene weights c."""
    rx, ry = rankdata(x), rankdata(y)
    w = np.asarray(c, float) / np.sum(c)
    mx, my = w @ rx, w @ ry
    return float((w @ (rx * ry) - mx * my) / np.sqrt((w @ rx ** 2 - mx ** 2) * (w @ ry ** 2 - my ** 2)))


# ------------------------------------------------------------------ per-panel Gram matrices and representations
GR = {}
for p in PANELS:
    idx = PIDX[p]
    g = {m: EMB[m][idx] @ EMB[m][idx].T for m in "MGS"}
    g["rawS"] = S_RAW[idx] @ S_RAW[idx].T
    for m in "MGS":
        nr = np.sqrt(np.diag(g[m]))
        g[m + "_rn"] = g[m] / np.outer(nr, nr)            # unit-norm rows
    GR[p] = g


def build_scores(Gd, loc):
    """PCA scores for every variant, fitted on the genes in loc (None = the whole panel)."""
    sub = (lambda G: G) if loc is None else (lambda G: G[np.ix_(loc, loc)])
    Pm = {m: pca_from_gram(sub(Gd[m]), KMAX) for m in "MGS"}
    out = {f"k{k}": {m: Pm[m][:, :k] for m in "MGS"} for k in (K,) + K_SENS}
    out["main"] = out[f"k{K}"]
    out["rawS"] = {"M": out["main"]["M"], "G": out["main"]["G"], "S": pca_from_gram(sub(Gd["rawS"]), K)}
    out["rownorm"] = {m: pca_from_gram(sub(Gd[m + "_rn"]), K) for m in "MGS"}
    return out


SENS = [("k10", [("M", "S"), ("M", "G")]), ("k30", [("M", "S"), ("M", "G")]),
        ("rawS", [("M", "S")]), ("rownorm", [("M", "S"), ("M", "G")])]


def geometry_stats(Gd, sc, genes, cnt):
    """Distance-correlation statistics on the genes present (weights = multiplicities):
    centred-cosine RSA on the full embeddings, Euclidean RSA in PCA-20 space, PCA-20 radius diagnostics."""
    w = cnt / cnt.sum()
    Rc = {m: rank_matrix(centred_cos_dist_gram(Gd[m][np.ix_(genes, genes)], w)) for m in "MGS"}
    Re = {m: rank_matrix(euclid(sc[m])) for m in "MGS"}
    rad = {m: np.linalg.norm(sc[m], axis=1) for m in "MGS"}
    out = {}
    for a, b in PAIRS:
        out[a + b] = {"rsa_cos": float(weighted_rank_corr(Rc[a], Rc[b], cnt)[0]),
                      "rsa_euc20": float(weighted_rank_corr(Re[a], Re[b], cnt)[0]),
                      "radius20_corr": weighted_spearman_vec(rad[a], rad[b], cnt)}
    for m in "MGS":
        out["diag_" + m] = {"euc20_vs_radius_sum": float(weighted_rank_corr(
            Re[m], rank_matrix(rad[m][:, None] + rad[m][None]), cnt)[0])}
    return out, Rc, Re


# ------------------------------------------------------------------ observed statistics
REP, obs = {}, {p: {} for p in PANELS}
details = {"n_genes": {p: int(len(PIDX[p])) for p in PANELS}, "n_union": int(NU),
           "n_shared": {"lung&immune": len(set(panels["lung"]) & set(panels["immune"])),
                        "lung&external_lung": len(set(panels["lung"]) & set(panels["external_lung"])),
                        "immune&external_lung": len(set(panels["immune"]) & set(panels["external_lung"])),
                        "all_three": len(set(panels["lung"]) & set(panels["immune"]) & set(panels["external_lung"]))},
           "pca20_var_explained": {}}
gene_rows = np.array(sorted(v for k, v in tdM.items() if k.startswith("ENSG")))
details["table_element_sd_all_gene_rows"] = {"M": round(float(np.asarray(Mt[gene_rows]).std()), 4),
                                             "G": round(float(np.asarray(Gt[gene_rows]).std()), 4),
                                             "M_init_range_config": 0.02}
RANKS = {}
rng_obs = np.random.default_rng([SEED, 1])
for p in PANELS:
    n = len(PIDX[p])
    groups = np.arange(n)
    sc = build_scores(GR[p], None)
    REP[p] = sc
    details["pca20_var_explained"][p] = {m: round(pca_var_explained(GR[p][m], K), 4) for m in "MGS"}
    splits = [make_folds(groups, rng_obs) for _ in range(N_SPLITS)]
    for a, b in PAIRS:
        cvs = [cv_stats(sc["main"][a], sc["main"][b], f, groups) for f in splits]
        obs[p][a + b] = {key: float(np.mean([c[key] for c in cvs])) for key in CV_KEYS}
        obs[p][a + b]["insample_cca"] = float(cca_fit(sc["main"][a], sc["main"][b])[4].mean())
    geo, Rc, Re = geometry_stats(GR[p], sc["main"], groups, np.ones(n))
    for key, v in geo.items():
        obs[p].setdefault(key, {}).update(v)
    RANKS[p] = {"cos": Rc, "euc": Re}
    for var, prs in SENS:
        for a, b in prs:
            obs[p][f"{var}:{a}{b}"] = {"cv_cca": float(np.mean([cv_stats(sc[var][a], sc[var][b], f, groups)["cv_cca"]
                                                                for f in splits]))}
log("observed statistics done")

# ------------------------------------------------------------------ permutation nulls (gene labels of the 2nd model shuffled;
# a row permutation leaves each model's own PCA unchanged)
null = {p: {} for p in PANELS}
rng_perm = np.random.default_rng([SEED, 2])
for p in PANELS:
    n = len(PIDX[p])
    groups = np.arange(n)
    sc = REP[p]["main"]
    Z = {kind: {m: std_offdiag(RANKS[p][kind][m]) for m in "MGS"} for kind in ("cos", "euc")}
    for a, b in PAIRS:
        d = {key: np.empty(N_PERM) for key in NULL_CV + ["insample_cca"]}
        for i in range(N_PERM):
            pi = rng_perm.permutation(n)
            f = make_folds(groups, rng_perm)
            c = cv_stats(sc[a], sc[b][pi], f, groups)
            for key in NULL_CV:
                d[key][i] = c[key]
            d["insample_cca"][i] = cca_fit(sc[a], sc[b][pi])[4].mean()
        re_, rc_ = np.empty(N_PERM_RSA), np.empty(N_PERM_RSA)
        for i in range(N_PERM_RSA):
            pi = rng_perm.permutation(n)
            sub = np.ix_(pi, pi)
            re_[i] = np.sum(Z["euc"][a] * Z["euc"][b][sub]) / (n * (n - 1))
            rc_[i] = np.sum(Z["cos"][a] * Z["cos"][b][sub]) / (n * (n - 1))
        d["rsa_euc20"], d["rsa_cos"] = re_, rc_
        null[p][a + b] = d
    log(f"permutation null done: {p}")

# ------------------------------------------------------------------ gene-level resampling
# Unit of resampling = gene, drawn from the 828-gene union of the panels; each panel keeps the genes it
# received (keeps the dependence created by overlapping panels). In each resample and panel, PCA (every
# variant), centring, CCA and Procrustes are refitted on the drawn genes.
#   "boot": 828 genes with replacement (duplicates share a CV fold); also records the CV statistics
#           with the full-panel PCA held fixed, for comparison only.
#   "half": 414 genes without replacement (no duplicates). For a smooth statistic the SD of the
#           half-sample estimates approximates the SD of the full-sample estimate
#           (half-sampling / delete-n/2 jackknife: var = (r/d) var_sub with r = d).
u2loc = {}
for p in PANELS:
    _m = np.full(NU, -1)
    _m[PIDX[p]] = np.arange(len(PIDX[p]))
    u2loc[p] = _m


def resample_stats(sel, rng, fixed):
    res = {}
    for p in PANELS:
        loc = u2loc[p][sel]
        loc = loc[loc >= 0]
        f = make_folds(loc, rng)
        sc = build_scores(GR[p], loc)
        r = {}
        for a, b in PAIRS:
            A, B = sc["main"][a], sc["main"][b]
            c = cv_stats(A, B, f, loc)
            r[a + b] = {key: c[key] for key in NULL_CV}
            r[a + b]["insample_cca"] = float(cca_fit(A, B)[4].mean())
            if fixed:
                cf = cv_stats(REP[p]["main"][a][loc], REP[p]["main"][b][loc], f, loc)
                r[a + b].update({"fixedpca_" + key: cf[key] for key in NULL_CV})
        genes, first, cnt = np.unique(loc, return_index=True, return_counts=True)
        geo, _, _ = geometry_stats(GR[p], {m: sc["main"][m][first] for m in "MGS"}, genes, cnt.astype(float))
        for key, v in geo.items():
            r.setdefault(key, {}).update(v)
        for var, prs in SENS:
            for a, b in prs:
                r[f"{var}:{a}{b}"] = {"cv_cca": cv_stats(sc[var][a], sc[var][b], f, loc)["cv_cca"]}
        res[p] = r
    return res


def boot_rep(i):
    rng = np.random.default_rng([SEED, 3, i])
    return resample_stats(rng.integers(0, NU, NU), rng, True)


def half_rep(i):
    rng = np.random.default_rng([SEED, 5, i])
    return resample_stats(rng.permutation(NU)[:NU // 2], rng, False)


def run_all(fn, n):
    if N_WORKERS > 1 and "fork" in mp.get_all_start_methods():
        with mp.get_context("fork").Pool(N_WORKERS) as pool:
            return pool.map(fn, range(n), chunksize=5)
    return [fn(i) for i in range(n)]


def collect(reps):
    out = {p: {} for p in PANELS}
    for p in PANELS:
        for key in reps[0][p]:
            out[p][key] = {met: np.array([r[p][key][met] for r in reps]) for met in reps[0][p][key]}
    return out


boot = collect(run_all(boot_rep, N_BOOT))
log("bootstrap done")
half = collect(run_all(half_rep, N_HALF))
log("half-sampling done")


# ------------------------------------------------------------------ estimates
def rs_vals(src, p, key, met):
    if p == "panel_mean":
        return np.mean([src[q][key][met] for q in PANELS], axis=0)
    return src[p][key][met]


def obs_val(p, key, met):
    if p == "panel_mean":
        return float(np.mean([obs[q][key][met] for q in PANELS]))
    return float(obs[p][key][met])


METHOD = (f"gene-level resampling from the 828-gene panel union, PCA/centring/CCA/Procrustes refitted each time: "
          f"{N_BOOT} bootstrap reps (with replacement) and {N_HALF} half-samples (without replacement); "
          f"95% CI = est +/- 1.96 x max(bootstrap SD, half-sample SD)")
estimates, extra = [], {}


def add(name, value, rb, rh, diff=False):
    sb, sh = float(np.std(rb, ddof=1)), float(np.std(rh, ddof=1))
    sd = max(sb, sh)
    estimates.append({"name": name, "value": round(float(value), 4), "ci_low": round(float(value - Z975 * sd), 4),
                      "ci_high": round(float(value + Z975 * sd), 4),
                      "method_of_uncertainty": METHOD + ("; paired difference" if diff else "")})
    q_lo, q_hi = np.quantile(rb, [0.025, 0.975])
    extra[name] = {"sd_boot": round(sb, 4), "sd_half": round(sh, 4), "boot_shift": round(float(np.mean(rb) - value), 4),
                   "half_mean": round(float(np.mean(rh)), 4),
                   "boot_percentile_ci": [round(float(q_lo), 4), round(float(q_hi), 4)],
                   "boot_basic_ci": [round(float(2 * value - q_hi), 4), round(float(2 * value - q_lo), 4)]}


def add_stat(name, p, key, met):
    add(name, obs_val(p, key, met), rs_vals(boot, p, key, met), rs_vals(half, p, key, met))


def add_diff(name, p, key_g, key_s, met):
    add(name, obs_val(p, key_g, met) - obs_val(p, key_s, met),
        rs_vals(boot, p, key_g, met) - rs_vals(boot, p, key_s, met),
        rs_vals(half, p, key_g, met) - rs_vals(half, p, key_s, met), diff=True)


METRICS = ["cv_cca", "cv_cca_top5", "cv_cca_top10", "top1", "procrustes_top1", "insample_cca", "rsa_cos", "rsa_euc20"]
for met in METRICS:
    for p in PANELS + ["panel_mean"]:
        if met == "cv_cca" or p == "panel_mean":
            for a, b in PAIRS:
                add_stat(f"{met}|{a}{b}|{p}", p, a + b, met)
        add_diff(f"{met}|diff_MG_minus_MS|{p}", p, "MG", "MS", met)
for var, prs in SENS:
    for p in PANELS + ["panel_mean"]:
        if p == "panel_mean":
            for a, b in prs:
                add_stat(f"sens_{var}|cv_cca|{a}{b}|panel_mean", p, f"{var}:{a}{b}", "cv_cca")
        kg = f"{var}:MG" if var != "rawS" else "MG"   # scGPT without LayerNorm: compared with the main MG
        add_diff(f"sens_{var}|cv_cca|diff_MG_minus_MS|{p}", p, kg, f"{var}:MS", "cv_cca")
for a, b in PAIRS:
    add_stat(f"diag_radius20_spearman|{a}{b}|panel_mean", "panel_mean", a + b, "radius20_corr")
for m in "MGS":
    add_stat(f"diag_euc20_distance_vs_radius_sum_spearman|{m}|panel_mean", "panel_mean", "diag_" + m,
             "euc20_vs_radius_sum")

# SDs of the held-out differences with the full-panel PCA held fixed (comparison only; not used for CIs)
fixed_pca_sd = {}
for met in NULL_CV:
    for p in PANELS + ["panel_mean"]:
        dfix = rs_vals(boot, p, "MG", "fixedpca_" + met) - rs_vals(boot, p, "MS", "fixedpca_" + met)
        fixed_pca_sd[f"{met}|diff_MG_minus_MS|{p}"] = round(float(np.std(dfix, ddof=1)), 4)

# delete-one-gene jackknife SE of the PCA-free centred-cosine RSA difference (check; ranks/centring fixed)
jack = {}
for p in PANELS:
    n = len(PIDX[p])
    C = np.ones((n, n)) - np.eye(n)
    Rc = RANKS[p]["cos"]
    dj = weighted_rank_corr(Rc["M"], Rc["G"], C) - weighted_rank_corr(Rc["M"], Rc["S"], C)
    jack[f"rsa_cos|diff_MG_minus_MS|{p}"] = round(float(np.sqrt((n - 1) / n * np.sum((dj - dj.mean()) ** 2))), 4)
djm = []
for p in PANELS:
    Cu = np.ones((NU, len(PIDX[p])))
    Cu[PIDX[p], np.arange(len(PIDX[p]))] = 0.0
    Rc = RANKS[p]["cos"]
    djm.append(weighted_rank_corr(Rc["M"], Rc["G"], Cu) - weighted_rank_corr(Rc["M"], Rc["S"], Cu))
djm = np.mean(djm, axis=0)
jack["rsa_cos|diff_MG_minus_MS|panel_mean"] = round(float(np.sqrt((NU - 1) / NU * np.sum((djm - djm.mean()) ** 2))), 4)


# permutation p-values and null summaries
def perm_p(o, nl):
    return float((1 + np.sum(nl >= o)) / (1 + len(nl)))


perm = {}
for met in NULL_CV + ["insample_cca", "rsa_euc20", "rsa_cos"]:
    for a, b in PAIRS:
        key = a + b
        for p in PANELS:
            nl = null[p][key][met]
            perm[f"{met}|{key}|{p}"] = {"obs": round(float(obs[p][key][met]), 4), "null_mean": round(float(nl.mean()), 4),
                                         "null_q95": round(float(np.quantile(nl, 0.95)), 4),
                                         "p": round(perm_p(obs[p][key][met], nl), 4)}
        nl = np.mean([null[q][key][met] for q in PANELS], axis=0)
        o = float(np.mean([obs[q][key][met] for q in PANELS]))
        perm[f"{met}|{key}|panel_mean"] = {"obs": round(o, 4), "null_mean": round(float(nl.mean()), 4),
                                            "null_q95": round(float(np.quantile(nl, 0.95)), 4), "p": round(perm_p(o, nl), 4)}
chance = {p: round(float(obs[p]["MS"]["top1_chance"]), 4) for p in PANELS}

# ------------------------------------------------------------------ per-metric classification (post hoc judgement aid)
# Margin rule on D = MG - MS and its 95% CI (MARGIN = 0.05):
#   "gap > margin"        CI entirely above +MARGIN
#   "equivalent"          CI entirely inside (-MARGIN, +MARGIN)
#   "gap > 0, size open"  CI entirely above 0 but not entirely above +MARGIN
#   "reversed"            CI entirely below 0
#   "undetermined"        otherwise
# This rule was written after the point estimates had been seen. The overall verdict is a judgement
# across these rows and is not computed by this script.
E = {e["name"]: e for e in estimates}


def classify(e):
    lo, hi = e["ci_low"], e["ci_high"]
    if lo > MARGIN:
        return "gap > margin"
    if lo > -MARGIN and hi < MARGIN:
        return "equivalent"
    if lo > 0:
        return "gap > 0, size open"
    if hi < 0:
        return "reversed"
    return "undetermined"


classification = {}
for met in METRICS:
    e = E[f"{met}|diff_MG_minus_MS|panel_mean"]
    classification[met] = {"diff": e["value"], "ci": [e["ci_low"], e["ci_high"]], "class": classify(e),
                           "per_panel": {p: [E[f"{met}|diff_MG_minus_MS|{p}"]["value"],
                                             classify(E[f"{met}|diff_MG_minus_MS|{p}"])] for p in PANELS},
                           "ratio_MS_over_MG": round(obs_val("panel_mean", "MS", met) / obs_val("panel_mean", "MG", met), 3)}
for var, _ in SENS:
    e = E[f"sens_{var}|cv_cca|diff_MG_minus_MS|panel_mean"]
    classification[f"sens_{var}|cv_cca"] = {
        "diff": e["value"], "ci": [e["ci_low"], e["ci_high"]], "class": classify(e),
        "per_panel": {p: [E[f"sens_{var}|cv_cca|diff_MG_minus_MS|{p}"]["value"],
                          classify(E[f"sens_{var}|cv_cca|diff_MG_minus_MS|{p}"])] for p in PANELS}}
ms_beyond_chance = {met: perm[f"{met}|MS|panel_mean"]["p"] < 0.05 and all(perm[f"{met}|MS|{p}"]["p"] < 0.05 for p in PANELS)
                    for met in NULL_CV + ["insample_cca", "rsa_cos", "rsa_euc20"]}

out = {"estimates": estimates, "per_metric_classification": classification, "ms_beyond_chance": ms_beyond_chance,
       "resampling_extra": extra, "fixed_pca_bootstrap_sd": fixed_pca_sd, "jackknife_se": jack,
       "permutation": perm, "top1_chance": chance, "details": details,
       "settings": {"K": K, "K_SENS": list(K_SENS), "TOPK": list(TOPK), "NFOLD": NFOLD, "N_SPLITS": N_SPLITS,
                    "N_PERM": N_PERM, "N_PERM_RSA": N_PERM_RSA, "N_BOOT": N_BOOT, "N_HALF": N_HALF,
                    "MARGIN": MARGIN, "SEED": SEED},
       "runtime_s": round(time.time() - T0, 1)}
print(json.dumps(out, indent=1))

#!/usr/bin/env python
"""Is MaxToki-217M's gene-embedding geometry aligned with scGPT's, and how does it compare with its
alignment to Geneformer V2-316M?  H24-style whitened CCA on PCA-20 token embeddings, evaluated
out-of-sample, plus fit-free centred-cosine RSA; gene-correspondence permutation nulls; gene bootstrap.
Run from the package root:  python analysis.py   -> prints every reported estimate as JSON (~7 min, CPU)."""
import json, numpy as np, pandas as pd
from scipy.stats import rankdata, combine_pvalues
from scipy.spatial.distance import pdist, squareform

SEED = 20261001; K = 20; NFOLD = 5; NSPLIT = 10; NPERM = 500; NBOOT = 400
D = 'data/'
# ---------------- load tables, dictionaries, gene mapping ----------------
M = np.load(D + 'maxtoki_217m/embed_tokens.npy')
G = np.load(D + 'geneformer_v2_316m/word_embeddings.npy')
S = np.load(D + 'scgpt_whole_human/encoder_embedding_weight.npy')
LN = np.load(D + 'scgpt_whole_human/encoder_enc_norm.npz')
mt = json.load(open(D + 'maxtoki_217m/token_dictionary.json'))
gf = json.load(open(D + 'geneformer_v2_316m/token_dictionary.json'))
sv = json.load(open(D + 'scgpt_whole_human/vocab.json'))
es = pd.read_csv(D + 'gene_ids/ensembl_symbol.csv'); e2s = dict(zip(es.ensembl_id, es.symbol))
PAN = ['lung', 'immune', 'external_lung']
panels = {p: pd.read_csv(D + f'panels/{p}.csv').ensembl_id.tolist() for p in PAN}
union = sorted(set().union(*panels.values())); uidx = {g: i for i, g in enumerate(union)}
PIDX = {p: np.array([uidx[g] for g in panels[p]]) for p in PAN}
assert all(g in mt and g in gf and e2s.get(g) in sv for g in union)      # every panel gene maps in all 3 vocabularies
assert all(mt[g] == gf[g] for g in union)                                  # MaxToki and Geneformer share token ids

def layernorm(X):  # scGPT gene encoder output = enc_norm(embedding(token))
    mu = X.mean(1, keepdims=True); var = X.var(1, keepdims=True)
    return (X - mu) / np.sqrt(var + float(LN['eps'])) * LN['weight'] + LN['bias']

Xs_raw = S[[sv[e2s[g]] for g in union]].astype(np.float64)
BASE = {'MaxToki': M[[mt[g] for g in union]].astype(np.float64),
        'Geneformer': G[[gf[g] for g in union]].astype(np.float64),
        'scGPT': layernorm(Xs_raw)}
PAIRS = [('MaxToki', 'scGPT'), ('MaxToki', 'Geneformer'), ('Geneformer', 'scGPT')]
PN = {PAIRS[0]: 'MaxToki_scGPT', PAIRS[1]: 'MaxToki_Geneformer', PAIRS[2]: 'Geneformer_scGPT'}
METRICS = ['cv_canonical_r', 'cv_top1_retrieval', 'cosine_rsa', 'euclidean_rsa', 'insample_cca_r']

# ---------------- building blocks ----------------
def pca_scores(GR, d, u, k):
    """PCA basis fitted on the UNIQUE genes u (Gram-matrix form); scores returned for the rows d (may repeat)."""
    Kuu = GR[np.ix_(u, u)]; Kdu = GR[np.ix_(d, u)]
    cm = Kuu.mean(0); gm = Kuu.mean()
    Cuu = Kuu - cm[None, :] - cm[:, None] + gm
    w, V = np.linalg.eigh(Cuu); o = np.argsort(w)[::-1][:k]; w = np.maximum(w[o], 1e-12); V = V[:, o]
    Cdu = Kdu - Kdu.mean(1)[:, None] - cm[None, :] + gm
    return Cdu @ V / np.sqrt(w)

def fit_cca(X, Y):  # whitened CCA via SVD of the two orthonormal bases
    mx = X.mean(0); my = Y.mean(0)
    Ux, sx, Vx = np.linalg.svd(X - mx, full_matrices=False); Uy, sy, Vy = np.linalg.svd(Y - my, full_matrices=False)
    A, r, Bt = np.linalg.svd(Ux.T @ Uy)
    return mx, my, (Vx.T / sx) @ A, (Vy.T / sy) @ Bt.T, r

def cv_eval(X, Y, gid, foldof):
    """Fit CCA on training genes; on held-out genes: mean canonical correlation (all K comps) and top-1 retrieval."""
    rs, t1 = [], []
    for f in range(NFOLD):
        te = np.where(foldof == f)[0]; tr = np.where(foldof != f)[0]
        mx, my, Wx, Wy, _ = fit_cca(X[tr], Y[tr])
        a = (X[te] - mx) @ Wx; b = (Y[te] - my) @ Wy
        ac = a - a.mean(0); bc = b - b.mean(0)
        rs.append(np.mean((ac * bc).sum(0) / np.sqrt((ac ** 2).sum(0) * (bc ** 2).sum(0))))
        an = a / np.linalg.norm(a, axis=1, keepdims=True); bn = b / np.linalg.norm(b, axis=1, keepdims=True)
        sim = an @ bn.T; g = gid[te]
        t1.append(0.5 * ((g[sim.argmax(1)] == g).mean() + (g[sim.argmax(0)] == g).mean()))
    return float(np.mean(rs)), float(np.mean(t1))

def folds_for(gid, rng):  # folds assigned per gene, so bootstrap copies of a gene stay together
    ug = np.unique(gid); fa = rng.permutation(len(ug)) % NFOLD
    return fa[np.searchsorted(ug, gid)]

def rank_vec(d):
    r = rankdata(d); r = r - r.mean(); return r / np.sqrt((r ** 2).sum())

def panel_eval(GRAMS, d, rng, nsplit, k=K, keep=False):
    u = np.unique(d)
    P = {m: pca_scores(GRAMS[m], d, u, k) for m in GRAMS}
    n = len(d); iu = np.triu_indices(n, 1); mask = d[iu[0]] != d[iu[1]]   # drop pairs of copies of one gene
    Rc = {m: rank_vec(pdist(P[m], 'cosine')[mask]) for m in P}
    Re = {m: rank_vec(pdist(P[m])[mask]) for m in P}
    splits = [folds_for(d, rng) for _ in range(nsplit)]
    out = {}
    for a, b in PAIRS:
        cv = np.mean([cv_eval(P[a], P[b], d, f) for f in splits], axis=0)
        out[(a, b)] = {'cv_canonical_r': cv[0], 'cv_top1_retrieval': cv[1], 'cosine_rsa': float(Rc[a] @ Rc[b]),
                       'euclidean_rsa': float(Re[a] @ Re[b]), 'insample_cca_r': float(fit_cca(P[a], P[b])[4].mean())}
    return (out, P, Rc, splits) if keep else out

def stat(rec, p, pair, m):
    return float(np.mean([rec[q][pair][m] for q in PAN])) if p == 'pooled' else rec[p][pair][m]

EST = []
def rnd(v): return None if v is None else float(f'{float(v):.4g}')
def add(name, value, lo=None, hi=None, how=''):
    EST.append({'name': name, 'value': rnd(value), 'ci_low': rnd(lo), 'ci_high': rnd(hi), 'method_of_uncertainty': how})

GRAM = {m: X @ X.T for m, X in BASE.items()}
rng = np.random.default_rng(SEED)

# ---------------- observed values + permutation null (shuffle gene correspondence) ----------------
obs, pv, zs, nullmean = {}, {}, {}, {}
for p in PAN:
    d = PIDX[p]; n = len(d); iu = np.triu_indices(n, 1)
    o, P, Rc, splits = panel_eval(GRAM, d, rng, NSPLIT, keep=True); obs[p] = o
    Rsq = {m: squareform(Rc[m]) for m in Rc}
    for a, b in PAIRS:
        nul = []
        for _ in range(NPERM):
            pi = rng.permutation(n); Yp = P[b][pi]
            cvr, t1 = cv_eval(P[a], Yp, d, splits[0])
            nul.append([cvr, t1, float(Rc[a] @ Rsq[b][np.ix_(pi, pi)][iu]), float(fit_cca(P[a], Yp)[4].mean())])
        nul = np.array(nul)
        for j, m in enumerate(['cv_canonical_r', 'cv_top1_retrieval', 'cosine_rsa', 'insample_cca_r']):
            pv[(p, a, b, m)] = (1 + (nul[:, j] >= o[(a, b)][m]).sum()) / (1 + NPERM)
            zs[(p, a, b, m)] = (o[(a, b)][m] - nul[:, j].mean()) / nul[:, j].std()
            nullmean[(p, a, b, m)] = nul[:, j].mean()

# ---------------- gene bootstrap ----------------
# unit = gene: resample the 828-gene union with replacement; each panel keeps the drawn genes that belong to it.
# PCA bases are refitted on the unique drawn genes (refitting on duplicated rows creates gene-specific variance
# spikes that are shared across models and spuriously inflate alignment), CV folds are grouped by gene,
# and RSA ignores pairs of copies.  CI = estimate +/- 1.96 * bootstrap SE (normal approximation), because
# resampling shifts the CV statistics (fewer unique genes per fold) and percentile intervals would be off-centre.
boot = []
for bi in range(NBOOT):
    draw = rng.integers(0, len(union), len(union))
    boot.append({p: panel_eval(GRAM, draw[np.isin(draw, PIDX[p])], rng, 1) for p in PAN})

BH = f'95% CI = estimate +/- 1.96 x SE from a gene bootstrap (unit = gene; {NBOOT} resamples of the 828-gene panel union; PCA refit on unique drawn genes; gene-grouped 5-fold CV)'
def ci(v, bs): s = np.std(bs, ddof=1); return v - 1.96 * s, v + 1.96 * s
for m in METRICS:
    for pair in PAIRS:
        for p in PAN + ['pooled']:
            v = stat(obs, p, pair, m)
            add(f'{m}__{PN[pair]}__{p}', v, *ci(v, [stat(r, p, pair, m) for r in boot]),
                BH + ('; NOTE in-sample CCA r is biased upward (permutation-null mean ~0.20)' if m == 'insample_cca_r' else ''))
    for p in PAN + ['pooled']:
        v = stat(obs, p, PAIRS[1], m) - stat(obs, p, PAIRS[0], m)
        add(f'diff_MaxTokiGeneformer_minus_MaxTokiscGPT__{m}__{p}', v,
            *ci(v, [stat(r, p, PAIRS[1], m) - stat(r, p, PAIRS[0], m) for r in boot]), 'paired (same resampled genes) ' + BH)
chance = float(np.mean([nullmean[(p, 'MaxToki', 'scGPT', 'cv_top1_retrieval')] for p in PAN]))
for m, c in [('cv_canonical_r', 0.0), ('cosine_rsa', 0.0), ('cv_top1_retrieval', chance)]:
    f = lambda rec: (stat(rec, 'pooled', PAIRS[0], m) - c) / (stat(rec, 'pooled', PAIRS[1], m) - c)
    v = f(obs)
    add(f'ratio_MaxTokiscGPT_over_MaxTokiGeneformer__{m}__pooled', v, *ci(v, [f(r) for r in boot]),
        'paired ' + BH + ('; retrieval ratio uses excess over permutation chance level' if c else ''))
for pair in PAIRS[:2]:
    for p in PAN:
        add(f'perm_null_mean__insample_cca_r__{PN[pair]}__{p}', nullmean[(p, *pair, 'insample_cca_r')], None, None,
            f'mean of {NPERM} gene-correspondence permutations (chance level of in-sample CCA r); no CI')

PH = f'one-sided permutation p, {NPERM} shuffles of gene correspondence within panel (floor {1/(NPERM+1):.4f}); no CI'
for pair in PAIRS[:2]:
    for m in ['cv_canonical_r', 'cv_top1_retrieval', 'cosine_rsa']:
        ps = [pv[(p, *pair, m)] for p in PAN]
        for p in PAN:
            add(f'perm_p__{m}__{PN[pair]}__{p}', pv[(p, *pair, m)], None, None, PH)
            add(f'perm_z__{m}__{PN[pair]}__{p}', zs[(p, *pair, m)], None, None, 'z = (observed - permutation-null mean) / null SD; no CI')
        add(f'fisher_combined_p__{m}__{PN[pair]}', combine_pvalues(ps, method='fisher')[1], None, None,
            'Fisher combination of the 3 panel permutation p-values (bounded by the p floor; panels share some genes); no CI')

# ---------------- sensitivity analyses (point estimates, mean over the 3 panels) ----------------
def rown(X): return X / np.linalg.norm(X, axis=1, keepdims=True)
VAR = {'scgpt_no_layernorm': ({**BASE, 'scGPT': Xs_raw}, K), 'pca10': (BASE, 10), 'pca50': (BASE, 50),
       'row_l2_normalised': ({m: rown(X) for m, X in BASE.items()}, K)}
for vn, (E, k) in VAR.items():
    GR = {m: X @ X.T for m, X in E.items()}
    res = {p: panel_eval(GR, PIDX[p], rng, NSPLIT, k) for p in PAN}
    for m in ['cv_canonical_r', 'cv_top1_retrieval', 'cosine_rsa', 'euclidean_rsa']:
        add(f'sens_{vn}__{m}__MaxToki_scGPT__pooled', stat(res, 'pooled', PAIRS[0], m), None, None, 'sensitivity point estimate; no CI')
        add(f'sens_{vn}__{m}__MaxToki_Geneformer__pooled', stat(res, 'pooled', PAIRS[1], m), None, None, 'sensitivity point estimate; no CI')
fd = {}
for p in PAN:
    Xc = {m: X[PIDX[p]] - X[PIDX[p]].mean(0) for m, X in BASE.items()}
    Rcos = {m: rank_vec(pdist(Xc[m], 'cosine')) for m in Xc}
    Reuc = {m: rank_vec(pdist(Xc[m])) for m in Xc}
    fd[p] = {pair: {'cos': float(Rcos[pair[0]] @ Rcos[pair[1]]), 'euc': float(Reuc[pair[0]] @ Reuc[pair[1]])} for pair in PAIRS}
for pair in PAIRS:
    add(f'sens_fulldim_cosine_rsa__{PN[pair]}__pooled', stat(fd, 'pooled', pair, 'cos'), None, None,
        'sensitivity point estimate (no PCA; centred cosine on full embeddings); no CI')
    add(f'sens_fulldim_euclidean_rsa__{PN[pair]}__pooled', stat(fd, 'pooled', pair, 'euc'), None, None,
        'sensitivity point estimate (no PCA; Euclidean on full centred embeddings); no CI')
print(json.dumps(EST, indent=1))

points.evidence:
Immune panel, 10 PCs (my recomputation; per panel, MaxToki-scGPT vs MaxToki-Geneformer):
- in-sample CCA r: 0.349 vs 0.345, so MaxToki-scGPT is higher;
- CV canonical r: 0.290 vs 0.297, a gap of 0.007 against 0.065 at PCA-20;
- top-1 retrieval: 0.076 vs 0.096.
The report's sensitivity table shows only pooled values (for example, 10 PCs: 0.305 vs 0.350).

points.description:
The bootstrap CIs describe a different estimator from the one reported:
- each replicate uses a single CV split and about 63% unique genes;
- the point estimate averages 10 splits over the full panel;
- B = 400, and the normal approximation (estimate ± 1.96 SE) is used.
The resulting CIs are probably conservative, but they are not calibrated for the reported statistic, and the analyst notes that the bootstrap distribution is shifted.

results.analysis_script:
#!/usr/bin/env python
"""Is MaxToki-217M's gene-embedding geometry aligned with scGPT's, and how does that alignment compare with its
alignment to Geneformer V2-316M?  SPEC Phase 4 (H24): whitened CCA between panel PCA-20 token embeddings, scored
out of sample (cross-validated canonical r, held-out top-1 retrieval), plus fit-free representational similarity
(Spearman of pairwise distances: centred cosine, Euclidean, and Euclidean in the whitened 20-component canonical
space).  Gene-correspondence permutation nulls; gene bootstrap (unit = gene) for every interval; sensitivity
variants with bootstrap intervals.
Run from the package root:  python analysis.py   -> prints every reported estimate as JSON.
Runtime: a few minutes on CPU; uses up to 8 worker processes (fork start method; serial fallback)."""
import os
for _v in ('OPENBLAS_NUM_THREADS', 'OMP_NUM_THREADS', 'MKL_NUM_THREADS', 'VECLIB_MAXIMUM_THREADS'):
    os.environ.setdefault(_v, '1')
import json, multiprocessing as mp
import numpy as np, pandas as pd
from scipy.linalg import eigh
from scipy.stats import combine_pvalues, spearmanr
from scipy.spatial.distance import pdist, squareform

SEED = 20261001; K = 20; KMAX = 50; NFOLD = 5; NSPLIT = 10; NPERM = 500
NBOOT = 400; NBOOT_SENS = 200; NBOOT_VOCAB = 200; NSIM = 20
NPROC = max(1, min(8, (os.cpu_count() or 2) - 1))
D = 'data/'

# ---------------- load tables, dictionaries, gene mapping; integrity checks ----------------
def load_json(path):  # refuses duplicate keys
    def hook(pairs):
        assert len({k for k, _ in pairs}) == len(pairs), f'duplicate key in {path}'
        return dict(pairs)
    with open(path) as fh:
        return json.load(fh, object_pairs_hook=hook)

M = np.load(D + 'maxtoki_217m/embed_tokens.npy')
G = np.load(D + 'geneformer_v2_316m/word_embeddings.npy')
S = np.load(D + 'scgpt_whole_human/encoder_embedding_weight.npy')
LN = np.load(D + 'scgpt_whole_human/encoder_enc_norm.npz')
mt = load_json(D + 'maxtoki_217m/token_dictionary.json')
gf = load_json(D + 'geneformer_v2_316m/token_dictionary.json')
sv = load_json(D + 'scgpt_whole_human/vocab.json')
es = pd.read_csv(D + 'gene_ids/ensembl_symbol.csv')
assert es.ensembl_id.is_unique and es.symbol.is_unique
e2s = dict(zip(es.ensembl_id, es.symbol))
PAN = ['lung', 'immune', 'external_lung']
panels = {p: pd.read_csv(D + f'panels/{p}.csv').ensembl_id.tolist() for p in PAN}
assert all(len(set(v)) == len(v) for v in panels.values())
union = sorted(set().union(*panels.values())); uidx = {g: i for i, g in enumerate(union)}
PIDX = {p: np.sort([uidx[g] for g in panels[p]]) for p in PAN}
GENES = sorted(g for g in gf if g.startswith('ENSG'))
assert set(GENES) == {g for g in mt if g.startswith('ENSG')} and all(mt[g] == gf[g] for g in GENES)  # shared ids
assert all(g in mt and g in gf and e2s.get(g) in sv for g in union)   # every panel gene maps (exact-case symbol)
assert all(np.isfinite(X).all() for X in (M, G, S))

def layernorm(X):  # scGPT gene-encoder output = enc_norm(embedding(token))
    mu = X.mean(1, keepdims=True); var = X.var(1, keepdims=True)
    return (X - mu) / np.sqrt(var + float(LN['eps'])) * LN['weight'] + LN['bias']

Xs_raw = S[[sv[e2s[g]] for g in union]].astype(np.float64)
BASE = {'MaxToki': M[[mt[g] for g in union]].astype(np.float64),
        'Geneformer': G[[gf[g] for g in union]].astype(np.float64),
        'scGPT': layernorm(Xs_raw)}
assert all(len(np.unique(X, axis=0)) == len(union) for X in BASE.values())   # no duplicated rows
PAIRS = [('MaxToki', 'scGPT'), ('MaxToki', 'Geneformer'), ('Geneformer', 'scGPT')]
MS, MG, GS = PAIRS
PN = {MS: 'MaxToki_scGPT', MG: 'MaxToki_Geneformer', GS: 'Geneformer_scGPT'}
RSA = ['cosine_rsa', 'euclidean_rsa', 'canonical_space_rsa']
METRICS = ['cv_canonical_r', 'cv_top1_retrieval'] + RSA + ['insample_cca_r']
NORM = {m: np.linalg.norm(X, axis=1) for m, X in BASE.items()}
NORMCOV = np.log(np.column_stack([NORM['MaxToki'], NORM['Geneformer'], NORM['scGPT'], np.linalg.norm(Xs_raw, axis=1)]))
def rown(X): return X / np.linalg.norm(X, axis=1, keepdims=True)
GRAM = {m: X @ X.T for m, X in BASE.items()}
GRAM_SCGPT_RAW = Xs_raw @ Xs_raw.T
GRAM_L2 = {m: rown(X) @ rown(X).T for m, X in BASE.items()}

# ---------------- building blocks ----------------
def wrank(x, w):
    """Average ranks of x when element i occurs w[i] times, centred and scaled so that the dot product of two such
    vectors is the Spearman correlation over the expanded set (exact for bootstrap copies; w = 1 gives plain ranks)."""
    o = np.argsort(x); cw = np.cumsum(w[o]); r = np.empty(len(x)); r[o] = cw - (w[o] - 1) / 2
    r = (r - (w * r).sum() / w.sum()) * np.sqrt(w)
    return r / np.sqrt((r ** 2).sum())

def pca_basis(GR, u, kmax, C=None):
    """PCA of the unique genes u (Gram-matrix form): top-kmax eigenvectors/eigenvalues and total variance.
    Per-gene covariates C, if given, are regressed out (with the intercept) before the PCA."""
    Kuu = GR[np.ix_(u, u)]; n = len(u)
    Q = np.linalg.qr(np.ones((n, 1)) if C is None else np.column_stack([np.ones(n), C[u]]))[0]
    Kc = Kuu - Q @ (Q.T @ Kuu); Kc = Kc - (Kc @ Q) @ Q.T; Kc = (Kc + Kc.T) / 2
    w, V = eigh(Kc, subset_by_index=[n - kmax, n - 1])
    return V[:, ::-1], np.maximum(w[::-1], 1e-12), float(np.trace(Kc))

def fit_cca(X, Y):  # whitened CCA via SVD of the two orthonormal bases
    mx = X.mean(0); my = Y.mean(0)
    Ux, sx, Vx = np.linalg.svd(X - mx, full_matrices=False); Uy, sy, Vy = np.linalg.svd(Y - my, full_matrices=False)
    A, r, Bt = np.linalg.svd(Ux.T @ Uy)
    return mx, my, (Vx.T / sx) @ A, (Vy.T / sy) @ Bt.T, r

def cv_eval(X, Y, gid, foldof):
    """Fit CCA on training genes; on held-out genes: mean canonical correlation over all components, top-1
    retrieval (cosine in canonical space, both directions) and its exact chance level for this fold composition."""
    rs, t1, ch = [], [], []
    for f in range(NFOLD):
        te = foldof == f; tr = ~te
        mx, my, Wx, Wy, _ = fit_cca(X[tr], Y[tr])
        a = (X[te] - mx) @ Wx; b = (Y[te] - my) @ Wy
        ac = a - a.mean(0); bc = b - b.mean(0)
        rs.append(np.mean((ac * bc).sum(0) / np.sqrt((ac ** 2).sum(0) * (bc ** 2).sum(0))))
        an = a / np.linalg.norm(a, axis=1, keepdims=True); bn = b / np.linalg.norm(b, axis=1, keepdims=True)
        sim = an @ bn.T; g = gid[te]
        t1.append(0.5 * ((g[sim.argmax(1)] == g).mean() + (g[sim.argmax(0)] == g).mean()))
        c = np.unique(g, return_counts=True)[1]; ch.append((c ** 2).sum() / len(g) ** 2)
    return float(np.mean(rs)), float(np.mean(t1)), float(np.mean(ch))

def folds_for(gid, rng):  # folds assigned per gene, so bootstrap copies of a gene stay together
    ug = np.unique(gid); fa = rng.permutation(len(ug)) % NFOLD
    return fa[np.searchsorted(ug, gid)]

def panel_metrics(Bs, k, d, rng, nsplit, extra=False):
    """Alignment metrics for one panel from per-model PCA bases Bs (fitted on the unique genes of d).
    d = sorted union indices of the panel genes (bootstrap: with repeats).  RSA uses pairs of distinct genes,
    weighted by their copy numbers (pairs of copies of one gene are ignored)."""
    u, inv, cnt = np.unique(d, return_inverse=True, return_counts=True)
    iu = np.triu_indices(len(u), 1); w = cnt[iu[0]] * cnt[iu[1]]
    Pu = {m: V[:, :k] * np.sqrt(ev[:k]) for m, (V, ev, tot) in Bs.items()}        # PC scores
    R = {'cosine_rsa': {m: wrank(pdist(Pu[m], 'cosine'), w) for m in Pu},       # centred cosine (PCA is centred)
         'euclidean_rsa': {m: wrank(pdist(Pu[m]), w) for m in Pu}}
    out = {}
    if extra:
        # Euclidean distance in the whitened canonical space of a 20-component CCA = Euclidean on whitened PC scores
        R['canonical_space_rsa'] = {m: wrank(pdist(Bs[m][0][:, :k]), w) for m in Pu}
        rad = {m: (Pu[m] ** 2).sum(1) for m in Pu}                                  # squared distance from centre
        out['var_frac'] = {m: float(ev[:k].sum() / tot) for m, (V, ev, tot) in Bs.items()}
        out['radial_share'] = {m: float(R['euclidean_rsa'][m] @ wrank(rad[m][iu[0]] + rad[m][iu[1]], w)) for m in Pu}
    P = {m: Pu[m][inv] for m in Pu}
    splits = [folds_for(d, rng) for _ in range(nsplit)]
    for a, b in PAIRS:
        cv = np.mean([cv_eval(P[a], P[b], d, f) for f in splits], axis=0)
        o = {'cv_canonical_r': cv[0], 'cv_top1_retrieval': cv[1], 'cv_top1_chance': cv[2],
             'insample_cca_r': float(fit_cca(P[a], P[b])[4].mean())}
        for rn in R: o[rn] = float(R[rn][a] @ R[rn][b])
        if extra: o['radial_agreement'] = float(spearmanr(rad[a][inv], rad[b][inv])[0])
        out[(a, b)] = o
    return out, P, R, splits

def fulldim_rsa(d):  # no PCA: centred cosine and Euclidean distances on the full centred embeddings
    u, cnt = np.unique(d, return_counts=True); iu = np.triu_indices(len(u), 1); w = cnt[iu[0]] * cnt[iu[1]]
    R = {}
    for m, GR in GRAM.items():
        Kuu = GR[np.ix_(u, u)]; cm = Kuu.mean(0); Kc = Kuu - cm[None, :] - cm[:, None] + Kuu.mean()
        dg = np.diag(Kc); kij = Kc[iu]; di = dg[iu[0]]; dj = dg[iu[1]]
        R[m] = (wrank(1 - kij / np.sqrt(di * dj), w), wrank(di + dj - 2 * kij, w))
    return {pr: {'cosine_rsa': float(R[pr[0]][0] @ R[pr[1]][0]),
                 'euclidean_rsa': float(R[pr[0]][1] @ R[pr[1]][1])} for pr in PAIRS}

VARIANTS = ['scgpt_no_layernorm', 'pca10', 'pca50', 'row_l2_normalised', 'norm_residualised']
def eval_all(d, rng, nsplit, variants=True):
    u = np.unique(d)
    B0 = {m: pca_basis(GRAM[m], u, KMAX) for m in GRAM}          # one top-50 basis serves PCA-10/20/50
    base, P, R, splits = panel_metrics(B0, K, d, rng, nsplit, extra=True)
    r = {'base': base}
    if variants:
        r['scgpt_no_layernorm'] = panel_metrics({**B0, 'scGPT': pca_basis(GRAM_SCGPT_RAW, u, K)}, K, d, rng, nsplit)[0]
        r['pca10'] = panel_metrics(B0, 10, d, rng, nsplit)[0]
        r['pca50'] = panel_metrics(B0, 50, d, rng, nsplit)[0]
        r['row_l2_normalised'] = panel_metrics({m: pca_basis(GRAM_L2[m], u, K) for m in GRAM_L2}, K, d, rng, nsplit)[0]
        # log row norms of all three models (and raw scGPT) regressed out of every model before PCA
        r['norm_residualised'] = panel_metrics({m: pca_basis(GRAM[m], u, K, NORMCOV) for m in GRAM}, K, d, rng, nsplit)[0]
        r['fulldim'] = fulldim_rsa(d)
    r['norm_rho'] = {pr: float(spearmanr(NORM[pr[0]][d], NORM[pr[1]][d])[0]) for pr in PAIRS}
    return r, (P, R, splits)

def one_boot(job):
    # unit = gene: resample the 828-gene union with replacement; each panel keeps the drawn genes that belong to it
    seed, variants = job
    rng = np.random.default_rng(seed); draw = np.sort(rng.integers(0, len(union), len(union)))
    return {p: eval_all(draw[np.isin(draw, PIDX[p])], rng, 1, variants)[0] for p in PAN}

def one_perm(job):
    # null: shuffle gene correspondence between the two models; CV statistics use the SAME NSPLIT fold splits
    # as the observed values, so observed and null statistics are commensurate
    p, pair, seed = job; a, b = pair
    P, R, splits = OBSKEEP[p]; d = PIDX[p]; n = len(d); iu = np.triu_indices(n, 1)
    Rsq = {rn: squareform(R[rn][b], checks=False) for rn in RSA}
    rng = np.random.default_rng(seed); nul = []
    for _ in range(NPERM):
        pi = rng.permutation(n); Yp = P[b][pi]
        cv = np.mean([cv_eval(P[a], Yp, d, f) for f in splits], axis=0)
        nul.append([cv[0], cv[1]] + [float(R[rn][a] @ Rsq[rn][np.ix_(pi, pi)][iu]) for rn in RSA]
                   + [float(fit_cca(P[a], Yp)[4].mean())])
    return np.array(nul)

def pmap(f, xs):
    try:
        ctx = mp.get_context('fork')
    except ValueError:
        return [f(x) for x in xs]
    with ctx.Pool(NPROC) as pool:
        return pool.map(f, xs, chunksize=1)

# ---------------- observed values, permutation nulls, bootstrap ----------------
SS = np.random.SeedSequence(SEED).spawn(10 + NBOOT)
rng_obs = np.random.default_rng(SS[0])
OBS, OBSKEEP = {}, {}
for p in PAN:
    OBS[p], OBSKEEP[p] = eval_all(PIDX[p], rng_obs, NSPLIT)
JOBS = [(p, pr, SS[1 + i]) for i, (p, pr) in enumerate([(p, pr) for p in PAN for pr in (MS, MG)])]
NUL = {(j[0], j[1]): z for j, z in zip(JOBS, pmap(one_perm, JOBS))}
BOOT = pmap(one_boot, [(s, i < NBOOT_SENS) for i, s in enumerate(SS[10:])])

# ---------------- assemble estimates ----------------
EST = []
def rnd(v): return None if v is None else float(f'{float(v):.4g}')
def add(name, value, lo=None, hi=None, how=''):
    EST.append({'name': name, 'value': rnd(value), 'ci_low': rnd(lo), 'ci_high': rnd(hi), 'method_of_uncertainty': how})
BH = f'gene bootstrap (unit = gene, B = {NBOOT}); 95% CI = est +/- 1.96 SE'
BHS = f'gene bootstrap (unit = gene, B = {NBOOT_SENS}); 95% CI = est +/- 1.96 SE'
def bci(name, f, how=BH, detail=False, reps=None):
    reps = BOOT if reps is None else reps
    v = f(OBS); bs = np.array([f(r) for r in reps]); se = bs.std(ddof=1)
    if detail:
        how = how + (f'; boot mean {bs.mean():.3g} (bias {bs.mean() - v:+.2g}); '
                     f'percentile CI [{np.percentile(bs, 2.5):.3g}, {np.percentile(bs, 97.5):.3g}]')
    add(name, v, v - 1.96 * se, v + 1.96 * se, how)
def get(rec, p, v, key, m):
    if p == 'pooled':
        return float(np.mean([rec[q][v][key][m] for q in PAN]))
    return float(rec[p][v][key][m])
LEV = PAN + ['pooled']

# (1) MaxToki table description
gi = np.array([mt[g] for g in GENES]); nM = np.linalg.norm(M[gi], axis=1); nG = np.linalg.norm(G[gi], axis=1)
coll = nM < 1e-2; CEN = 'exact census of the 20,271 gene rows; no sampling uncertainty'
add('maxtoki_collapsed_gene_rows_count', coll.sum(), None, None, CEN + ' (norm < 0.01)')
add('maxtoki_collapsed_gene_rows_median_norm', np.median(nM[coll]), None, None, CEN)
add('maxtoki_mask_token_row_norm', np.linalg.norm(M[mt['<mask>']]), None, None, 'exact; no sampling uncertainty')
add('maxtoki_gene_row_median_norm', np.median(nM), None, None, CEN)
add('maxtoki_collapsed_rows_in_panels_count', int(np.isin(gi[coll], [mt[g] for g in union]).sum()), None, None,
    'exact count; no sampling uncertainty')
rngv = np.random.default_rng(SS[7]); rv = spearmanr(nM, nG)[0]
bv = [spearmanr(nM[i], nG[i])[0] for i in (rngv.integers(0, len(gi), len(gi)) for _ in range(NBOOT_VOCAB))]
add('rownorm_spearman__MaxToki_Geneformer__vocabulary', rv, rv - 1.96 * np.std(bv, ddof=1), rv + 1.96 * np.std(bv, ddof=1),
    f'gene bootstrap over the 20,271 vocabulary genes (B = {NBOOT_VOCAB}); 95% CI = est +/- 1.96 SE')
for pr in PAIRS:
    for p in PAN:
        bci(f'rownorm_spearman__{PN[pr]}__{p}', lambda r, p=p, pr=pr: r[p]['norm_rho'][pr])
for m in BASE:
    for p in PAN:
        bci(f'top{K}_pc_variance_fraction__{m}__{p}', lambda r, p=p, m=m: get(r, p, 'base', 'var_frac', m))
rngs = np.random.default_rng(SS[8])
for p in PAN:
    fr = []
    for _ in range(NSIM):
        Z = rngs.standard_normal((len(PIDX[p]), M.shape[1])); Z -= Z.mean(0); ev = np.linalg.eigvalsh(Z @ Z.T)[::-1]
        fr.append(ev[:K].sum() / ev.sum())
    add(f'top{K}_pc_variance_fraction__iid_gaussian_reference__{p}', np.mean(fr), np.percentile(fr, 2.5),
        np.percentile(fr, 97.5), f'{NSIM} simulated i.i.d. Gaussian matrices of the same shape; 2.5-97.5 percentile range')
for m in BASE:
    for p in PAN:
        bci(f'euclidean_distance_radial_share__{m}__{p}', lambda r, p=p, m=m: get(r, p, 'base', 'radial_share', m))

# (2) main metrics, differences, ratios
for m in METRICS + ['radial_agreement']:
    for pr in PAIRS:
        for p in LEV:
            bci(f'{m}__{PN[pr]}__{p}', lambda r, p=p, pr=pr, m=m: get(r, p, 'base', pr, m))
for m in METRICS + ['radial_agreement']:
    for p in LEV:
        bci(f'diff_MG_minus_MS__{m}__{p}', lambda r, p=p, m=m: get(r, p, 'base', MG, m) - get(r, p, 'base', MS, m),
            'paired ' + BH, detail=True)
add('cv_top1_chance__pooled', get(OBS, 'pooled', 'base', MS, 'cv_top1_chance'), None, None,
    'exact chance level for the observed fold sizes; no sampling uncertainty')
for p in LEV:
    bci(f'ratio_MS_over_MG__cv_canonical_r__{p}',
        lambda r, p=p: get(r, p, 'base', MS, 'cv_canonical_r') / get(r, p, 'base', MG, 'cv_canonical_r'), 'paired ' + BH, detail=True)
bci('ratio_MS_over_MG__cosine_rsa__pooled',
    lambda r: get(r, 'pooled', 'base', MS, 'cosine_rsa') / get(r, 'pooled', 'base', MG, 'cosine_rsa'), 'paired ' + BH, detail=True)
def rexc(r):
    c = get(r, 'pooled', 'base', MS, 'cv_top1_chance')    # chance level of THIS replicate's folds (same for both pairs)
    return (get(r, 'pooled', 'base', MS, 'cv_top1_retrieval') - c) / (get(r, 'pooled', 'base', MG, 'cv_top1_retrieval') - c)
bci('ratio_MS_over_MG__cv_top1_retrieval_excess_over_chance__pooled', rexc,
    'paired ' + BH + '; chance recomputed per replicate', detail=True)

# (3) permutation tests
PH = f'one-sided permutation p, {NPERM} shuffles (floor {1 / (NPERM + 1):.4f}); no CI'
for pr in (MS, MG):
    for j, m in enumerate(METRICS):
        ps = []
        for p in PAN:
            o = OBS[p]['base'][pr][m]; nul = NUL[(p, pr)][:, j]
            ps.append((1 + (nul >= o).sum()) / (1 + NPERM))
            add(f'perm_p__{m}__{PN[pr]}__{p}', ps[-1], None, None, PH)
            add(f'perm_z__{m}__{PN[pr]}__{p}', (o - nul.mean()) / nul.std(ddof=1), None, None,
                'z vs permutation null (same fold splits as observed); no CI')
            if m in ('cv_top1_retrieval', 'insample_cca_r'):
                add(f'perm_null_mean__{m}__{PN[pr]}__{p}', nul.mean(), None, None, f'mean of {NPERM} permutations (chance level); no CI')
        add(f'fisher_combined_p__{m}__{PN[pr]}', combine_pvalues(ps, method='fisher')[1], None, None,
            'Fisher combination of 3 panel p-values (floor-bounded; panels overlap); no CI')

# (4) sensitivity variants (paired bootstrap CIs on the first NBOOT_SENS replicates)
SENS = ['cv_canonical_r', 'cv_top1_retrieval', 'cosine_rsa', 'euclidean_rsa', 'insample_cca_r']
BS_ = BOOT[:NBOOT_SENS]
for vn in VARIANTS:
    for m in SENS:
        for pr in (MS, MG):
            bci(f'sens_{vn}__{m}__{PN[pr]}__pooled', lambda r, vn=vn, pr=pr, m=m: get(r, 'pooled', vn, pr, m), BHS, reps=BS_)
        for p in LEV:
            bci(f'sens_{vn}__diff_MG_minus_MS__{m}__{p}', lambda r, vn=vn, p=p, m=m: get(r, p, vn, MG, m) - get(r, p, vn, MS, m),
                'paired ' + BHS, reps=BS_)
    bci(f'sens_{vn}__ratio_MS_over_MG__cv_canonical_r__pooled',
        lambda r, vn=vn: get(r, 'pooled', vn, MS, 'cv_canonical_r') / get(r, 'pooled', vn, MG, 'cv_canonical_r'),
        'paired ' + BHS, detail=True, reps=BS_)
for m in ['cosine_rsa', 'euclidean_rsa']:
    for pr in PAIRS:
        bci(f'sens_fulldim__{m}__{PN[pr]}__pooled', lambda r, pr=pr, m=m: get(r, 'pooled', 'fulldim', pr, m), BHS, reps=BS_)
    for p in LEV:
        bci(f'sens_fulldim__diff_MG_minus_MS__{m}__{p}', lambda r, p=p, m=m: get(r, p, 'fulldim', MG, m) - get(r, p, 'fulldim', MS, m),
            'paired ' + BHS, reps=BS_)
print('[\n' + ',\n'.join(json.dumps(e) for e in EST) + '\n]')

#!/usr/bin/env python
"""Is MaxToki-217M's gene-embedding geometry aligned with scGPT's, and how does that compare with its alignment
to Geneformer V2-316M?  H24-style whitened CCA on PCA-20 token-embedding tables, evaluated out of sample, plus
fit-free RSA metrics; union-wide gene-correspondence permutation null (every statistic recomputed exactly as
observed); gene bootstrap (B = 1000, same estimator in every replicate); norm-stratified nulls; noise-degradation
calibration of effect sizes; random-vocabulary control; per-panel sensitivity analyses with paired bootstrap CIs.
Run from the package root:  python analysis.py   -> prints every reported estimate as JSON on stdout.
CPU only; fork-based pool of up to 9 worker processes (about 4-9 minutes, depending on machine load)."""
import os
for _v in ('OPENBLAS_NUM_THREADS', 'OMP_NUM_THREADS', 'MKL_NUM_THREADS', 'VECLIB_MAXIMUM_THREADS'):
    os.environ.setdefault(_v, '1')
import json, sys, time, multiprocessing as mp
import numpy as np, pandas as pd
from scipy.linalg import eigh
from scipy.spatial.distance import squareform

SEED = 20261001; K = 20; NFOLD = 5; NSPLIT = 5; NDIST = 2
NPERM = 500; NBOOT = 1000; NBOOT_SENS = 100; NSTRAT = 100; NVOCAB = 20; NNOISE = 4
NOISE_F = np.round(np.arange(0, 0.601, 0.05), 2); KDIST = (5, 10)
NWORK = max(1, min(9, (os.cpu_count() or 2) - 1))
D = 'data/'
# ---------------- load tables, dictionaries, gene mapping ----------------
M = np.load(D + 'maxtoki_217m/embed_tokens.npy')
G = np.load(D + 'geneformer_v2_316m/word_embeddings.npy')
S = np.load(D + 'scgpt_whole_human/encoder_embedding_weight.npy')
LN = np.load(D + 'scgpt_whole_human/encoder_enc_norm.npz')
mt = json.load(open(D + 'maxtoki_217m/token_dictionary.json'))
gf = json.load(open(D + 'geneformer_v2_316m/token_dictionary.json'))
sv = json.load(open(D + 'scgpt_whole_human/vocab.json'))
es = pd.read_csv(D + 'gene_ids/ensembl_symbol.csv'); e2s = dict(zip(es.ensembl_id, es.symbol))
PAN = ['lung', 'immune', 'external_lung']
panels = {p: pd.read_csv(D + f'panels/{p}.csv').ensembl_id.tolist() for p in PAN}
union = sorted(set().union(*panels.values())); uidx = {g: i for i, g in enumerate(union)}
PIDX = {p: np.array([uidx[g] for g in panels[p]]) for p in PAN}
assert all(g in mt and g in gf and e2s.get(g) in sv for g in union)   # every panel gene maps in all 3 vocabularies
assert all(mt[g] == gf[g] for g in union)                               # MaxToki and Geneformer share token ids

def layernorm(X):  # scGPT gene-encoder output = enc_norm(embedding(token))
    mu = X.mean(1, keepdims=True); var = X.var(1, keepdims=True)
    return (X - mu) / np.sqrt(var + float(LN['eps'])) * LN['weight'] + LN['bias']

Xs_raw = S[[sv[e2s[g]] for g in union]].astype(np.float64)
BASE = {'MaxToki': M[[mt[g] for g in union]].astype(np.float64),
        'Geneformer': G[[gf[g] for g in union]].astype(np.float64),
        'scGPT': layernorm(Xs_raw)}
GRAM = {m: X @ X.T for m, X in BASE.items()}
NORM = {'MaxToki': np.linalg.norm(BASE['MaxToki'], axis=1), 'Geneformer': np.linalg.norm(BASE['Geneformer'], axis=1),
        'scGPT_raw': np.linalg.norm(Xs_raw, axis=1)}                   # raw row norms (token-frequency proxies)
PAIRS = [('MaxToki', 'scGPT'), ('MaxToki', 'Geneformer'), ('Geneformer', 'scGPT')]
MS, MG, GS = PAIRS
PN = {MS: 'MaxToki_scGPT', MG: 'MaxToki_Geneformer', GS: 'Geneformer_scGPT'}
DISTM = [f'cv_ccaspace_dist_rsa_k{k}' for k in KDIST]
METRICS = (['cv_canonical_r', 'cv_top1_retrieval', 'cosine_rsa'] + DISTM
           + ['whitened_euclidean_rsa', 'euclidean_rsa', 'insample_cca_r', 'insample_cca_r_top10'])
DECM = ['cv_canonical_r', 'cv_top1_retrieval', 'cosine_rsa', 'cv_ccaspace_dist_rsa_k5']
SENSM = ['cv_canonical_r', 'cv_top1_retrieval', 'cosine_rsa', 'euclidean_rsa', 'insample_cca_r']

# ---------------- building blocks ----------------
def pca_scores(GR, d, u, k):
    """PCA basis fitted on the UNIQUE genes u (Gram-matrix form); scores returned for rows d (may repeat)."""
    Kuu = GR[np.ix_(u, u)]; Kdu = GR[np.ix_(d, u)]
    cm = Kuu.mean(0); gm = Kuu.mean(); n = len(u)
    w, V = eigh(Kuu - cm[None, :] - cm[:, None] + gm, subset_by_index=[n - k, n - 1], driver='evr')
    w = np.maximum(w[::-1], 1e-12); V = V[:, ::-1]
    return (Kdu - Kdu.mean(1)[:, None] - cm[None, :] + gm) @ V / np.sqrt(w)

def cca_r(X, Y):  # in-sample canonical correlations of whitened CCA (SVD of the product of orthonormal bases)
    Ux = np.linalg.svd(X - X.mean(0), full_matrices=False)[0]; Uy = np.linalg.svd(Y - Y.mean(0), full_matrices=False)[0]
    return np.linalg.svd(Ux.T @ Uy, compute_uv=False)

def rvec(x):
    """Centred unit-length vector of average ranks, so Spearman(x, y) = rvec(x) @ rvec(y)."""
    o = np.argsort(x); xs = x[o]
    b = np.flatnonzero(np.r_[True, xs[1:] != xs[:-1], True])
    r = np.empty(len(x)); r[o] = np.repeat((b[:-1] + b[1:] + 1) / 2.0, np.diff(b))
    r -= r.mean(); return r / np.sqrt(r @ r)

def sqdist(X):  # squared Euclidean distances (rank-equivalent to Euclidean)
    q = (X ** 2).sum(1); return np.maximum(q[:, None] + q[None, :] - 2 * X @ X.T, 0)

def rsa_vecs(X, keep, white=False):
    """Rank vectors of pairwise centred-cosine and Euclidean distances (and Euclidean on standardised PC scores,
    which equals distance in the CCA space with all components)."""
    iu = np.triu_indices(len(X), 1); Xn = X / np.linalg.norm(X, axis=1, keepdims=True)
    R = {'cos': rvec((1 - Xn @ Xn.T)[iu][keep]), 'euc': rvec(sqdist(X)[iu][keep])}
    if white:
        R['wht'] = rvec(sqdist(X / X.std(0))[iu][keep])
    return R

def cv_multi(P, pairs, gid, splits, dist=True):
    """Repeated 5-fold CV of whitened CCA for model pairs sharing the same folds.  On held-out genes: mean canonical
    correlation over all components and top-1 retrieval (cosine, both directions), averaged over all splits; if dist,
    Spearman of pairwise Euclidean distances in the top-k canonical space (k = 5, 10), averaged over the first NDIST
    splits (the same rule is used for observed, null and bootstrap statistics)."""
    acc = {pr: [] for pr in pairs}; accd = {pr: [] for pr in pairs}; models = sorted({m for pr in pairs for m in pr})
    for si, foldof in enumerate(splits):
        dd = dist and si < NDIST
        for f in range(NFOLD):
            te = foldof == f; tr = ~te; g = gid[te]; sv_ = {}
            for m in models:
                mu = P[m][tr].mean(0); U, s, Vt = np.linalg.svd(P[m][tr] - mu, full_matrices=False); sv_[m] = (mu, U, s, Vt)
            if dd:
                iu = np.triu_indices(len(g), 1); keep = g[iu[0]] != g[iu[1]]
            for a, b in pairs:
                mx, Ux, sx, Vx = sv_[a]; my, Uy, sy, Vy = sv_[b]
                A, _, Bt = np.linalg.svd(Ux.T @ Uy)
                ea = (P[a][te] - mx) @ ((Vx.T / sx) @ A); eb = (P[b][te] - my) @ ((Vy.T / sy) @ Bt.T)
                ac = ea - ea.mean(0); bc = eb - eb.mean(0)
                sim = (ea / np.linalg.norm(ea, axis=1, keepdims=True)) @ (eb / np.linalg.norm(eb, axis=1, keepdims=True)).T
                acc[(a, b)].append([np.mean((ac * bc).sum(0) / np.sqrt((ac ** 2).sum(0) * (bc ** 2).sum(0))),
                                    0.5 * ((g[sim.argmax(1)] == g).mean() + (g[sim.argmax(0)] == g).mean())])
                if dd:
                    accd[(a, b)].append([float(rvec(sqdist(ea[:, :k])[iu][keep]) @ rvec(sqdist(eb[:, :k])[iu][keep])) for k in KDIST])
    return {pr: np.r_[np.mean(acc[pr], 0), np.mean(accd[pr], 0) if accd[pr] else []] for pr in pairs}

def folds_for(gid, rng):  # folds assigned per gene, so bootstrap copies of a gene stay together
    ug = np.unique(gid); fa = rng.permutation(len(ug)) % NFOLD
    return fa[np.searchsorted(ug, gid)]

def finish(P, R, pairs, gid, splits, dist=True):
    cv = cv_multi(P, pairs, gid, splits, dist); out = {}
    for a, b in pairs:
        r = cca_r(P[a], P[b])
        o = {'cv_canonical_r': cv[(a, b)][0], 'cv_top1_retrieval': cv[(a, b)][1], 'cosine_rsa': float(R[a]['cos'] @ R[b]['cos']),
             'euclidean_rsa': float(R[a]['euc'] @ R[b]['euc']), 'insample_cca_r': float(r.mean()), 'insample_cca_r_top10': float(r[:10].mean())}
        if dist:
            o.update({m: cv[(a, b)][2 + i] for i, m in enumerate(DISTM)})
            o['whitened_euclidean_rsa'] = float(R[a]['wht'] @ R[b]['wht'])
        out[(a, b)] = o
    return out

def panel_eval(GRAMS, d, rng, nsplit=NSPLIT, k=K, dist=True, pairs=PAIRS, keepP=False):
    u = np.unique(d)
    P = {m: pca_scores(GRAMS[m], d, u, k) for m in sorted({m for pr in pairs for m in pr})}
    iu = np.triu_indices(len(d), 1); keep = d[iu[0]] != d[iu[1]]              # drop pairs of copies of one gene
    R = {m: rsa_vecs(P[m], keep, dist) for m in P}
    out = finish(P, R, pairs, d, [folds_for(d, rng) for _ in range(nsplit)], dist)
    return (out, P, R) if keepP else out

def fulldim_eval(E, d):  # no PCA: RSA on the full embeddings centred on the (unique) panel genes
    u = np.unique(d); iu = np.triu_indices(len(d), 1); keep = d[iu[0]] != d[iu[1]]
    R = {m: rsa_vecs(X[d] - X[u].mean(0), keep) for m, X in E.items()}
    return {pr: {'cosine_rsa': float(R[pr[0]]['cos'] @ R[pr[1]]['cos']),
                 'euclidean_rsa': float(R[pr[0]]['euc'] @ R[pr[1]]['euc'])} for pr in PAIRS}

def stat(rec, p, pair, m):
    return float(np.mean([rec[q][pair][m] for q in PAN])) if p == 'pooled' else float(rec[p][pair][m])

def rown(X): return X / np.linalg.norm(X, axis=1, keepdims=True)
VAR = {'scgpt_no_layernorm': ({'MaxToki': GRAM['MaxToki'], 'Geneformer': GRAM['Geneformer'], 'scGPT': Xs_raw @ Xs_raw.T}, K),
       'pca10': (GRAM, 10), 'pca50': (GRAM, 50),
       'row_l2_normalised': ({m: rown(X) @ rown(X).T for m, X in BASE.items()}, K)}

# ---------------- observed values (computed before the worker pool forks) ----------------
rng0 = np.random.default_rng([SEED, 0])
OBS, OBS_P, OBS_R = {}, {}, {}
for p in PAN:
    OBS[p], OBS_P[p], OBS_R[p] = panel_eval(GRAM, PIDX[p], rng0, keepP=True)
OBS_SENS = {vn: {p: panel_eval(GR, PIDX[p], rng0, k=k, dist=False, pairs=PAIRS[:2]) for p in PAN} for vn, (GR, k) in VAR.items()}
OBS_FD = {p: fulldim_eval(BASE, PIDX[p]) for p in PAN}
OBS_RSQ = {p: {m: squareform(OBS_R[p][m]['cos']) for m in ('scGPT', 'Geneformer')} for p in PAN}

# ---------------- worker tasks ----------------
def boot_draw(i):  # gene bootstrap: resample the 828-gene union; each panel keeps its drawn genes
    draw = np.random.default_rng([SEED, 2, i]).integers(0, len(union), len(union))
    return {p: draw[np.isin(draw, PIDX[p])] for p in PAN}

def boot_task(i):
    rng = np.random.default_rng([SEED, 3, i]); dd = boot_draw(i)
    return {p: panel_eval(GRAM, dd[p], rng) for p in PAN}

def sens_task(i):  # same gene draws as boot_task(i), for the sensitivity variants and the no-PCA RSA
    rng = np.random.default_rng([SEED, 4, i]); dd = boot_draw(i)
    out = {vn: {p: panel_eval(GR, dd[p], rng, k=k, dist=False, pairs=PAIRS[:2]) for p in PAN} for vn, (GR, k) in VAR.items()}
    out['fulldim'] = {p: fulldim_eval(BASE, dd[p]) for p in PAN}
    return out

def perm_task(i):
    """Union-wide null: the partner models' rows are permuted across the 828 union genes (one permutation shared by
    all panels, so panel overlap is respected); partner PCA, RSA and the repeated CV are recomputed as observed."""
    rng = np.random.default_rng([SEED, 1, i]); pi = rng.permutation(len(union)); res = {}
    for p in PAN:
        d = PIDX[p]; db = pi[d]; allp = np.ones(len(d) * (len(d) - 1) // 2, bool)
        P = {'MaxToki': OBS_P[p]['MaxToki']}; R = {'MaxToki': OBS_R[p]['MaxToki']}
        for b in ('scGPT', 'Geneformer'):
            P[b] = pca_scores(GRAM[b], db, np.unique(db), K); R[b] = rsa_vecs(P[b], allp, True)
        res[p] = finish(P, R, [MS, MG], d, [folds_for(d, rng) for _ in range(NSPLIT)])
    return res

def noise_task(args):
    """Calibration: a fraction f of the variance of every Geneformer PC is replaced by independent Gaussian noise."""
    pi_, fi, rep = args; p = PAN[pi_]; f = NOISE_F[fi]; d = PIDX[p]
    rng = np.random.default_rng([SEED, 5, pi_, fi, rep])
    Pg = OBS_P[p]['Geneformer']; Pn = np.sqrt(1 - f) * Pg + np.sqrt(f) * rng.standard_normal(Pg.shape) * Pg.std(0)
    P = {'MaxToki': OBS_P[p]['MaxToki'], 'Geneformer': Pn}
    R = {'MaxToki': OBS_R[p]['MaxToki'], 'Geneformer': rsa_vecs(Pn, np.ones(len(d) * (len(d) - 1) // 2, bool), True)}
    return finish(P, R, [MG], d, [folds_for(d, rng) for _ in range(NSPLIT)])[MG]

VOCAB = sorted(g for g in mt if g.startswith('ENSG') and g in gf and e2s.get(g) in sv)
def vocab_task(i):
    """Random-vocabulary control: 380 genes drawn at random from all genes present in all three vocabularies."""
    rng = np.random.default_rng([SEED, 6, i]); gs = [VOCAB[j] for j in rng.choice(len(VOCAB), 380, replace=False)]
    E = {'MaxToki': M[[mt[g] for g in gs]].astype(np.float64), 'Geneformer': G[[gf[g] for g in gs]].astype(np.float64),
         'scGPT': layernorm(S[[sv[e2s[g]] for g in gs]].astype(np.float64))}
    return panel_eval({m: X @ X.T for m, X in E.items()}, np.arange(380), rng, dist=False)

STRAT_COV = ['MaxToki', 'Geneformer', 'scGPT_raw']        # stratifying covariate = raw row norm of this table
def strat_task(args):
    """Norm-stratified null: partner rows are shuffled only among panel genes in the same decile of a raw-row-norm
    covariate (token-frequency proxy), so alignment carried by that gene-level scalar is kept in the null."""
    ci, pi_, i = args; p = PAN[pi_]; d = PIDX[p]; n = len(d)
    rng = np.random.default_rng([SEED, 7, ci, pi_, i])
    st = np.argsort(np.argsort(NORM[STRAT_COV[ci]][d])) * 10 // n; perm = np.arange(n)
    for s in range(10):
        idx = np.where(st == s)[0]; perm[idx] = rng.permutation(idx)
    pairs = [MS] if STRAT_COV[ci] == 'scGPT_raw' else [MS, MG]
    P = {'MaxToki': OBS_P[p]['MaxToki']}; P.update({b: OBS_P[p][b][perm] for _, b in pairs})
    cv = cv_multi(P, pairs, d, [folds_for(d, rng) for _ in range(NSPLIT)]); iu = np.triu_indices(n, 1)
    return {pr: [cv[pr][0], cv[pr][1], float(OBS_R[p]['MaxToki']['cos'] @ OBS_RSQ[p][pr[1]][np.ix_(perm, perm)][iu]), cv[pr][2]]
            for pr in pairs}

def run_task(t):
    kind, a = t
    return kind, a, {'boot': boot_task, 'sens': sens_task, 'perm': perm_task, 'noise': noise_task,
                     'vocab': vocab_task, 'strat': strat_task}[kind](a)

# ---------------- reporting helpers ----------------
EST = []
def rnd(v): return None if v is None else float(f'{float(v):.4g}')
def add(name, value, lo=None, hi=None, how=''):
    EST.append({'name': name, 'value': rnd(value), 'ci_low': rnd(lo), 'ci_high': rnd(hi), 'method_of_uncertainty': how})
def nci(v, bs):  # normal-approximation 95% interval around the full-sample estimate
    s = np.std(bs, ddof=1); return v - 1.96 * s, v + 1.96 * s
def pci(v, bs):  # bootstrap percentile interval shifted to centre on the full-sample estimate
    return tuple(np.percentile(bs, [2.5, 97.5]) - np.median(bs) + v)

if __name__ == '__main__':
    T0 = time.time()
    tasks = ([('sens', i) for i in range(NBOOT_SENS)] + [('boot', i) for i in range(NBOOT)] + [('perm', i) for i in range(NPERM)]
             + [('vocab', i) for i in range(NVOCAB)] + [('strat', (a, b, i)) for a in range(3) for b in range(3) for i in range(NSTRAT)]
             + [('noise', (a, b, c)) for a in range(3) for b in range(len(NOISE_F)) for c in range(NNOISE)])
    RES = {k: {} for k in ('boot', 'sens', 'perm', 'noise', 'vocab', 'strat')}
    with mp.get_context('fork').Pool(NWORK) as pool:
        for kind, a, r in pool.imap_unordered(run_task, tasks, chunksize=1):
            RES[kind][a] = r
    print(f'compute time {time.time() - T0:.0f} s', file=sys.stderr)
    BOOT = [RES['boot'][i] for i in range(NBOOT)]; SENS = [RES['sens'][i] for i in range(NBOOT_SENS)]
    PERM = [RES['perm'][i] for i in range(NPERM)]

    # ---- main estimates: per panel and pooled (mean of the 3 panels); 95% CI from the gene bootstrap ----
    BH = f'gene bootstrap (unit = gene, B={NBOOT}, same estimator in every replicate); 95% CI = est +/- 1.96 SE'
    for m in METRICS:
        for pair in PAIRS:
            for p in PAN + ['pooled']:
                v = stat(OBS, p, pair, m); add(f'{m}__{PN[pair]}__{p}', v, *nci(v, [stat(r, p, pair, m) for r in BOOT]), BH)
        for p in PAN + ['pooled']:
            v = stat(OBS, p, MG, m) - stat(OBS, p, MS, m); bs = [stat(r, p, MG, m) - stat(r, p, MS, m) for r in BOOT]
            add(f'diff_MaxTokiGeneformer_minus_MaxTokiscGPT__{m}__{p}', v, *nci(v, bs), 'paired ' + BH)
            if p == 'pooled' and m in DECM:
                add(f'diff_MaxTokiGeneformer_minus_MaxTokiscGPT__{m}__pooled__percentile_ci', v, *pci(v, bs),
                    f'paired gene bootstrap (B={NBOOT}); percentile interval re-centred on the estimate')
    # ---- union-wide permutation null: p-values and chance levels ----
    PH = f'one-sided permutation p, {NPERM} union-wide shuffles, statistic recomputed as observed (floor {1 / (NPERM + 1):.4f}); no CI'
    NULL = {}
    for pair in (MS, MG):
        for m in METRICS:
            for p in PAN + ['pooled']:
                nv = np.array([stat(r, p, pair, m) for r in PERM]); NULL[(pair, m, p)] = nv
                if p == 'pooled' or m in DECM:
                    add(f'perm_p__{m}__{PN[pair]}__{p}', (1 + (nv >= stat(OBS, p, pair, m)).sum()) / (1 + NPERM), None, None, PH)
            if m in ('cv_canonical_r', 'cv_top1_retrieval', 'insample_cca_r'):
                add(f'perm_null_mean__{m}__{PN[pair]}__pooled', NULL[(pair, m, 'pooled')].mean(), None, None,
                    f'mean of {NPERM} union-wide permutations (chance level); no CI')
    # ---- MS / MG ratios (pooled) ----
    chance = float(np.mean([NULL[(pr, 'cv_top1_retrieval', 'pooled')].mean() for pr in (MS, MG)]))
    RATIO = {}
    for m, c in [('cv_canonical_r', 0.0), ('cv_top1_retrieval', chance), ('cv_top1_retrieval_raw', 0.0), ('cosine_rsa', 0.0),
                 ('cv_ccaspace_dist_rsa_k5', 0.0), ('cv_ccaspace_dist_rsa_k10', 0.0)]:
        mm = m.replace('_raw', '')
        f = lambda rec: (stat(rec, 'pooled', MS, mm) - c) / (stat(rec, 'pooled', MG, mm) - c)
        v = f(OBS); bs = np.array([f(r) for r in BOOT]); RATIO[m] = (v, *nci(v, bs))
        add(f'ratio_MaxTokiscGPT_over_MaxTokiGeneformer__{m}__pooled', *RATIO[m],
            'paired ' + BH + ('; ratio of excess over permutation chance' if c else ''))
        add(f'ratio_MaxTokiscGPT_over_MaxTokiGeneformer__{m}__pooled__percentile_ci', v, *pci(v, bs),
            f'paired gene bootstrap (B={NBOOT}); percentile interval re-centred on the estimate')
    # ---- noise-degradation calibration: express each gap as an equivalent noise fraction ----
    for m in ['cv_canonical_r', 'cv_top1_retrieval_raw', 'cosine_rsa', 'cv_ccaspace_dist_rsa_k5', 'cv_ccaspace_dist_rsa_k10']:
        mm = m.replace('_raw', '')
        curve = np.array([np.mean([RES['noise'][(a, fi, c)][mm] for a in range(3) for c in range(NNOISE)]) for fi in range(len(NOISE_F))])
        rho = np.minimum.accumulate(curve / curve[0])
        fstar = lambda x: float(np.interp(x, rho[::-1], NOISE_F[::-1]))
        v, lo, hi = RATIO[m]
        add(f'noise_equivalent_fraction__{m}__pooled', fstar(v), fstar(hi), fstar(lo),
            f'calibration curve ({NNOISE} noise draws x 3 panels, f = 0-{NOISE_F[-1]}); CI = paired-bootstrap ratio CI mapped through the curve')
        add(f'noise_fraction_at_ratio_0.8__{m}__pooled', fstar(0.8), None, None, 'calibration curve; no CI')
    # ---- norm-stratified nulls ----
    SCHEME = {'maxtoki_norm': (0, 0), 'geneformer_norm': (1, 1), 'partner_norm': (2, 1)}   # covariate index used for (MS, MG)
    for sn, (cs, cg) in SCHEME.items():
        for j, m in enumerate(DECM):
            nm = {}
            for pair, ci in ((MS, cs), (MG, cg)):
                arr = {p: np.array([RES['strat'][(ci, pi_, i)][pair][j] for i in range(NSTRAT)]) for pi_, p in enumerate(PAN)}
                nm[pair] = float(np.mean([arr[p].mean() for p in PAN]))
                if sn != 'partner_norm' or pair == MS:
                    add(f'strat_null_mean__{sn}__{m}__{PN[pair]}__pooled', nm[pair], None, None, f'mean of {NSTRAT} within-decile shuffles per panel; no CI')
                    add(f'strat_perm_p_max_over_panels__{sn}__{m}__{PN[pair]}',
                        max((1 + (arr[p] >= stat(OBS, p, pair, m)).sum()) / (1 + NSTRAT) for p in PAN), None, None,
                        f'largest per-panel one-sided p vs the stratified null ({NSTRAT} shuffles; floor {1 / (NSTRAT + 1):.4f}); no CI')
            v = (stat(OBS, 'pooled', MG, m) - nm[MG]) - (stat(OBS, 'pooled', MS, m) - nm[MS])
            s = np.std([stat(r, 'pooled', MG, m) - stat(r, 'pooled', MS, m) for r in BOOT], ddof=1)
            add(f'strat_excess_gap_MG_minus_MS__{sn}__{m}__pooled', v, v - 1.96 * s, v + 1.96 * s,
                'gap in excess over stratified-null means; CI = est +/- 1.96 x paired-bootstrap SE of the raw gap')
    # ---- sensitivity analyses: paired bootstrap CI for the difference, per panel and pooled ----
    SH = f'paired gene bootstrap (B={NBOOT_SENS}, same estimator); 95% CI = est +/- 1.96 SE'
    for vn in VAR:
        for m in SENSM:
            for pair in (MS, MG):
                add(f'sens_{vn}__{m}__{PN[pair]}__pooled', stat(OBS_SENS[vn], 'pooled', pair, m), None, None, 'point estimate; CI given for the paired difference')
            for p in PAN + ['pooled']:
                v = stat(OBS_SENS[vn], p, MG, m) - stat(OBS_SENS[vn], p, MS, m)
                add(f'sens_{vn}__diff_MG_minus_MS__{m}__{p}', v, *nci(v, [stat(r[vn], p, MG, m) - stat(r[vn], p, MS, m) for r in SENS]), SH)
    for m in ('cosine_rsa', 'euclidean_rsa'):
        for p in PAN + ['pooled']:
            for pair in PAIRS:
                v = stat(OBS_FD, p, pair, m); add(f'sens_fulldim_{m}__{PN[pair]}__{p}', v, *nci(v, [stat(r['fulldim'], p, pair, m) for r in SENS]), SH)
            v = stat(OBS_FD, p, MG, m) - stat(OBS_FD, p, MS, m)
            add(f'sens_fulldim_diff_MG_minus_MS__{m}__{p}', v, *nci(v, [stat(r['fulldim'], p, MG, m) - stat(r['fulldim'], p, MS, m) for r in SENS]), SH)
    # ---- random-vocabulary control ----
    VO = [RES['vocab'][i] for i in range(NVOCAB)]
    VH = f'mean over {NVOCAB} random 380-gene sets ({len(VOCAB)} eligible genes); interval = 2.5-97.5 percentiles across sets'
    for m in SENSM[:4]:
        for pair in PAIRS:
            x = np.array([r[pair][m] for r in VO]); add(f'random_vocab__{m}__{PN[pair]}', x.mean(), *np.percentile(x, [2.5, 97.5]), VH)
        if m != 'euclidean_rsa':
            c = 1 / 76 if m == 'cv_top1_retrieval' else 0.0
            x = np.array([(r[MS][m] - c) / (r[MG][m] - c) for r in VO])
            add(f'random_vocab__ratio_MaxTokiscGPT_over_MaxTokiGeneformer__{m}', x.mean(), *np.percentile(x, [2.5, 97.5]),
                VH + ('; excess over chance 1/76' if c else ''))
    # ---- spectrum diagnostics (data section) ----
    rs = np.random.default_rng([SEED, 8])
    def top20(X): s = np.linalg.svd(X - X.mean(0), compute_uv=False); return (s[:20] ** 2).sum() / (s ** 2).sum()
    for p in PAN:
        for mname, X in BASE.items():
            add(f'top20_pca_variance_fraction__{mname}__{p}', top20(X[PIDX[p]]), None, None, 'descriptive; no CI')
        add(f'top20_pca_variance_fraction__random_N(0,0.02^2)_1232d__{p}', np.mean([top20(rs.normal(0, 0.02, (len(PIDX[p]), 1232))) for _ in range(5)]),
            None, None, 'mean of 5 random matrices of the panel shape; descriptive; no CI')
        add(f'median_row_norm__MaxToki__{p}', np.median(NORM['MaxToki'][PIDX[p]]), None, None, 'descriptive (0.702 expected at initialisation); no CI')
    print(f'total time {time.time() - T0:.0f} s; {len(EST)} estimates', file=sys.stderr)
    print('[\n' + ',\n'.join(json.dumps(e) for e in EST) + '\n]')

points.description:
Several numbers in the report are not produced by the delivered script, so they cannot be reproduced from it. These are:
- the bootstrap SEs (0.0052/0.0046/0.0041) and the bootstrap centre of 0.59;
- the top-20 PC variance figures;
- the token-id |rho| <= 0.025 check;
- the median norm;
- the 5-to-all-components sweep cited to dismiss the Euclidean metric.
One small inaccuracy: scGPT's top-20 variance on the lung panel is 35.0%, not 34%.

review_generic.summary:
Rerunning the delivered pipeline reproduces every reported estimate, CI and permutation result exactly. Alignment of MaxToki with scGPT beyond chance is solid on every tested metric. Two of the checks I ran support the analyst's choice of metric:
- Per-gene (norm-like) effects do not drive the centred-cosine RSA; removing them barely changes it (0.244 vs 0.243).
- The dimension sweep behaves as described.

The problem is the verdict 'clearly less than with Geneformer'. It depends on centred-cosine RSA, a metric outside the SPEC that was chosen, along with the 0.9 threshold, after the point estimates were seen. Applying the analyst's own rule to the SPEC's headline H24 metric (CCA mean r) gives 'inconclusive':
- held-out ratio 0.84 [0.71, 0.97];
- in-sample ratio 0.92 [0.86, 0.98];
- null-excess ratio 0.85 [0.79, 0.91].

The SPEC's distance-Spearman reverses direction or gives mixed results. Procrustes, PCA-10 and per-panel CCA differences are not significant.

The partial-RSA claim of a MaxToki–Geneformer-specific component cannot be identified from the data. A one-factor model fits exactly, which means the ratio of 0.69 may simply reflect scGPT matching the shared geometry less closely than Geneformer does.

Minor issues:
- jackknife calibration for statistics that depend on panel size;
- pooled CIs that ignore heterogeneity between panels;
- incorrect zero-row and 'near initialisation' statements about the MaxToki table;
- H17 cited out of context;
- numbers in the report that the script does not compute.

